var ZAIKA_EXTRA_HI={"biryani":{"intro":"बिरयानी वो खाना है जो अक्सर मेहमानों और खुशी के मौकों पर बनती है, और कराची स्टाइल अपने तेज़ मसाले, अलग-अलग चावल और दम की खुशबू के लिए मशहूर है जो ढक्कन उठने से पहले पूरे घर में फैल जाती है। नीचे दिया तरीक़ा चिकन को जूसी और चावल को खुशबूदार रखता है, और तहों को एक नरम लुगदी नहीं बनने देता। मैरीनेशन ही असल ज़ायका बनाती है, इसलिए पकाना ज़्यादा तर तह लगाना और इंतज़ार करना है। इसे पतीले से सीधे परोसें, रायता और सलाद के साथ, जब तक भाप निकल रही हो।","ing":["चिकन 750g","दही 1 कप","बासमती चावल 3 कप (भिगोए हुए)","बिरयानी मसाला 3 tbsp","अदरक-लहसुन पेस्ट 2 tbsp","प्याज़ 3 (ब्राउन की हुई)","टमाटर 2","हरी मिर्च 4","हरा धनिया","पुदीना","नींबू","केसर / फ़ूड कलर","घी 3 tbsp","नमक","तेजपत्ता","इलायची","लौंग (चावल के पानी के लिए)"],"steps":["चावल को साफ़ पानी आने तक धो कर 30 मिनट भिगो दें, फिर छान लें। दही, बिरयानी मसाला, अदरक-लहसुन पेस्ट और नमक चिकन में मिला कर 30 मिनट मैरीनेट करें।","एक बड़े बर्तन में नमक और साबुत मसालों के साथ पानी उबालें। चावल डाल कर 70 प्रतिशत तक पकाएँ, बीच में सख्त रहे, फिर फ़ौरन छान लें।","घी गरम कर के प्याज़ को गहरा सुनहरा होने तक ब्राउन करें, आधी तह लगाने के लिए निकाल लें, बाकी पैन में रहने दें।","टमाटर और मैरीनेट किया चिकन डाल कर मध्यम तेज़ आंच पर 10 से 12 मिनट भूनें, जब तक मसाला गाढ़ा हो जाए और तेल अलग नज़र आए।","चिकन मसाला एक भारी पतीले में फैला दें। आधे चावल डालें, फिर धनिया, पुदीना, ब्राउन प्याज़, नींबू और केसर छिड़कें।","बाकी चावल डालें, ऊपर बाकी प्याज़, जड़ी-बूटी और केसर और एक चम्मच घी डालें। ढक्कन को कपड़े या फ़ॉइल से बंद करें।","हल्की आंच पर 20 मिनट दम दें, ढक्कन न खोलें, फिर आंच से उतार कर 10 मिनट आराम दें।","ढक्कन खोलें, काँटे से किनारों से हल्के हाथ से फुलाएँ, हल्का मिलाएँ ताकि रंग नज़र आते रहें, और गरम परोसें।"],"tip":"चावल ज़्यादा न उबालें। वो दम पर पक जाएँगे। दम पर ढक्कन पर कपड़ा रखें ताकि भाप बाहर न निकले, और चावल का पानी चखें। वो हल्का नमकीन होना चाहिए, क्योंकि सादे चावल को इस नमक की ज़रूरत होती है।","notes":["हड्डी वाला चिकन दम पर ज़्यादा जूसी रहता है। लेग पीस लें और ज़्यादा चर्बी हटा दें।","पुरानी बासमती के दाने अलग रहते हैं। नया चावल जल्दी नरम हो जाता है, इसलिए उबालने का समय देखें।","फुल फैट दही मैरीनेड को चिकन पर चिपका देती है। लो फैट दही गरम होने पर फट सकती है।","बिरयानी मसाला हर ब्रांड का अलग होता है। ज़्यादा मिर्च डालने से पहले मसाला चखें, और अगली बार ठीक करें।"],"variations":["सब्ज़ी बिरयानी: चिकन की जगह आलू, फूलगोभी, मटर और गाजर लें, सब्ज़ियों को हल्का मैरीनेट करें, और दम 15 मिनट कर दें।","मटन बिरयानी: 750g मटन लें, तह लगाने से पहले मसाला इतना पकाएँ कि गोश्त तक़रीबन गल जाए, और 30 मिनट दम दें।","कम मिर्च वाली: हरी मिर्च आधी कर दें, ज़्यादा लाल मिर्च न डालें, और ज़्यादा रायते के साथ परोसें।"],"serving":"4 लोगों के लिए रायता, कचूमर सलाद और नींबू के साथ काफ़ी है। पतीला मेज़ के बीच में रखें और वहीं खोलें, ताकि सब को दम की खुशबू मिले। नान ज़रूरी नहीं, क्योंकि चावल ही असल खाना है। लस्सी या पुदीने का ड्रिंक मिर्च को बैलेंस करता है।","storage":"1 घंटे के अंदर ठंडा कर के एयरटाइट डिब्बे में फ्रिज में 2 दिन तक रखें। ढकी हुई कड़ाही में हल्की आंच पर 2 tbsp पानी के साथ दोबारा गरम करें, या माइक्रोवेव में ढक कर गरम करें, जब तक पूरी तरह भाप न निकले। एक बार से ज़्यादा दोबारा गरम न करें। हिस्सों में फ्रीज़ कर के 1 महीने तक रखें, और गरम करने से पहले फ्रिज में रात भर थॉ करें।","mistakes":["दम से पहले चावल पूरा उबाल लेना। वो पतीले में नरम हो जाता है।","दम के दौरान ढक्कन खोलना। भाप निकल जाती है और चावल कच्चा रह जाता है।","चावल के पानी में नमक कम रखना। तहें फीकी लगती हैं।","दम के बाद ज़ोर से हिलाना। दाने टूट जाते हैं और रंग एक हो जाते हैं।"],"faq":[["क्या बिरयानी केसर के बिना बन सकती है?","जी हाँ। गरम दूध में घुला हुआ एक चुटकी पीला फ़ूड कलर इस्तेमाल करें, या छोड़ दें। ज़ायका मसाले और दम से आता है, सिर्फ़ रंग से नहीं।"],["चिकन को कितनी देर मैरीनेट करना चाहिए?","कम से कम 30 मिनट। फ्रिज में 2 से 4 घंटे बेहतर है। इसे फ्रिज में रखें, और मैरीनेट किए चिकन को कमरे के तापमान पर न छोड़ें।"],["मेरे चावल चिपके हुए क्यों बनते हैं?","चावल ज़्यादा उबल गया था, या फ़ौरन छाना नहीं गया, या पतीला ज़ोर से हिलाया गया। 70 प्रतिशत पर छानें और फुलाने से पहले आराम दें।"],["क्या बोनलेस चिकन इस्तेमाल कर सकते हैं?","जी हाँ। थाई पीस लें और मसाला पकाने का समय 3 से 4 मिनट कम कर दें, ताकि चिकन सूखा न हो।"]]},"nihari":{"intro":"निहारी असल में सब्र का खाना है, वीकेंड का सालन जो सब्र का इनाम नरम गोश्त और चम्मच पर चिपकने वाली ग्रेवी की सूरत में देता है। इस वर्शन में बीफ़ शैंक तक़रीबन 2 घंटे हल्की आंच पर पकता है, जब तक गोश्त हड्डी से अलग न हो जाए और मसाला गहरा रंग और ज़ायका न ले ले। आखिर में आटे का घोल ही निहारी की मशहूर गाढ़ी, चमकीली ग्रेवी बनाता है, इसलिए इसे आहिस्ता डालना और अच्छी तरह हिलाना ज़रूरी है। इसे ताज़ी नान और क्लासिक गार्निश के साथ उबलता हुआ परोसें, और मेज़ पर एक्स्ट्रा नींबू रखें।","ing":["बीफ़ (शैंक) 1 kg","निहारी मसाला 4 tbsp","आटा 3 tbsp","अदरक-लहसुन पेस्ट 2 tbsp","प्याज़ 1","घी / तेल 1/2 कप","अदरक","हरी मिर्च","नींबू (गार्निश के लिए)","हरा धनिया"],"steps":["घी गरम करें, कटी हुई प्याज़ को जलाए बिना हल्का ब्राउन करें, अदरक-लहसुन पेस्ट डालें, और कच्ची खुशबू जाने तक 1 मिनट भूनें।","गोश्त और निहारी मसाला डाल कर मध्यम तेज़ आंच पर 8 से 10 मिनट भूनें, जब तक गोश्त का रंग बदल जाए और मसाला हर टुकड़े पर लग जाए।","इतना गरम पानी डालें कि गोश्त से तक़रीबन 2 इंच ऊपर हो, उबाल लाएँ, और ऊपर आने वाली झाग हटा दें।","बर्तन ढक कर हल्की आंच पर 2 घंटे पकाएँ। बीच-बीच में हिलाएँ, और पानी गोश्त से नीचे जाए तो गरम पानी डालें।","गोश्त चेक करें। वो काँटे से अलग होना चाहिए और हड्डी से आसानी से छूटना चाहिए। अगर सख्त हो तो 20 से 30 मिनट और पकाएँ।","आटे को 1 कप ठंडे पानी में मिला कर बिल्कुल हमवार कर लें, कोई गुठली न रहे। बर्तन हिलाते हुए पतली धार में डालें।","10 से 15 मिनट हल्की आंच पर हिलाते हुए पकाएँ, जब तक ग्रेवी गाढ़ी और चमकीली हो जाए और चम्मच के पीछे चिपक जाए।","10 मिनट आराम दें, नमक चखें, और नान के साथ परोसें, ऊपर अदरक, हरी मिर्च, नींबू और धनिया डाल कर।"],"tip":"ग्रेवी पतली न रखें। निहारी अपनी गाढ़ी, चमकीली ग्रेवी से पहचानी जाती है। आटा आहिस्ता डालें ताकि गुठलियाँ न बनें, और डालते वक़्त लगातार हिलाएँ।","notes":["शैंक, हड्डी और कनेक्टिव टिशू के साथ, निहारी के लिए बेहतरीन है। इससे ग्रेवी में बॉडी आती है। बोनलेस स्टूइंग बीफ़ भी चल जाता है, लेकिन ग्रेवी उतनी रिच नहीं होती।","निहारी मसाला हर ब्रांड में तेज़ या हल्का होता है। पहली बार दी हुई मात्रा इस्तेमाल करें, और अगली बार ठीक करें।","घी से रिवायती ज़ायका आता है। तेल भी चल जाता है, और आधा घी आधा तेल बेहतरीन बीच का रास्ता है।","आटा सिर्फ़ गाढ़ा करने के लिए है। ज़्यादा न डालें, क्योंकि इससे मसाले का ज़ायका हल्का हो जाता है।"],"variations":["मटन निहारी: वही तरीक़ा इस्तेमाल करें और तक़रीबन 1 घंटा 30 मिनट पकाएँ, पहले चेक करें, क्योंकि मटन जल्दी गल जाता है।","चिकन निहारी: हड्डी वाला चिकन लें, 35 से 40 मिनट पकाएँ, आटे का घोल जल्दी डालें, और हल्की ग्रेवी की उम्मीद रखें।","ज़्यादा मिर्च वाली: ज़्यादा हरी मिर्च पकाते वक़्त नहीं, परोसते वक़्त डालें, ताकि मिर्च ताज़ी लगे।"],"serving":"5 लोगों के लिए नान और मेज़ पर गार्निश के छोटे कटोरों के साथ काफ़ी है, ताकि हर शख्स अपने ज़ायके के मुताबिक अदरक, मिर्च, नींबू और धनिया डाल सके। निहारी रिवायती तौर पर नाश्ते या वीकेंड के लंच में गहरे कटोरों में परोसी जाती है, गोश्त पर खूब ग्रेवी डाल कर। नान गरम रखें और बर्तन मेज़ पर तब लाएँ जब वो उबल रहा हो।","storage":"ठंडा कर के एयरटाइट डिब्बे में फ्रिज में 3 दिन तक रखें। ठंडा होने पर ग्रेवी गाढ़ी हो जाती है। हल्की आंच पर थोड़ा गरम पानी डाल कर आहिस्ता गरम करें, हिलाते हुए, जब तक पूरी तरह भाप न निकले। 2 महीने तक फ्रीज़ करें, फ्रिज में रात भर थॉ करें, और गार्निश सिर्फ़ परोसते वक़्त ताज़ी डालें।","mistakes":["तेज़ आंच पर पकाना। गोश्त सख्त हो जाता है और ग्रेवी जल्दी कम हो जाती है।","आटा सूखा या एक ही बार डालना। गुठलियाँ बन जाती हैं और आसानी से नहीं निकलतीं।","पकाने का समय कम रखना। गोश्त हड्डी से अलग होने के बजाय च्यूई रहता है।","ठंडी नान और गार्निश के बिना परोसना। इनके बिना ज़ायका फीका लगता है।"],"faq":[["मेरी निहारी की ग्रेवी पतली क्यों है?","आटा कम था, या डालने के बाद सिमर कम समय हुआ। हिलाते हुए 10 से 15 मिनट सिमर करें। ज़रूरत हो तो पानी में घुला हुआ 1 एक्स्ट्रा tbsp आटा डालें।"],["क्या प्रेशर कुकर इस्तेमाल कर सकते हैं?","जी हाँ। प्रेशर आने के बाद गोश्त और मसाला 25 से 30 मिनट पकाएँ, फिर खुले बर्तन में आटे के घोल के साथ पूरा करें। सुरक्षा के लिए अपने कुकर की निर्देशों का पालन करें।"],["क्या निहारी बहुत मिर्च वाली होती है?","मसाला गर्माहट देता है, जलन नहीं। परोसते वक़्त ताज़ी मिर्च से हर शख्स अपनी मर्ज़ी से तेज़ कर सकता है।"],["क्या इसे एक दिन पहले बना सकते हैं?","जी हाँ। फ्रिज में रात भर ज़ायका बेहतर हो जाता है। आहिस्ता गरम करें, ज़्यादा गाढ़ी हो तो थोड़ा गरम पानी डालें, और गार्निश ताज़ी डालें।"]]},"karahi":{"intro":"चिकन कड़ाही ढाबे का बेहतरीन खाना है, गहरी कड़ाही में जल्दी पकने वाला, बिना प्याज़ और बिना मसालों की लंबी लिस्ट के। ताज़े टमाटर मसाला बन जाते हैं, अदरक और हरी मिर्च आखिर में डाली जाती हैं, और पूरा खाना तक़रीबन 40 मिनट में तैयार हो जाता है। राज़ आंच और टाइमिंग है। आंच तेज़ रखें, टमाटर को अपना काम करने दें, और अदरक तब डालें जब कड़ाही उबल रही हो। इसे कड़ाही से सीधे गरम रोटी या नान के साथ खाएँ, जब मसाला चमकीला हो और चिकन नरम हो।","ing":["चिकन 750g","टमाटर 4 बड़े","अदरक-लहसुन पेस्ट 1 tbsp","हरी मिर्च 4","अदरक जूलियन","घी / तेल 1/2 कप","नमक","कुटी हुई लाल मिर्च","गरम मसाला","हरा धनिया"],"steps":["टमाटर को 4 टुकड़ों में काटें और अदरक, मिर्च और धनिया तैयार रखें। कड़ाही जल्दी बनती है, इसलिए सब कुछ हाथ के पास होना चाहिए।","कड़ाही में घी तेज़ आंच पर गरम करें। चिकन डाल कर 4 से 5 मिनट फ्राई करें, बार-बार पलट कर, जब तक बाहर का रंग बदल जाए।","अदरक-लहसुन पेस्ट डाल कर 1 मिनट भूनें। टमाटर और थोड़ा नमक डाल कर ढक दें, और मध्यम तेज़ आंच पर 8 से 10 मिनट पकाएँ।","ढक्कन हटा कर नरम टमाटर को चम्मच के पीछे से मैश करें। भूनते रहें जब तक मसाला गाढ़ा हो जाए और तेल ऊपर आ जाए।","कुटी हुई लाल मिर्च डालें और नमक चखें। अगर मसाला सूखा लगे तो सिर्फ़ 2 tbsp गरम पानी डालें, ज़्यादा नहीं।","आधी अदरक जूलियन और 2 कटी हुई हरी मिर्च डालें। 2 मिनट और भूनें ताकि इनका ज़ायका मसाले में चला जाए।","गरम मसाला छिड़कें, ढक दें, और हल्की आंच पर 5 मिनट दम दें। चिकन अंदर तक पक जाना चाहिए और जूसी रहना चाहिए।","बाकी अदरक, मिर्च और ताज़ा धनिया डालें। फ़ौरन परोसें, कड़ाही से सीधे, रोटी या नान के साथ।"],"tip":"कड़ाही में पानी न डालें। टमाटर का अपना पानी काफ़ी है। आंच तेज़ रखें ताकि चिकन नरम रहे और मसाला अच्छा भुने, और ताज़ी अदरक आखिर में डालें, शुरू में नहीं।","notes":["पके हुए, नरम टमाटर लें। सख्त टमाटर देर से घुलते हैं और मसाला पानी वाला रह जाता है।","हड्डी वाला चिकन ज़्यादा ज़ायका देता है और जूसी रहता है। बोनलेस थाई भी चल जाता है, लेकिन 3 से 4 मिनट कम पकाएँ।","घी से ढाबे का ज़ायका आता है। तेल भी चल जाता है, लेकिन आखिर में थोड़ी ज़्यादा अदरक डालें।","ताज़ी अदरक जूलियन गार्निश भी है और ज़ायका भी। सूखी अदरक पाउडर इसकी जगह नहीं ले सकती।"],"variations":["मटन कड़ाही: 750g मटन लें, ढक कर 40 से 50 मिनट नरम होने तक पकाएँ, फिर मसाला हमेशा की तरह तेज़ आंच पर भूनें।","हरी मिर्च कड़ाही: लाल मिर्च छोड़ दें, 8 हरी मिर्च लें, आधी मसाले में और आधी गार्निश में, ताज़े तेज़ ज़ायके के लिए।","बटर कड़ाही: आंच से उतार कर 1 tbsp मक्खन और 2 tbsp क्रीम मिला दें, ज़्यादा रिच और हल्के वर्शन के लिए।"],"serving":"4 लोगों के लिए रोटी या नान, प्याज़ और नींबू की सादी सलाद, और पसंद हो तो रायता के साथ काफ़ी है। कड़ाही में ही परोसें, नींबू के साथ, और गरम-गरम खाएँ। मसाला रोटी से उठाने के लिए होता है, इसलिए ज़्यादा रोटी तैयार रखें। ठंडा ड्रिंक या लस्सी मिर्च में मदद करता है।","storage":"1 घंटे के अंदर ठंडा कर के एयरटाइट डिब्बे में फ्रिज में 2 दिन तक रखें। कड़ाही में मध्यम आंच पर ढक कर 1 से 2 tbsp पानी के साथ दोबारा गरम करें, जब तक भाप न निकले। दोबारा गरम करने के बाद ताज़ी अदरक और धनिया डालें। 1 महीने तक फ्रीज़ कर सकते हैं, लेकिन थॉ होने पर टमाटर मसाला नरम हो जाता है, इसलिए ताज़ा बेहतरीन है।","mistakes":["शुरू में पानी डालना। मसाला गाढ़ी चमकीली कड़ाही के बजाय पतली करी बन जाता है।","पूरा समय हल्की आंच पर पकाना। चिकन भाप में पक जाता है, टमाटर टुकड़ों में रहते हैं, और मसाला ठीक से नहीं भुनता।","अदरक सिर्फ़ शुरू में डालना। वो पक कर खत्म हो जाती है, और ताज़ा फिनिश नहीं मिलता।","बोनलेस चिकन को ज़्यादा पकाना। तेज़ आंच पर वो जल्दी सूखा हो जाता है, इसलिए जल्दी चेक करें।"],"faq":[["मेरी कड़ाही में मसाला क्यों नहीं है?","टमाटर अच्छी तरह मैश और भुने नहीं गए, या पानी डाल दिया गया। टमाटर अच्छी तरह मैश करें और तेल अलग होने तक भूनें।"],["क्या कड़ाही कड़ाही के बिना बन सकती है?","जी हाँ। गहरी, भारी वॉक या फ्राइंग पैन इस्तेमाल करें। पतली पैन मसाला जला देती है, इसलिए आंच थोड़ी कम रखें और ज़्यादा हिलाएँ।"],["क्या कड़ाही में प्याज़ होती है?","रिवायती पाकिस्तानी कड़ाही में प्याज़ नहीं होती। टमाटर का पानी मसाला बनाता है। प्याज़ से अलग खाना बनता है, करी के करीब।"],["चिकन पक गया है, कैसे पता चलेगा?","सबसे मोटे टुकड़े को काटने पर रस साफ़ निकले, और गोश्त गुलाबी न रहे। शक हो तो सबसे बड़ा टुकड़ा काट कर चेक करें।"]]},"daal":{"intro":"दाल फ्राई रोज़ का वो खाना है जो साबित करता है कि सादा खाना भी यादगार हो सकता है, बस दाल नरम पकनी चाहिए और तड़का गरम-गरम डाल कर फ़ौरन ढक देना चाहिए। मसूर और मूंग जल्दी पक जाती हैं और बिना क्रीम के क्रीमी हो जाती हैं, और ऊपर घी, लहसुन, जीरा और साबुत लाल मिर्च की खुशबू कटोरे से पहले मेज़ तक पहुँचती है। ये चावल या रोटी के साथ सुकून का खाना है, व्यस्त हफ़्तों और उन दिनों के लिए जब कुछ ख़ास नहीं चाहिए। पूरी रेसिपी तक़रीबन 35 मिनट लेती है, और ज़्यादा समय दाल खामोशी से उबलती है।","ing":["मसूर / मूंग दाल 1½ कप","हल्दी 1/2 tsp","नमक","लहसुन 4 कलियाँ","जीरा 1 tsp","साबुत लाल मिर्च 3","घी 3 tbsp","हरी मिर्च","हरा धनिया","नींबू"],"steps":["दाल को कई बार पानी बदल कर धोएँ, जब तक पानी तक़रीबन साफ़ न हो जाए, फिर अच्छी तरह छान लें।","दाल को बर्तन में हल्दी और 4 कप पानी के साथ रखें। उबाल लाएँ, झाग हटा दें, और आंच हल्की कर दें।","20 से 25 मिनट हल्की आंच पर पकाएँ, बीच-बीच में हिलाते हुए, जब तक दाल बिल्कुल नरम और क्रीमी न हो जाए। ज़्यादा गाढ़ी हो तो गरम पानी डालें।","चखें और नमक डालें। दाल बहने वाली होनी चाहिए, सख्त नहीं, क्योंकि ठंडा होने पर गाढ़ी हो जाती है।","लहसुन को पतला काटें। छोटी कड़ाही में घी मध्यम आंच पर गरम करें और जीरा डालें। जब चटकने लगे तो लहसुन डालें।","लहसुन को सुनहरा होने तक फ्राई करें, ब्राउन नहीं। साबुत लाल मिर्च डालें, दस तक गिनें, और कड़ाही फ़ौरन आंच से उतार लें।","गरम तड़का एक ही बार दाल पर डालें, सिज़ल सुनें, और 2 मिनट के लिए बर्तन ढक दें ताकि खुशबू अंदर रहे।","हरी मिर्च और धनिया मिलाएँ, ऊपर नींबू निचोड़ें, और चावल या रोटी के साथ गरम परोसें।"],"tip":"जैसे ही तड़का डालें, दाल को ढक दें। इससे खुशबू दाल के अंदर रहती है, रसोई में नहीं निकलती, और लहसुन का ज़ायका पूरे बर्तन में फैल जाता है।","notes":["मसूर दाल सबसे जल्दी पकती है और क्रीमी होती है। मूंग दाल थोड़ी शेप रखती है। दोनों चल जाती हैं, और आधी-आधी मिक्स भी अच्छी है।","हल्दी रंग और हल्के ज़ायके के लिए है। ज़्यादा डालने से दाल कड़वी हो जाती है, इसलिए नाप कर डालें।","तड़के के लिए लहसुन को काटें, कूटें नहीं। काशें एक जैसी सुनहरी होती हैं और कुरकुरी रहती हैं।","घी तड़के का ज़ायका सबसे अच्छा उठाता है। तेल भी चल जाता है, लेकिन एक एक्स्ट्रा लहसुन की कली डालें।"],"variations":["पालक दाल: पकी हुई दाल में 2 कप कटा हुआ पालक मिला कर तड़के से पहले 5 मिनट सिमर करें।","टमाटर दाल: शुरू में दाल के साथ 1 कटा हुआ टमाटर डालें, खट्टे और थोड़े गाढ़े नतीजे के लिए।","ज़्यादा लहसुन वाली: तड़के में लहसुन दुगना कर दें और आधा tsp कुटी हुई लाल मिर्च भी डालें।"],"serving":"4 लोगों के लिए उबले हुए चावल या रोटी, नींबू का टुकड़ा, और साइड पर सादी सलाद या अचार के साथ काफ़ी है। दाल गहरे कटोरों में पतली और गरम परोसनी चाहिए, तड़का ऊपर नज़र आना चाहिए। चावल के साथ परोसें तो दाल मेज़ पर चावल पर डालें। तला हुआ अंडा या पापड़ इसे पूरा खाना बना देता है।","storage":"ठंडा कर के एयरटाइट डिब्बे में फ्रिज में 3 दिन तक रखें। फ्रिज में दाल गाढ़ी हो जाती है, इसलिए दोबारा गरम करते वक़्त थोड़ा गरम पानी मिला कर हिलाएँ। हल्की आंच पर हिलाते हुए गरम करें, जब तक भाप न निकले, और दोबारा गरम करने के बाद ताज़ा धनिया डालें। हिस्सों में 1 महीने तक फ्रीज़ करें, फ्रिज में थॉ करें, और बेहतरीन खुशबू के लिए ताज़ा तड़का बनाएँ।","mistakes":["दाल को कम पकाना। दाने वाली दाल तड़का कितना भी अच्छा हो, क्रीमी नहीं होती।","लहसुन जलाना। ब्राउन लहसुन कड़वा हो जाता है और पूरा बर्तन खराब कर देता है, इसलिए कड़ाही जल्दी उतार लें।","तड़के के बाद बर्तन खुला छोड़ना। खुशबू निकल जाती है और दाल फीकी लगती है।","दाल सख्त रहने पर नमक शुरू में डालना, इससे नरम होने में देर हो सकती है, इसलिए नरम होने के बाद नमक डालें।"],"faq":[["तड़का दाल के लिए सबसे अच्छी दाल कौन सी है?","मसूर सबसे जल्दी और क्रीमी होती है। मूंग करीब दूसरी है। तूर दाल भी चल जाती है, लेकिन इसे ज़्यादा समय चाहिए और प्रेशर कुकर मदद करता है।"],["क्या दाल फ्राई घी के बिना बन सकती है?","जी हाँ। तेल इस्तेमाल करें और एक एक्स्ट्रा लहसुन की कली डालें। नतीजा हल्का होता है, और तड़का फिर भी काम करता है, लेकिन खुशबू उतनी रिच नहीं होती।"],["मेरी दाल पानी वाली क्यों है?","इसे काफ़ी देर सिमर नहीं किया गया, या पानी ज़्यादा इस्तेमाल हुआ। कुछ मिनट बिना ढके सिमर कर के गाढ़ा करें, और याद रखें कि ठंडा होने पर और गाढ़ी होती है।"],["क्या दाल प्रेशर कुकर में पका सकते हैं?","जी हाँ। 2 सीटी या तक़रीबन 8 मिनट प्रेशर पर पकाएँ, प्रेशर खुद खत्म होने दें, फिर खुले बर्तन में तड़का लगा कर पूरा करें।"]]},"chapli":{"intro":"चपली कबाब पेशावर है एक प्लेट में, चपटा, नरम, मसालेदार, और तवे पर तला हुआ जब तक किनारे कुरकुरे न हो जाएँ। इसका नाम इसकी चपटी शेप से आया है, और ज़ायका टमाटर, अनारदाना, कुटे हुए साबुत धनिया और हरी मिर्च से आता है जो कीमे में मिलाए जाते हैं। ये स्ट्रीट फ़ूड भी है और दावत का खाना भी, नान, प्याज़ और हरी चटनी के साथ खाया जाता है, और ठंडे कीमे और नरम हाथों से बेहतरीन बनता है। इसे मध्यम हल्की आंच पर फ्राई करें ताकि बीच में पक जाए और बाहर न जले, और बीच में टमाटर का टुकड़ा दबाएँ, जैसे कबाब बनाने वाले करते हैं।","ing":["बीफ़ कीमा 500g","टमाटर 1 बारीक कटा","प्याज़ 1","अनारदाना 1 tbsp","कुटा हुआ साबुत धनिया","हरी मिर्च 3","अदरक","नमक","मक्के का आटा 2 tbsp","तलने के लिए तेल"],"steps":["प्याज़ और टमाटर को बहुत बारीक काटें और टमाटर का ज़्यादा रस निचोड़ दें, ताकि मिक्स शेप देने के लिए सख्त रहे।","कीमा एक कटोरे में टमाटर, प्याज़, अनारदाना, कुटा धनिया, मिर्च, अदरक, नमक और मक्के के आटे के साथ रखें। हाथों से सिर्फ़ मिलने तक मिलाएँ।","ढक कर मिक्स को फ्रिज में 20 मिनट आराम दें। ठंडा कीमा शेप अच्छी रखता है और बेहतर फ्राई होता है।","हाथों को ठंडे पानी से गीला करें। एक हिस्सा लें, तक़रीबन 4 इंच की पतली गोल टिक्की बनाएँ, और बीच में टमाटर का छोटा टुकड़ा दबाएँ।","तवे पर तेल की अच्छी तह मध्यम आंच पर गरम करें। तेल इतना गरम हो कि सिज़ल करे, लेकिन धुआँ न निकले।","कबाब को जगह छोड़ कर तवे पर रखें। पहली तरफ 4 से 5 मिनट फ्राई करें, बिना दबाए।","चौड़ी स्पैटुला से आहिस्ता पलटें और 4 से 5 मिनट और फ्राई करें, जब तक दोनों तरफ सुनहरे और अंदर तक पक न जाएँ।","निकाल कर हल्का ड्रेन करें, और हरी चटनी, कटी हुई प्याज़ और नान के साथ गरम परोसें।"],"tip":"कबाब को ज़्यादा न दबाएँ। आहिस्ता पलटें वरना टूट जाएँगे। ठंडा कीमा बेहतर कबाब बनाता है, इसलिए मिक्स को हर बैच शेप देने तक फ्रिज में रखें।","notes":["थोड़ी चर्बी वाला कीमा लें, तक़रीबन 15 से 20 प्रतिशत। बिल्कुल लीन कीमा सूखा और टूटने वाला कबाब बनाता है।","मक्के का आटा मिक्स को बाँधता है और क्लासिक टेक्सचर देता है। गेहूँ का आटा भी चल जाता है, लेकिन कबाब घना होता है।","अनारदाना खट्टा पॉप देता है। इसे हल्का कूट लें, पेस्ट न बनाएँ।","बारीक कटा टमाटर नमी और ज़ायका देता है, लेकिन ज़्यादा रस कबाब को तोड़ देता है, इसलिए पहले ड्रेन करें।"],"variations":["चिकन चपली: चिकन कीमा लें, 1 एक्स्ट्रा tbsp मक्के का आटा डालें, और हर तरफ 3 से 4 मिनट फ्राई करें, क्योंकि चिकन जल्दी पक जाता है।","ज़्यादा मिर्च वाली: 1 tsp कुटी हुई लाल मिर्च और एक एक्स्ट्रा हरी मिर्च डालें, और ज़्यादा चटनी के साथ परोसें।","चपली बर्गर: कबाब को सेंके हुए बन में प्याज़, टमाटर, चटनी और तले हुए अंडे के साथ रखें, पेशावर स्टाइल बर्गर के लिए।"],"serving":"4 लोगों के लिए नान, हरी चटनी, कटी हुई प्याज़, नींबू और सलाद के साथ मेन डिश के तौर पर काफ़ी है। हर शख्स को 2 कबाब खूब चटनी के साथ दें, और ज़्यादा नान गरम रखें। चपली कबाब स्टार्टर के तौर पर भी अच्छा है, मेन कोर्स से पहले हर शख्स को एक कबाब चटनी और नींबू के साथ। पुदीने का रायता मिर्च को ठंडा करता है।","storage":"ठंडा कर के पके हुए कबाब एयरटाइट डिब्बे में फ्रिज में 2 दिन तक रखें। तवे पर मध्यम आंच पर गरम करें जब तक अंदर तक गरम न हो जाए, या ओवन में 180C पर 8 से 10 मिनट। कच्चा मिक्स फ्रिज में 1 दिन तक रहता है। शेप दिए हुए कच्चे कबाब को बेकिंग पेपर के बीच में रख कर 1 महीने तक फ्रीज़ करें, और फ्रोज़न ही फ्राई करें, हर तरफ 2 मिनट ज़्यादा दें।","mistakes":["मोटे कबाब बनाना। बाहर जल जाता है और बीच में कच्चा रह जाता है, इसलिए पतले और एक जैसे रखें।","बहुत तेज़ आंच पर फ्राई करना। मसाले जल जाते हैं और कबाब पलटने पर टूट जाता है।","स्पैटुला से दबाना। इससे रस निकल जाता है और कबाब सूखा हो जाता है।","दुकान से लाया गरम कीमा इस्तेमाल करना। वो नरम और चिपचिपा होता है और शेप देना मुश्किल होता है, इसलिए पहले ठंडा करें।"],"faq":[["मेरे चपली कबाब क्यों टूट जाते हैं?","मिक्स ज़्यादा गीला था, कबाब मोटा था, या जल्दी पलट दिया गया। टमाटर ड्रेन करें, मिक्स ठंडा करें, कबाब पतले रखें, और पहली तरफ सेट होने दें फिर पलटें।"],["क्या चपली कबाब बेक कर सकते हैं?","जी हाँ। तेल ब्रश कर के 200C पर 15 से 18 मिनट बेक करें, एक बार पलट कर। वो तले हुए कबाब जितने कुरकुरे नहीं होते, लेकिन फिर भी मज़ेदार होते हैं।"],["अनारदाना किस लिए होता है?","अनारदाना खट्टा, फ्रूटी ज़ायका देता है जो रिच कीमे को बैलेंस करता है। न मिले तो 1 tsp नींबू रस और कुछ कुटी हुई सूखी क्रैनबेरी इस्तेमाल करें, लेकिन ज़ायका अलग होता है।"],["क्या मिक्स पहले से बना सकते हैं?","जी हाँ। मिला कर ढक कर फ्रिज में 1 दिन तक रखें। फ्राई करने से पहले ही शेप दें, ताकि कबाब अपनी फ़ॉर्म रखें।"]]},"tikka":{"intro":"चिकन टिक्का वो खाना है जो अच्छे तरीके से सब्र सिखाता है। मैरीनेड काम करती है, दही और मसाले कम से कम एक घंटे तक गोश्त में जाते हैं, और ग्रिल को सिर्फ़ तेज़ आंच और हर तरफ कुछ मिनट चाहिए। ठीक बने तो बाहर हल्का चर्र्ड और स्मोकी होता है, अंदर जूसी रहता है, और आखिर में नींबू और चाट मसाला सब कुछ जगा देता है। ये स्टार्टर, नान के साथ मेन डिश, और अगले दिन रैप और सलाद में कटा हुआ, सब में चल जाता है। नीचे दी रेसिपी ओवन ग्रिल या बारबेक्यू के लिए है, और गरम पैन भी चल जाता है अगर वही हो।","ing":["चिकन (लेग / बोनलेस) 750g","दही 1/2 कप","लाल मिर्च 1 tbsp","हल्दी","गरम मसाला","जीरा पाउडर","अदरक-लहसुन पेस्ट 1 tbsp","नींबू 1 (तेल / मक्खन ब्रश करने के लिए)"],"steps":["चिकन को एक जैसे टुकड़ों में काटें और हर टुकड़े पर 2 हल्के कट लगाएँ, ताकि मैरीनेड अंदर तक जाए।","दही, लाल मिर्च, हल्दी, गरम मसाला, जीरा पाउडर, अदरक-लहसुन पेस्ट, नींबू रस और नमक को हमवार पेस्ट बना लें।","चिकन पर अच्छी तरह लगाएँ, ढक कर फ्रिज में कम से कम 1 घंटा रखें। रात भर भी ठीक है और ज़ायका गहरा होता है।","पकाने से 20 मिनट पहले चिकन निकाल लें, ताकि आंच पर जाते वक़्त फ्रिज जितना ठंडा न हो।","ग्रिल या बारबेक्यू को तेज़ गरम करें। रैक पर हल्का तेल लगाएँ और चिकन को एक तह में जगह छोड़ कर रखें।","पहली तरफ 6 से 8 मिनट ग्रिल करें, एक बार मक्खन या तेल ब्रश कर के, जब तक किनारे हल्के चर्र्ड न हो जाएँ।","पलट कर 6 से 8 मिनट और ग्रिल करें, जब तक अंदर तक पक जाए और रस साफ़ निकले।","5 मिनट आराम दें, नींबू रस और चाट मसाला छिड़कें, और प्याज़, चटनी और नान के साथ गरम परोसें।"],"tip":"मैरीनेशन जितनी लंबी, टिक्का उतना नरम। वक़्त कम हो तो कम से कम 30 मिनट ज़रूर दें, और स्कोरिंग कभी न छोड़ें, क्योंकि इसी से मैरीनेड मोटे टुकड़ों में जाती है।","notes":["थाई का गोश्त तेज़ आंच पर ब्रेस्ट से ज़्यादा जूसी रहता है। ब्रेस्ट भी चल जाता है, लेकिन एक मिनट पहले चेक करें।","दही को लटका लें या गाढ़ी दही इस्तेमाल करें। पानी वाली दही चिकन से फिसल जाती है और ग्रिल पर जल जाती है।","मैरीनेड में ताज़ा नींबू नरम करने में मदद करता है, लेकिन ज़्यादा देर ज़्यादा नींबू सतह को मुशी बना सकता है, इसलिए रात भर वाली मैरीनेड में नींबू हल्का रखें।","चाट मसाला आखिर में डालें, मैरीनेड में नहीं, ताकि इसकी खट्टापन ताज़ा रहे।"],"variations":["मलाई टिक्का: लाल मिर्च की जगह सफ़ेद मिर्च लें, मैरीनेड में 2 tbsp क्रीम और 1 tbsp चीज़ डालें, हल्के क्रीमी वर्शन के लिए।","हरियाली टिक्का: धनिया, पुदीना, हरी मिर्च और दही को ब्लेंड कर के हरी मैरीनेड बनाएँ, और वही तरीके से ग्रिल करें।","टिक्का रैप: बचा हुआ टिक्का काट कर पराठे या रोटी में प्याज़, चटनी और सलाद के साथ रोल करें, अगले दिन के लंच के लिए।"],"serving":"4 लोगों के लिए नान या रोटी, कटी हुई प्याज़, नींबू, हरी चटनी और सलाद के साथ काफ़ी है। गरम प्लैटर पर ग्रिल से सीधे परोसें, मेज़ पर नींबू निचोड़ कर। टिक्का चावल पर, रैप में, या सलाद पर भी अच्छा लगता है। साइड पर ज़्यादा चटनी रखें, क्योंकि लोग हमेशा और माँगते हैं।","storage":"ठंडा कर के एयरटाइट डिब्बे में फ्रिज में 2 दिन तक रखें। 180C पर गरम ओवन में 8 मिनट, या पैन में मध्यम आंच पर गरम करें, जब तक भाप न निकले। माइक्रोवेव में ज़्यादा देर गरम न करें, क्योंकि चिकन सूखा हो जाता है और चार नरम हो जाता है। मैरीनेट किया कच्चा चिकन फ्रिज में 1 दिन तक रहता है। पका हुआ टिक्का 1 महीने तक फ्रीज़ करें और फ्रिज में थॉ करें।","mistakes":["फ्रिज से ठंडा चिकन ग्रिल करना। बाहर जल जाता है और अंदर कच्चा रह जाता है, इसलिए पहले कमरे के तापमान पर लाएँ।","ग्रिल पर भीड़ करना। टुकड़े चर्र्ड होने के बजाय भाप में पक जाते हैं, इसलिए जगह छोड़ें और ज़रूरत हो तो बैच में पकाएँ।","आराम न देना। फ़ौरन काटने से रस निकल जाता है और टिक्का सूखा हो जाता है।","पतली मैरीनेड इस्तेमाल करना। वो टपक जाती है और जल जाती है, चिकन फीका रह जाता है।"],"faq":[["क्या टिक्का पैन में पका सकते हैं?","जी हाँ। भारी पैन में तेज़ आंच पर थोड़े तेल के साथ हर तरफ 6 से 7 मिनट पकाएँ। स्मोकी चार वैसा नहीं होगा, लेकिन ज़ायका करीब होगा।"],["घर पर स्मोकी ज़ायका कैसे लाएँ?","ग्रिल करने के बाद बर्तन में गरम कोयले के टुकड़े के साथ छोटा स्टील कटोरा रखें, उस पर तेल की चंद बूँदें डालें, 2 मिनट ढक दें, और कटोरा निकाल लें। रसोई में हवा का गुज़र रखें।"],["क्या ब्रेस्ट चिकन इस्तेमाल कर सकते हैं?","जी हाँ, लेकिन ज़्यादा न पकाएँ। हर तरफ 5 से 6 मिनट के बाद चेक करें, और अच्छी तरह आराम दें। थाई ज़्यादा माफ़ करने वाला है।"],["क्या टिक्का मिर्च वाला होता है?","ये गरम और मसालेदार होता है, बहुत तेज़ नहीं। हल्के वर्शन के लिए लाल मिर्च 1 tsp कर दें, और चटनी मेज़ पर मिर्च दे देगी।"]]},"halwapuri":{"intro":"हलवा पूरी लाहौर में इतवार का नाश्ता है, और कई घरों में ये सिर्फ़ खाना नहीं, पूरा इवेंट है। तीन चीज़ें इकट्ठी आती हैं, फूली हुई पूरी, नरम सूजी का हलवा, और आलू के साथ मसालेदार चने, और मज़ा एक निवाले में तीनों लेने में है। हर हिस्सा अपने तौर पर सादा है, लेकिन टाइमिंग अहम है। पूरी आखिर में फ्राई करें, ताकि फूली हुई और गरम आए, हलवा गरम और नरम रखें, और चनों को इतना सिमर करें कि मसाला उन पर लग जाए। इसे एक स्लो सुबह पकाएँ, इकट्ठे खाएँ, और जल्दी न करें।","ing":["मैदा 2 कप","सूजी 1 कप","चीनी 1 कप","घी 1/2 कप","चने (उबले हुए) 2 कप","आलू 1","प्याज़","टमाटर","गरम मसाला","हल्दी","लाल मिर्च","इलायची (बादाम गार्निश के लिए)"],"steps":["मैदे को पानी और चुटकी भर नमक के साथ सख्त, हमवार आटा गूँधें। ढक कर 20 मिनट आराम दें।","अगर चने उबले हुए नहीं हैं तो उबाल लें, जब तक नरम हो जाएँ लेकिन मुशी न हों, और इनके पकाने का 1 कप पानी बचा लें।","सूजी को हल्की आंच पर घी में लगातार हिलाते हुए भूनें, जब तक सुनहरी और नटी खुशबू न आए, तक़रीबन 8 से 10 मिनट।","गरम पानी और चीनी एहतियात से डालें, उबलेगा, हिलाते हुए पकाएँ जब तक हलवा गाढ़ा न हो जाए, फिर इलायची डाल कर हल्की आंच पर 5 मिनट ढक दें।","तेल गरम करें, प्याज़ नरम होने तक फ्राई करें, टमाटर, आलू, गरम मसाला, हल्दी और लाल मिर्च डाल कर मसाला अच्छी तरह भूनें।","चने और इनका पकाने वाला पानी डालें, 10 मिनट सिमर करें, और कुछ चनों को किनारे पर मैश कर के ग्रेवी गाढ़ी करें।","छोटी पूरियाँ बेलें, सिक्के के किनारे से मोटी नहीं, और गरम तेल में डीप फ्राई करें, हल्के से दबाते हुए ताकि हर एक फूल जाए। कागज़ पर ड्रेन करें।","पूरी, हलवा और चने एक प्लेट में इकट्ठे परोसें, हलवे पर बादाम डाल कर।"],"tip":"पूरी बेलते वक़्त ज़्यादा मैदा न लगाएँ, वरना फूलेगी नहीं। तेल अच्छा गरम हो तो पूरी फ़ौरन फूल जाती है, इसलिए पहले आटे के छोटे टुकड़े से टेस्ट करें, वो सेकंडों में ऊपर आना चाहिए।","notes":["सख्त आटा फूली हुई पूरी बनाता है। नरम आटा तेल पी लेता है और चपटा रहता है, इसलिए सख्त गूँधें और अच्छी तरह आराम दें।","बारीक सूजी हमवार हलवा देती है। मोटी सूजी को ज़्यादा पानी और ज़्यादा समय चाहिए।","चनों के पकाने का पानी बचा कर रखें। इससे ग्रेवी कुदरती तौर पर गाढ़ी होती है और ज़ायका आता है।","इलायची हलवे में आखिर में डालें, ताकि इसकी खुशबू ताज़ी रहे, पक कर खत्म न हो।"],"variations":["चनों की जगह आलू की तरकारी: आलू को वही मसाले में पकाएँ, आधे मैश कर लें, और सेवरी साइड के तौर पर परोसें।","कम मीठा हलवा: चीनी 3/4 कप कर दें और थोड़ी ज़्यादा इलायची डालें, मसालेदार चनों के साथ बेहतर लगने वाले हलवे के लिए।","होल व्हीट पूरी: आधा होल व्हीट आटा और आधा मैदा लें, आटे को थोड़ा ज़्यादा आराम दें, और थोड़ा मोटा बेलें।"],"serving":"4 लोगों के लिए, हर शख्स को 2 से 3 पूरी, एक चम्मच हलवा, और एक प्लेट में चनों का बड़ा चम्मच काफ़ी है। अचार, कटी हुई प्याज़ और नींबू के साथ, और साइड पर चाय के साथ परोसें। हलवा पूरी बैठ कर खाने वाला नाश्ता है, गरम-गरम, सब मेज़ पर इकट्ठे। ज़्यादा पूरी बनाएँ, क्योंकि वो सबसे जल्दी खत्म होती है।","storage":"पूरी ताज़ी खाएँ, वो अच्छी नहीं रहती। हलवा फ्रिज में एयरटाइट डिब्बे में 3 दिन तक रहता है, और हल्की आंच पर पैन में थोड़े दूध या पानी के साथ दोबारा गरम होता है। चने फ्रिज में 3 दिन तक रहते हैं, और स्टोव पर उबलने तक दोबारा गरम होते हैं। तैयार प्लेट स्टोर न करें, तीनों हिस्से अलग रखें और परोसते वक़्त मिलाएँ।","mistakes":["पूरी को ज़्यादा मोटा बेलना या ज़्यादा सूखा मैदा लगाना। वो चपटी और च्यूई रहती है, फूलती नहीं।","सूजी को तेज़ आंच पर भूनना। वो जगह-जगह ब्राउन हो जाती है और जली हुई लगती है, इसलिए आंच हल्की रखें और हिलाएँ।","गरम सूजी में ठंडा पानी डालना। इससे गुठलियाँ बन जाती हैं, इसलिए गरम पानी इस्तेमाल करें और फ़ौरन हिलाएँ।","पूरी को कम गरम तेल में फ्राई करना। वो तेल पी लेती है और ग्रीसी हो जाती है।"],"faq":[["मेरी पूरी क्यों नहीं फूलती?","आटा ज़्यादा नरम था, पूरी ज़्यादा मोटी बेली गई, या तेल काफ़ी गरम नहीं था। सख्त गूँधें, पतला बेलें, और पहले तेल टेस्ट करें।"],["क्या टिन्ड चने इस्तेमाल कर सकते हैं?","जी हाँ। ड्रेन कर के धो लें, फिर मसाले में 10 मिनट सिमर करें। थोड़ा गरम पानी डालें, क्योंकि टिन्ड चनों के पास पकाने का पानी नहीं होता।"],["हलवा कितना मीठा होना चाहिए?","रिवायती हलवा पूरी का हलवा काफ़ी मीठा होता है, मसालेदार चनों को बैलेंस करने के लिए। कम मीठा पसंद हो तो चीनी कम करें, लेकिन आधी न करें, वरना टेक्सचर बदल जाता है।"],["क्या हिस्से पहले से बना सकते हैं?","जी हाँ। हलवा और चने एक दिन पहले बना कर फ्रिज में रखें। पूरी सुबह ताज़ी फ्राई करें, क्योंकि दोबारा गरम की हुई पूरी कभी उतनी अच्छी नहीं होती।"]]},"samosa":{"intro":"अच्छे समोसे का फैसला पहले निवाले में होता है, कुरकुरी परत जो टूट जाए, फिर मटर, अदरक और धनिये के साथ मसालेदार आलू। परत सख्त और आराम दी हुई होनी चाहिए, फिलिंग सूखी होनी चाहिए, गीली नहीं, और फ्राइंग हल्की आंच पर आहिस्ता होनी चाहिए, ताकि क्रस्ट अंदर तक सुनहरा हो, एक मिनट में ब्राउन हो कर अंदर से फीका न रहे। ये रेसिपी क्लासिक पंजाबी समोसा बनाती है, जो हरी और इमली की चटनी और चाय के कप के साथ परोसा जाता है। डबल बैच बनाएँ, क्योंकि ये जल्दी खत्म हो जाते हैं, और एक्स्ट्रा को फ्राई करने से पहले फ्रीज़ कर लें किसी और दिन के लिए।","ing":["मैदा 2 कप","अजवाइन 1/2 tsp","आलू (उबले हुए) 4","मटर 1/2 कप","अदरक","हरी मिर्च","गरम मसाला","हरा धनिया","अनारदाना","तलने के लिए तेल"],"steps":["अजवाइन और 3 tbsp तेल को उँगलियों से मैदे में मल लें, जब तक वो ब्रेडक्रम्ब्स जैसा न लगे।","थोड़ा-थोड़ा पानी डाल कर सख्त, स्टिफ़ आटा गूँधें। वो नरम नहीं होना चाहिए। ढक कर 20 मिनट आराम दें।","आलू को सिर्फ़ नरम होने तक उबालें, ठंडा करें, और मोटा-मोटा तोड़ लें। इसे हमवार मैश न करें।","1 tbsp तेल गरम करें, अदरक और हरी मिर्च 30 सेकंड फ्राई करें, मटर, गरम मसाला, नमक और अनारदाना डाल कर 2 मिनट पकाएँ।","आलू और धनिया डालें, अच्छी तरह मिलाएँ, और 2 से 3 मिनट पकाएँ जब तक फिलिंग सूखी न हो जाए। इसे बिल्कुल ठंडा कर लें।","आटे को गोलियों में बाँटें, हर एक को ओवल बेलें, आधा काटें, और कोन बनाएँ, सीधा किनारा पानी से बंद कर के।","हर कोन को तीन चौथाई भरें, ऊपर वाला किनारा मज़बूती से बंद करें, और दबाकर बंद करें। चेक करें कि फिलिंग बाहर न निकले।","हल्की आंच पर तेल में 12 से 15 मिनट फ्राई करें, बीच-बीच में पलट कर, जब तक गहरा सुनहरा और कुरकुरा न हो जाए। ड्रेन कर के चटनी के साथ परोसें।"],"tip":"समोसा हमेशा हल्की आंच पर फ्राई करें। तेज़ आंच पर परत जल जाएगी और अंदर कच्चा रह जाएगा, और क्रस्ट कुरकुरा और एक जैसा होने के बजाय बबल बन जाएगा।","notes":["सख्त आटा कुरकुरी परत का राज़ है। नरम आटा च्यूई, ऑइली समोसा बनाता है।","भरने से पहले फिलिंग को बिल्कुल ठंडा कर लें। गरम फिलिंग अंदर से परत में भाप बनाती है और सील कमज़ोर कर देती है।","अजवाइन क्लासिक ज़ायका देती है और हाज़मे में मदद करती है। मिल जाए तो न छोड़ें।","सूखी फिलिंग अहम है। गीली फिलिंग लीक होती है, परत को नरम करती है, और फ्राइंग को मेसी बना देती है।"],"variations":["कीमा समोसा: आलू की जगह पका हुआ, मसालेदार कीमा लें, बिल्कुल ठंडा कर के, और वही तरीके से फ्राई करें।","पनीर समोसा: मटर, गरम मसाला और धनिये के साथ क्रम्बल्ड पनीर इस्तेमाल करें, ज़्यादा रिच वेजिटेरियन फिलिंग के लिए।","बेक्ड समोसा: तेल ब्रश कर के 190C पर 20 से 25 मिनट बेक करें, एक बार पलट कर। कम कुरकुरा, लेकिन हल्का।"],"serving":"6 लोगों के लिए, हर शख्स को 2 समोसे, हरी चटनी, इमली की चटनी, कटी हुई प्याज़ और गरम चाय के साथ काफ़ी है। प्लैटर पर परोसें, एक को काट कर फिलिंग दिखाएँ, और साइड पर ज़्यादा चटनी रखें। समोसा फ्राई करने के 30 मिनट के अंदर गरम-गरम बेहतरीन होता है, जब परत अभी कुरकुरी हो। ऊपर छिड़का हुआ थोड़ा चाट मसाला खट्टा फिनिश देता है।","storage":"बेहतरीन कुरकुरेपन के लिए ताज़ा खाएँ। ठंडे, तले हुए समोसे फ्रिज में 2 दिन तक रहते हैं और ओवन में 180C पर 8 से 10 मिनट दोबारा गरम होते हैं, जब तक दोबारा कुरकुरे न हो जाएँ। माइक्रोवेव न करें, क्योंकि परत नरम हो जाती है। कच्चे, शेप दिए हुए समोसों को ट्रे पर फ्रीज़ करें, फिर बैग में डाल कर 1 महीने तक रखें, और फ्रोज़न ही हल्की आंच पर फ्राई करें, 3 से 4 मिनट ज़्यादा दें।","mistakes":["नरम आटा गूँधना। वो आसानी से बेलता है, लेकिन नरम और ऑइली फ्राई होता है।","गरम, गीली फिलिंग भरना। सील खुल जाती है और फिलिंग तेल में लीक हो जाती है।","तेज़ आंच पर फ्राई करना। बाहर जल्दी ब्राउन हो जाता है और अंदर की परत डोई रह जाती है।","कोन को ज़्यादा भरना। वो तेल में फट जाते हैं, इसलिए सिर्फ़ तीन चौथाई भरें।"],"faq":[["मेरे समोसे की परत कुरकुरी क्यों नहीं, नरम क्यों है?","आटा ज़्यादा नरम था, या फ्राइंग की आंच ज़्यादा तेज़ थी। सख्त गूँधें, आटे को आराम दें, और हल्की आंच पर आहिस्ता फ्राई करें।"],["क्या समोसे एयर फ्रायर में बना सकते हैं?","जी हाँ। तेल ब्रश कर के 180C पर 12 से 15 मिनट एयर फ्राई करें, एक बार पलट कर। क्रस्ट कुरकुरा होता है, हालाँकि डीप फ्राइड से थोड़ा सूखा होता है।"],["समोसा फ्राई करते वक़्त खुलने से कैसे रोकें?","पानी से बंद करें और मज़बूती से दबाएँ, और शेप दिए हुए समोसों को फ्राई करने से पहले 10 मिनट आराम दें, ताकि सील सेट हो जाए।"],["क्या रेडी मेड पेस्ट्री इस्तेमाल कर सकते हैं?","ज़रूरत हो तो स्प्रिंग रोल शीट इस्तेमाल कर सकते हैं, लेकिन ज़ायका और टेक्सचर अलग होता है। क्लासिक कुरकुरापन इस रेसिपी के सख्त मैदे के आटे से आता है।"]]},"bunkebab":{"intro":"बन कबाब कराची का स्ट्रीट फ़ूड है जिसके वफ़ादार चाहने वाले हैं, नरम बन, तला हुआ शामी कबाब, कटी हुई प्याज़ और टमाटर, और चटनी जो हर निवाले में मिर्च, खट्टापन और ताज़गी लाती है। ये घर पर 25 मिनट में बनने वाला फ़ास्ट फ़ूड है, बस शामी कबाब तैयार हों, और तवे से सीधे गरम खाना बेहतरीन है, बन हल्का सेंका हुआ और फिर भी नरम। बैलेंस किसी एक इंग्रीडिएंट से ज़्यादा अहम है। ज़्यादा चटनी कबाब को डुबो देती है, कम चटनी बन को सूखा छोड़ देती है, और अच्छा सेंका हुआ बन सब कुछ इकट्ठा रखता है बिना हाथों में टूटने के।","ing":["शामी कबाब 8","बन 4","प्याज़","टमाटर","हरी चटनी","इमली की चटनी","दही","हरी मिर्च","हरा धनिया","बन सेंकने के लिए मक्खन"],"steps":["प्याज़ को पतले रिंग्स में काटें, टमाटर काटें, और चटनी, मिर्च और धनिया छोटे कटोरों में तैयार रखें।","तवे पर मध्यम आंच पर थोड़ा तेल गरम करें। शामी कबाब को हर तरफ 2 से 3 मिनट फ्राई करें, जब तक अंदर तक गरम और किनारों पर हल्के कुरकुरे न हो जाएँ।","कबाब निकाल कर गरम रखें। तवा हल्का साफ़ करें, मक्खन डालें, और बन के कटे हुए हिस्से को हल्का सुनहरा होने तक सेंकें, तक़रीबन 1 मिनट।","नीचे वाले बन पर हरी चटनी और ऊपर वाले बन पर इमली की चटनी लगाएँ। पतली तह काफ़ी है, कबाब ही स्टार रहना चाहिए।","हर नीचे वाले बन पर 2 कबाब रखें। अगर कबाब छोटे हों तो थोड़े ओवरलैप कर दें ताकि हर निवाले में कबाब हो।","प्याज़ रिंग्स, टमाटर, हरी मिर्च और धनिया डालें। ठंडा, क्रीमी निवाला पसंद हो तो एक चम्मच फेंटी हुई दही डालें।","बन बंद कर के हल्के से दबाएँ। चटनी सिर्फ़ किनारों तक पहुँचनी चाहिए, टपकनी नहीं चाहिए।","फ़ौरन गरम परोसें, साइड पर ज़्यादा चटनी और ठंडे ड्रिंक के साथ। दोनों हाथों से खाएँ, कराची स्टाइल।"],"tip":"बन को ज़्यादा न सेंकें। हल्का सुनहरा काफ़ी है, वरना सख्त और टूटने वाला हो जाएगा, और कबाब अंदर बैठने के बजाय बाहर फिसल जाएगा।","notes":["शामी कबाब अंदर से नरम और बाहर से हल्के कुरकुरे होने चाहिए। अगर बहुत नरम हों तो फ्राई करने से पहले 15 मिनट ठंडा करें, ताकि शेप रखें।","नरम बर्गर बन लें, सख्त रोल नहीं। बन को कबाब के गिर्द हल्के से दबना चाहिए, लड़ना नहीं चाहिए।","इमली की चटनी मीठी खट्टी नोट देती है। पहले चखें, क्योंकि कुछ बहुत मीठी होती हैं और कम चाहिए।","प्याज़ रिंग्स कुरकुरे रहते हैं अगर परोसने से पहले काटें। कटी हुई प्याज़ देर तक रखी रहे तो नरम और तेज़ हो जाती है।"],"variations":["चिकन बन कबाब: चिकन शामी कबाब लें और थोड़ी ज़्यादा हरी चटनी डालें, क्योंकि चिकन बीफ़ से हल्का होता है।","अंडा बन कबाब: कबाब के ऊपर तला हुआ अंडा रखें, ज़र्दी सिर्फ़ सेट हो, ज़्यादा रिच स्ट्रीट स्टाइल वर्शन के लिए।","मिर्च वाला बन कबाब: कटी हुई हरी मिर्च और एक चम्मच चिली गार्लिक सॉस डालें, और दही छोड़ दें।"],"serving":"4 लोगों के लिए, हर शख्स को 1 बन कबाब, ज़्यादा चटनी, और साइड पर सादी सलाद या फ्राइज़ काफ़ी है। बन कबाब स्ट्रीट फ़ूड है, इसलिए इसे कागज़ में लपेट कर या प्लेट में, तवे से गरम परोसें, और फ़ौरन खाएँ। इसके साथ ठंडी लस्सी, फ़िज़ी ड्रिंक, या चाय अच्छी लगती है। बड़ी भीड़ के लिए बन, कबाब और चटनी मेज़ पर रखें और लोग खुद बनाएँ।","storage":"बन कबाब ताज़ा खाना बेहतरीन है और असेंबल करने के बाद अच्छा नहीं रहता, क्योंकि बन चटनी पी लेता है। हिस्से अलग रखें। पके हुए शामी कबाब फ्रिज में 2 दिन तक रहते हैं और तवे पर दोबारा गरम होते हैं। चटनी बंद जार में फ्रिज में 4 दिन तक रहती है। परोसने से पहले ही सेंकें और असेंबल करें, ताकि बन नरम और कबाब गरम रहे।","mistakes":["बन को ज़्यादा सेंकना। वो सख्त हो जाता है, टूट जाता है, और फिलिंग बाहर गिर जाती है।","कबाब को चटनी में डुबोना। बैलेंस खत्म हो जाता है और बन मिनटों में गीला हो जाता है।","कबाब को बहुत तेज़ आंच पर फ्राई करना। बाहर जल जाता है और बीच में ठंडा रह जाता है।","जल्दी असेंबल करना। बन नमी पी लेता है और कुरकुरे किनारे खाने से पहले नरम हो जाते हैं।"],"faq":[["शामी कबाब क्या होता है?","नरम कबाब जो कीमे और दाल से बनता है, पका कर, पीस कर और शेप दे कर, फिर फ्राई किया जाता है। ये बन में दबने के लिए नरम होता है, सख्त सीख कबाब की तरह नहीं।"],["क्या फ्रोज़न शामी कबाब इस्तेमाल कर सकते हैं?","जी हाँ। फ्रोज़न ही मध्यम आंच पर फ्राई करें, हर तरफ 1 से 2 मिनट ज़्यादा दें, जब तक अंदर तक गरम न हो जाए। पहले थॉ न करें, क्योंकि नरम कबाब टूट जाते हैं।"],["सबसे अच्छा बन कौन सा है?","नरम, सादा बर्गर बन। तिल वाला बन भी चल जाता है। सख्त रोल न लें, क्योंकि वो टूट जाता है और फिलिंग बाहर गिर जाती है।"],["क्या इमली की चटनी के बिना बना सकते हैं?","जी हाँ। ज़्यादा हरी चटनी और नींबू का रस खट्टापन के लिए इस्तेमाल करें। ज़ायका अलग होता है, लेकिन फिर भी अच्छा काम करता है।"]]},"gulabjamun":{"intro":"गुलाब जामुन वो मिठाई है जो अक्सर सेलिब्रेशन के आखिर में आती है, नरम, गरम, और गुलाब की खुशबू वाली चाशनी में डूबी हुई जब तक वो इससे भरी न हो जाए। राज़ इंग्रीडिएंट्स की लंबी लिस्ट नहीं है। ये ताज़ा और नरम खोया है, हल्के हाथ से गूँधा हुआ आटा, हल्की आंच पर फ्राइंग ताकि जामुन अंदर तक पक जाएँ बिना जल्दी ज़्यादा ब्राउन हुए, और चाशनी जो गरम हो, उबलती हुई नहीं, जब वो इसमें जाएँ। किसी भी हिस्से में जल्दी करें तो जामुन सख्त, दरार वाले, या अंदर से सूखे हो जाते हैं। समय लें, और वो फूल जाएँगे, नरम होंगे, और चमकेंगे। इन्हें गरम परोसें, ऊपर चाशनी डाल कर, और देखें कि कैसे खत्म हो जाते हैं।","ing":["खोया 250g","मैदा 3 tbsp","इलायची पाउडर 1/2 tsp","चीनी 2 कप","पानी 2 कप","गुलाब का पानी 1 tsp","नींबू की 2 बूँदें","तलने के लिए तेल / घी"],"steps":["खोये को तोड़ कर मैदा और इलायची के साथ गूँधें जब तक नरम, हमवार आटा न बन जाए। ज़्यादा न गूँधें, वरना जामुन घने हो जाएँगे।","आटे को ढक कर 15 मिनट आराम दें। वो इतना नरम होना चाहिए कि बिना दरार के रोल हो जाए।","चीनी, पानी और नींबू रस को गरम कर के चाशनी बनाएँ जब तक चीनी घुल न जाए। 5 मिनट सिमर करें, इलायची और गुलाब का पानी डालें, और गरम रखें, उबलता हुआ नहीं।","हथेलियों पर हल्का घी लगाएँ। छोटी, हमवार गोलियाँ बनाएँ, अखरोट के साइज़ की, सतह पर कोई दरार न हो।","तेल या घी को हल्की से मध्यम हल्की आंच पर गरम करें। तेल इतना गरम हो कि हल्के से सिज़ल करे, फ़ौरन ब्राउन करने जितना गरम नहीं।","जामुन को बैच में डालें, चम्मच से हल्के से हिलाते हुए ताकि वो रोल हों और एक जैसे ब्राउन हों, 6 से 8 मिनट, जब तक हल्के सुनहरे न हो जाएँ।","जामुन निकाल कर सीधे गरम चाशनी में डालें। वो हल्के से सिज़ल करेंगे और फूलना शुरू कर देंगे।","कम से कम 1 घंटा आराम दें, एक बार पलट कर, ताकि जामुन एक जैसे चाशनी पीएँ। गरम परोसें, ऊपर चाशनी डाल कर।"],"tip":"जामुन में दरार नहीं होनी चाहिए। गोलियाँ बनाते वक़्त हाथों पर हल्का घी लगाएँ। चाशनी ज़्यादा गरम न हो, वरना जामुन पीने के बजाय सख्त हो जाएँगे, और ठंडी भी न हो, वरना वो इसे जज़्ब नहीं करेंगे।","notes":["ताज़ा, नरम खोया नरम जामुन बनाता है। सूखा, टूटने वाला खोया आटे को जोड़ने के लिए एक चम्मच दूध माँगता है।","मैदा सिर्फ़ बाँधने के लिए है। ज़्यादा मैदा सख्त जामुन बनाता है, इसलिए नाप कर डालें और चिपचिपे आटे को ठीक करने के लिए ज़्यादा न डालें, आराम दें।","चाशनी में नींबू रस इसे ठंडा होने पर क्रिस्टलाइज़ होने से रोकता है, इसलिए चाशनी साफ़ और हमवार रहती है।","गुलाब का पानी आंच से उतार कर डालें, ताकि इसकी खुशबू ताज़ी रहे, उबल कर खत्म न हो।"],"variations":["केसर जामुन: एक चुटकी केसर को गरम दूध में भिगो कर चाशनी में डालें, और पिस्ता से गार्निश करें।","स्टफ़्ड जामुन: फ्राई करने से पहले हर गोली के बीच में सूखे मेवे और नट मिक्स का छोटा टुकड़ा दबाएँ।","आइसक्रीम के साथ जामुन: गरम जामुन को वनीला आइसक्रीम पर रखें, ऊपर गरम चाशनी डाल कर, गरम और ठंडी डिज़र्ट के लिए।"],"serving":"6 लोगों के लिए, हर शख्स को छोटे कटोरों में 3 से 4 जामुन, खूब चाशनी के साथ काफ़ी है। गरम परोसें, पसंद हो तो कटे हुए पिस्ता से गार्निश करें, और दूसरी बार के लिए ज़्यादा चाशनी जग में रखें। गुलाब जामुन ईद, शादी और डिनर पार्टी के लिए बेहतरीन है, और चम्मच से कटोरे से सीधे खाना बेहतरीन है। इसके बाद चाय का कप क्लासिक फिनिश है।","storage":"चाशनी में ढके हुए डिब्बे में फ्रिज में 4 दिन तक रखें। चाशनी में हल्की आंच पर आहिस्ता दोबारा गरम करें, या माइक्रोवेव में 20 से 30 सेकंड, जब तक गरम हो, ज़्यादा गरम नहीं। इन्हें चाशनी में न उबालें, क्योंकि वो टूट जाते हैं। चाशनी के बिना 1 महीने तक फ्रीज़ करें, फ्रिज में थॉ करें, और परोसने से पहले ताज़ी चाशनी में गरम करें।","mistakes":["तेज़ आंच पर फ्राई करना। बाहर जल्दी डार्क हो जाता है और अंदर कच्चा और घना रह जाता है।","दरार वाली गोलियाँ बनाना। चाशनी एक जैसी नहीं जाती और जामुन फट जाते हैं या खुरदुरे हो जाते हैं।","जामुन को उबलती हुई चाशनी में डालना। सतह बंद हो जाती है और वो अंदर से सख्त रहते हैं।","आटे को ज़्यादा गूँधना। वो सख्त हो जाता है और जामुन अपनी नरमी खो देते हैं।"],"faq":[["मेरे गुलाब जामुन सख्त क्यों हैं?","आटा ज़्यादा गूँधा गया, ज़्यादा मैदा इस्तेमाल हुआ, या चाशनी ज़्यादा गरम थी। हल्के से गूँधें, मैदा नाप कर डालें, और चाशनी को गरम रखें, उबलता हुआ नहीं।"],["क्या खोये की जगह मिल्क पाउडर इस्तेमाल कर सकते हैं?","जी हाँ। 1 कप मिल्क पाउडर को 2 tbsp घी और 3 से 4 tbsp गरम दूध के साथ नरम आटा बना लें, फिर वही स्टेप फॉलो करें। टेक्सचर करीब होता है, हालाँकि खोया ज़्यादा नरम होता है।"],["मेरे जामुन चाशनी में क्यों टूट गए?","वो कम फ्राई हुए, आटा ज़्यादा नरम था, या चाशनी उबल रही थी। हल्के सुनहरे और सख्त होने तक फ्राई करें, और चाशनी को गरम रखें।"],["क्या चाशनी कम मीठी बना सकते हैं?","चीनी को 1½ कप तक कम कर सकते हैं, लेकिन चाशनी को जामुन को ढकना चाहिए। बहुत पतली चाशनी वही तरीके से नहीं पीती, इसलिए इससे ज़्यादा कम न करें।"]]},"gajarhalwa":{"intro":"गाजर का हलवा सर्दियों का कटोरा है, लाल गाजर दूध में आहिस्ता पकती है जब तक दूध खत्म न हो जाए, फिर घी में चीनी के साथ भुनी जाती है और खोया, इलायची और नट्स से मुकम्मल होती है। ये जल्दी वाली डिज़र्ट नहीं है, और यही इसकी बात है। लंबी, हल्की कुकिंग कद्दूकस की हुई गाजर को नरम, रिच और गहरे ज़ायके वाली चीज़ बना देती है, और कोई शॉर्टकट वैसा ज़ायका नहीं देता। लाल गाजर मिले तो वही लें, बारीक कद्दूकस करें, और आंच हल्की रखें। इसे गरम परोसें, ऊपर खोये का चम्मच डाल कर, और अगले दिन के लिए कुछ बचा लें, क्योंकि फिर और बेहतर लगता है।","ing":["लाल गाजर 1 kg (कद्दूकस की हुई)","दूध 1 लीटर","चीनी 1 कप","घी 4 tbsp","खोया 150g","इलायची 4","बादाम / पिस्ता"],"steps":["गाजर को धो कर, छील कर बारीक कद्दूकस करें। बारीक कद्दूकस अहम है, क्योंकि मोटी श्रेड्स ज़्यादा समय लेती हैं और खुरदुरी रहती हैं।","गाजर और दूध को भारी कड़ाही में रखें। उबाल लाएँ, फिर हल्की आंच कर दें।","बिना ढके हल्की आंच पर 35 से 45 मिनट पकाएँ, हर कुछ मिनट में हिलाते हुए, जब तक दूध तक़रीबन सूख न जाए।","घी डाल कर गाजर को हिलाते हुए 8 से 10 मिनट भूनें, जब तक मिश्रण चमकीला न हो जाए और किनारों को छोड़ने लगे।","चीनी डाल कर 8 से 10 मिनट और पकाएँ, हिलाते हुए, जब तक चीनी घुल न जाए और हलवा दोबारा गाढ़ा न हो जाए।","इलायची कूट कर खोये के साथ डालें। 5 मिनट हिलाते हुए पकाएँ, जब तक खोया हलवे में घुल न जाए।","चखें और ठीक करें। ज़्यादा मीठा हो तो नींबू का रस रिवायती नहीं है, इसलिए छोटी पोर्शन बिना मीठी चाय के साथ परोसें।","गरम परोसें, ऊपर कटे हुए बादाम और पिस्ता और थोड़ा ज़्यादा खोया डाल कर।"],"tip":"गाजर बारीक कद्दूकस करें। मोटी गाजर देर से पकती है और हलवा खुरदुरा रहता है, चाहे कितनी देर हिलाएँ, इसलिए शुरू में कद्दूकस करने में समय लें।","notes":["लाल गाजर ज़्यादा मीठी होती है और गहरा रंग देती है। नारंगी गाजर भी चल जाती है, लेकिन हलवा हल्के रंग का होता है और थोड़ी ज़्यादा चीनी चाहिए।","फुल फैट दूध ज़्यादा रिच नतीजा देता है। लो फैट दूध को कम होने में ज़्यादा समय लगता है और ज़ायका पतला होता है।","आखिर में खोया रिचनेस और बॉडी देता है। अच्छा खोया खरीदना वर्थ है, या ज़रूरत हो तो पनीर को तोड़ कर सब्स्टिट्यूट बना लें।","इलायची को ताज़ा कूटना चाहिए। पहले से पिसी हुई इलायची की खुशबू जल्दी खत्म हो जाती है।"],"variations":["मिल्क पाउडर हलवा: आधे दूध की जगह 1 कप मिल्क पाउडर गाजर में मिला दें, जल्दी और रिच वर्शन के लिए।","नटी हलवा: खोये के साथ कटे हुए काजू और किशमिश डालें, और नट्स को पहले घी में टोस्ट करें।","कम मीठा हलवा: चीनी 3/4 कप कर दें। हलवा गाजर से फिर भी मीठा होता है, और आइसक्रीम के साथ परोसने के लिए बेहतरीन है।"],"serving":"5 लोगों के लिए, छोटे कटोरों में, गरम, कटे हुए नट्स और ऊपर खोये के चम्मच के साथ काफ़ी है। गाजर का हलवा सर्दियों की डिज़र्ट है, डिनर के बाद या दोपहर की चाय के साथ परोसी जाती है। गरम हलवे पर वनीला आइसक्रीम का स्कूप पॉपुलर मॉडर्न सर्विंग है, और गरम और ठंडे का कॉन्ट्रास्ट खूबसूरत लगता है। पोर्शन छोटी रखें, क्योंकि ये रिच है।","storage":"ठंडा कर के एयरटाइट डिब्बे में फ्रिज में 4 दिन तक रखें। पैन में हल्की आंच पर थोड़े दूध के साथ हिलाते हुए दोबारा गरम करें, जब तक अंदर तक गरम न हो जाए। माइक्रोवेव में छोटे बर्स्ट में भी अच्छा गरम होता है। हिस्सों में 1 महीने तक फ्रीज़ करें, फ्रिज में थॉ करें, और थोड़े दूध के साथ दोबारा गरम करें। ताज़े नट्स परोसते वक़्त डालें, क्योंकि रखे हुए नट्स नरम हो जाते हैं।","mistakes":["तेज़ आंच पर पकाना। दूध लग कर जल जाता है, और हलवा जला हुआ लगता है।","चीनी जल्दी डालना। इससे पानी निकलता है और गाजर कम होने के बजाय उबल जाती है, इसलिए दूध सूखने के बाद डालें।","मोटा कद्दूकस करना। हलवा चाहे कितनी देर पके, स्ट्रिंगी और खुरदुरा रहता है।","घी में भूनने का स्टेज छोड़ना। इसके बिना हलवा उबला हुआ लगता है, रिच और चमकीला नहीं।"],"faq":[["क्या नारंगी गाजर इस्तेमाल कर सकते हैं?","जी हाँ। हलवा हल्के रंग का और थोड़ा कम मीठा होता है, इसलिए चखें और ज़रूरत हो तो 1 से 2 tbsp ज़्यादा चीनी डालें। लाल गाजर सर्दियों के हलवे के लिए रिवायती है।"],["कैसे पता चलेगा कि दूध काफ़ी कम हो गया है?","मिश्रण सूखा लगता है, गाजर इकट्ठी रहती है, और हिलाते वक़्त किनारों पर घी अलग होता नज़र आता है। वही समय है घी डाल कर भूनने का।"],["क्या खोये के बिना बना सकते हैं?","जी हाँ। फिर भी अच्छा होता है, बस कम रिच होता है। आखिर में 2 एक्स्ट्रा tbsp घी और 2 tbsp मिल्क पाउडर डालें, या नरम पनीर तोड़ कर डालें।"],["गाजर का हलवा गरम परोसा जाता है या ठंडा?","गरम बेहतरीन है, कड़ाही से सीधे या हल्के से दोबारा गरम कर के। फ्रिज से ठंडा हलवा सख्त और कम खुशबूदार होता है, इसलिए परोसने से पहले गरम करें।"]]},"lassi":{"intro":"मैंगो लस्सी गर्मियों का गिलास है, पके हुए आम ठंडे दही, थोड़े दूध, और इलायची के साथ ब्लेंड किए जाते हैं, जब तक वो गाढ़ी, हमवार और इतनी ठंडी न हो जाए कि आपको ठंडा कर दे। इसमें 15 मिनट लगते हैं, ज़्यादा समय आम छीलने में है, और इसमें पकाना बिल्कुल नहीं है। आम की क्वालिटी सब कुछ तय करती है, इसलिए वो फल चुनें जो डंठल पर मीठी खुशबू दे, दबाने पर हल्का दबे, और जिसमें हरा, सख्त हिस्सा न हो। इसे फ़ौरन ठंडे गिलास में परोसें, ऊपर थोड़ा कटा हुआ आम डाल कर, और पीएँ जब तक ब्लेंडर का फोम ऊपर हो।","ing":["पके हुए आम 2","दही 1½ कप","दूध 1/2 कप","चीनी 2 tbsp (स्वाद के अनुसार)","इलायची पाउडर 1/4 tsp","बर्फ़ के टुकड़े (पुदीना गार्निश के लिए)"],"steps":["गिलास को फ्रिज में 15 मिनट ठंडा करें, ताकि लस्सी पीते वक़्त ठंडी रहे।","आम छील कर गुठली से गूदा अलग करें, और मोटा-मोटा काट लें। एक टुकड़ा चखें और तय करें कि कितनी चीनी चाहिए।","आम, दही, दूध, चीनी और इलायची ब्लेंडर में डालें। बर्फ़ अभी न डालें।","30 सेकंड ब्लेंड करें, रोकें, किनारों को स्क्रैप करें, और 30 सेकंड और ब्लेंड करें, जब तक बिल्कुल हमवार न हो जाए।","मुट्ठी भर बर्फ़ के टुकड़े डालें और 15 से 20 सेकंड और ब्लेंड करें, सिर्फ़ जब तक बर्फ़ कूट जाए और लस्सी गाढ़ी और ठंडी न हो जाए।","चखें और ठीक करें। आम खट्टा हो तो थोड़ी ज़्यादा चीनी डालें, या ज़्यादा गाढ़ी हो तो थोड़ा दूध डालें।","फ़ौरन ठंडे गिलास में डालें, फोम ऊपर रहने दें।","कटे हुए आम और पुदीने के पत्ते से गार्निश करें, और स्ट्रॉ या चम्मच के साथ फ़ौरन परोसें।"],"tip":"आम जितना मीठा, चीनी उतनी कम चाहिए। लस्सी पहले से न बनाएँ। ताज़ी ब्लेंड की हुई बेहतरीन होती है, क्योंकि रखी रहने पर अलग हो जाती है और फोम खत्म हो जाता है, और बर्फ़ पिघल कर इसे पतला कर देती है।","notes":["मौसम में सिंधरी, चौंसा या अल्फांसो जैसे पके, मीठे आम इस्तेमाल करें। रेशे वाले आम स्ट्रिंगी लस्सी बनाते हैं, इसलिए ज़रूरत हो तो छान लें।","फुल फैट दही गाढ़ी, क्रीमी लस्सी देती है। लो फैट दही भी चल जाती है, लेकिन लस्सी पतली होती है और कम दूध चाहिए।","इलायची बैकग्राउंड नोट होनी चाहिए, असल ज़ायका नहीं। 3 गिलास के लिए क्वार्टर tsp काफ़ी है।","सब कुछ पहले ठंडा करें। ठंडा आम, ठंडा दही और ठंडा दूध मतलब कम बर्फ़ चाहिए, और ज़ायका स्ट्रॉन्ग रहता है।"],"variations":["मैंगो बनाना लस्सी: 1 पका हुआ केला डालें, गाढ़ी, मीठी लस्सी के लिए जो बच्चों को पसंद आती है।","मैंगो रोज़ लस्सी: 1 tsp गुलाब का पानी और एक चुटकी केसर डालें, और गुलाब की पंखुड़ियों से गार्निश करें।","वीगन लस्सी: कोकोनट दही और ओट दूध इस्तेमाल करें, और स्वाद के अनुसार मेपल सिरप या चीनी से मीठा करें।"],"serving":"3 लोगों के लिए, लंबे ठंडे गिलास में, ऊपर कटे हुए आम और पुदीने के साथ काफ़ी है। मैंगो लस्सी गरम दोपहर, मिर्च वाले खाने, और गर्मियों के वीकेंड के नाश्ते के लिए बेहतरीन है। इसे पराठे और अचार के साथ ड्रिंक के तौर पर, या मिर्च वाली करी के बाद हल्की डिज़र्ट के तौर पर परोसें। डालने के समय तक ठंडा रखें, और ताज़ी पीएँ।","storage":"बेहतरीन टेक्सचर के लिए ताज़ी पीएँ। लस्सी बंद जार में फ्रिज में 1 दिन तक रहती है, लेकिन अलग हो जाती है, इसलिए परोसने से पहले अच्छी तरह हिलाएँ या शेक करें, और फोम वापस आने की उम्मीद न रखें। लस्सी को फ्रीज़ न करें, क्योंकि थॉ होने पर दही दाने वाली हो जाती है। अगर पहले से बनाना ही हो तो आम और दही को बर्फ़ के बिना ब्लेंड करें, फ्रिज में रखें, और परोसने से पहले बर्फ़ डाल कर दोबारा ब्लेंड करें।","mistakes":["कच्चा आम इस्तेमाल करना। कितनी भी चीनी खट्टे, सख्त ज़ायके को ठीक नहीं करती, इसलिए पके हुए फल का इंतज़ार करें।","बर्फ़ के साथ ज़्यादा ब्लेंड करना। लस्सी गाढ़ी और क्रीमी होने के बजाय पानी वाली और पतली फोमी हो जाती है।","शुरू में ज़्यादा दूध डालना। वो लस्सी को पतला कर देता है पहले ही, इसलिए दूध थोड़ा-थोड़ा डालें।","घंटों पहले बनाना। वो अलग हो जाती है, रंग हल्का हो जाता है, और ताज़े आम का ज़ायका खत्म हो जाता है।"],"faq":[["क्या फ्रोज़न आम इस्तेमाल कर सकते हैं?","जी हाँ। इसे आधा थॉ करें, ताकि ब्लेंड करने के लिए नरम हो लेकिन फिर भी ठंडा हो, और बर्फ़ आधी कर दें। फ्रोज़न आम बहुत गाढ़ी लस्सी बनाता है, इसलिए दूध थोड़ा-थोड़ा डालें।"],["क्या मैंगो लस्सी हेल्दी है?","ये फल और दही से बनती है, और यहाँ कोई नंबर्स नहीं दिए गए। चीनी वो हिस्सा है जिस पर ध्यान दें, इसलिए पके हुए आम इस्तेमाल करें और जितनी ज़रूरत हो उतनी ही चीनी डालें।"],["क्या लस्सी ब्लेंडर के बिना बना सकते हैं?","जी हाँ, अगर आम बहुत नरम हो। आम को काँटे से मैश करें, दही और दूध व्हिस्क करें, और छलनी से गुज़ारें। वो उतनी हमवार नहीं होती, लेकिन फिर भी मज़ेदार होती है।"],["मेरी लस्सी स्ट्रिंगी क्यों है?","आम रेशे वाला था। ज़्यादा देर ब्लेंड करें, या परोसने से पहले बारीक छलनी से गुज़ारें। अगली बार कम रेशे वाली वैरायटी चुनें।"]]},"pizza":{"intro":"मार्गेरिटा पिज़्ज़ा इस बात का सबूत है कि साधारण खाना भी असाधारण हो सकता है। यह नेपल्स में प्रसिद्ध हुआ, जहाँ गर्म ओवन, पतली क्रस्ट, चमकीली टमाटर सॉस और अच्छा मोज़रेला सारा काम करते हैं। इसके रंग इटली के झंडे की याद दिलाते हैं, लाल टमाटर, सफ़ेद मोज़रेला और हरा तुलसी, और स्वाद भारी नहीं, साफ़ और ताज़ा होता है। इस रेसिपी में आटे को इतनी देर आराम दिया जाता है कि वह हल्का और चबाने लायक हो जाए, सॉस मुश्किल से पकती है, और बहुत गर्म ओवन में क्रस्ट कुछ ही मिनटों में फूल जाती है। आटे और गर्मी पर ध्यान दें, तो घर के ओवन से भी पिज़्ज़ेरिया जैसा पिज़्ज़ा बनेगा।","ing":["मज़बूत ब्रेड आटा 500g","गुनगुना पानी 325ml","इंस्टेंट यीस्ट 7g","बारीक नमक 10g","जैतून का तेल 2 tbsp","सैन मार्ज़ानो टमाटर 400g (कुचले हुए)","फ़ियोर दि लाते मोज़रेला 250g (तोड़ा हुआ)","ताज़े तुलसी के पत्ते 1 मुट्ठी","लहसुन 1 कली","सॉस के लिए जैतून का तेल","नमक","छिड़कने के लिए सूजी या आटा"],"steps":["आटा, पानी, यीस्ट और नमक मिलाकर 8 से 10 मिनट गूँधें जब तक चिकना न हो जाए, फिर ढककर 1 घंटा आराम दें, या बेहतर स्वाद के लिए रात भर फ्रिज में रखें।","टमाटर को लहसुन, चुटकी भर नमक और 1 tbsp जैतून के तेल के साथ कुचल लें। सॉस को पकाएँ नहीं, वह पिज़्ज़ा पर पक जाएगी।","आटे को 4 भागों में बाँट लें, 20 मिनट आराम दें, फिर हर भाग को हाथ से बीच से बाहर की ओर फैलाएँ, किनारे को मोटा रखें।","ओवन को जितना गर्म हो सके, कम से कम 250C पर गर्म करें, अंदर पिज़्ज़ा स्टोन या उल्टी बेकिंग ट्रे 30 मिनट के लिए गर्म करें।","हर बेस पर 3 से 4 tbsp सॉस फैलाएँ, किनारा खाली रखें, और ऊपर तोड़ा हुआ मोज़रेला डालें।","6 से 8 मिनट बेक करें जब तक क्रस्ट फूलकर सुनहरी न हो जाए और चीज़ में बुलबुले न आने लगें।","पिज़्ज़ा निकलते ही तुलसी के पत्ते डालें, ताकि वे हल्के से नरम हो जाएँ और जल न जाएँ।","ऊपर से थोड़ा जैतून का तेल डालें, काटें, और क्रस्ट कुरकुरी रहते ही तुरंत परोसें।"],"tip":"पिज़्ज़ा पर ज़्यादा टॉपिंग न डालें। सॉस की पतली परत और मामूली चीज़ से क्रस्ट अच्छी तरह पकती है और कुरकुरी रहती है।","notes":["ब्रेड आटे से वह चबान मिलती है जो सादा आटा नहीं दे सकता, इसलिए अगर मिले तो वही इस्तेमाल करें, और आटे को तौलकर लें।","फ़ियोर दि लाते पानी में रखा नरम मोज़रेला होता है। इसे निकालकर तोड़ें और हल्का सा सुखा लें, ताकि पिज़्ज़ा गीला न हो।","सैन मार्ज़ानो टमाटर मीठे और कम खट्टे होते हैं। अगर दूसरा टिन इस्तेमाल करें तो अच्छी तरह कुचल लें और ज़रूरत पर ही चुटकी भर चीनी डालें।","पील पर सूजी आटे को चिपकने से रोकती है और हल्की सी कुरकुराहट देती है। सिर्फ आटा तेज़ गर्म ओवन में जल सकता है।"],"variations":["मरीनारा: चीज़ छोड़ दें, ज़्यादा लहसुन और ओरेगैनो डालें, और जैतून के तेल के साथ पूरा करें, डेयरी फ्री पिज़्ज़ा के लिए।","फ़ोर चीज़: टमाटर सॉस की जगह जैतून के तेल की पतली परत लगाएँ, फिर मोज़रेला, गॉर्गोंज़ोला, फ़ॉन्टीना और पार्मेसन डालें।","चेरी टमाटर के साथ: आधे चेरी टमाटर को जैतून के तेल के साथ भूनें, फिर कुचले हुए टमाटर की सॉस की जगह इस्तेमाल करें।"],"serving":"4 लोगों के लिए है, हर व्यक्ति के लिए एक पिज़्ज़ा, या सलाद के साथ बाँटकर खाने के लिए स्लाइस काट लें। ओवन से निकलते ही परोसें, ज़्यादा तुलसी, चिली ऑयल या पार्मेसन मेज़ पर रखें, और हर कोई अपनी मर्ज़ी से डाले। पिज़्ज़ा पहले 10 मिनट में सबसे बेहतरीन होता है, जब बेस कुरकुरा और चीज़ नरम और खिंचने वाली होती है।","storage":"बची हुई स्लाइस फ्रिज में एयरटाइट डिब्बे में 2 दिन तक रखी जा सकती हैं। दोबारा गर्म ओवन या ढक्कन वाली सूखी कड़ाही में गर्म करें, ताकि बेस फिर कुरकुरा हो जाए। माइक्रोवेव से बचें, इससे क्रस्ट नरम हो जाती है। कच्चा आटा फ्रिज में 3 दिन तक और फ्रीज़र में 1 महीने तक रखा जा सकता है, फ्रिज में रात भर रखकर पिघलाएँ।","mistakes":["ठंडा ओवन इस्तेमाल करना। क्रस्ट फूलने के बजाय भाप में पकती है, इसलिए स्टोन या ट्रे को पूरी तरह गर्म करें।","आटे को बेलन से बेलना। इससे हवा निकल जाती है, इसलिए हाथ से फैलाएँ।","ज़्यादा सॉस या चीज़ डालना। बीच गीला रहता है और बेस कुरकुरा नहीं होता।","बहुत गर्म ओवन में बेक करने से पहले तुलसी डालना। वह काली हो जाती है, इसलिए बेक के बाद डालें।"],"faq":[["मेरा पिज़्ज़ा बेस बीच में गीला क्यों होता है?","ओवन या स्टोन पूरी तरह गर्म नहीं था, या सॉस और चीज़ ज़्यादा थी। पूरी तरह प्रीहीट करें, टॉपिंग कम रखें, और सबसे नीचे वाली शेल्फ पर बेक करें।"],["क्या आटा पहले से बना सकता हूँ?","हाँ। गूँधने के बाद 3 दिन तक फ्रिज में रखें। फैलाने से पहले 30 से 45 मिनट कमरे के तापमान पर रखें।"],["क्या पिज़्ज़ा स्टोन ज़रूरी है?","नहीं। ओवन में गर्म की हुई उल्टी भारी बेकिंग ट्रे भी अच्छा काम करती है। कास्ट आयरन पैन से भी कुरकुरा बेस मिलता है।"],["क्या सूखी तुलसी इस्तेमाल कर सकता हूँ?","यहाँ ताज़ी तुलसी बहुत बेहतर है, क्योंकि यही असली स्वाद है। सॉस में सूखी तुलसी ठीक है, लेकिन पूरा करने के लिए ताज़े पत्ते डालें।"]]},"carbonara":{"intro":"असली कार्बोनारा में क्रीम नहीं होती। यह रोम से है, और इसकी सॉस सिर्फ अंडे, पेकोरिनो चीज़, काली मिर्च और ग्वानचाले या पैनचेटा की चर्बी से बनती है, गर्म पास्ता के साथ मिलाकर जब तक वह चमकदार और नरम न हो जाए। अहम बात गर्मी का नियंत्रण है। पैन इतना गर्म होना चाहिए कि अंडे हल्के से सॉस में पक जाएँ, लेकिन इतना गर्म नहीं कि वे स्क्रैम्बल हो जाएँ। जल्दी काम करें, सॉस को ढीला करने के लिए पास्ता का पानी इस्तेमाल करें, और तुरंत परोसें। टाइमिंग सीख लें तो यह सबसे तेज़ और सुकून देने वाली पास्ता डिश में से एक बन जाती है, सिर्फ कुछ सामग्री के साथ और गहरे स्वाद के साथ।","ing":["स्पेगेटी 400g","ग्वानचाले या पैनचेटा 150g (छोटे टुकड़े)","अंडे की ज़र्दी 4","और 1 पूरा अंडा","पेकोरिनो रोमानो 60g (बारीक कद्दूकस)","काली मिर्च 2 tsp (ताज़ी कुटी हुई)","पास्ता के पानी के लिए नमक","परोसने के लिए ज़्यादा पेकोरिनो","मिर्च"],"steps":["स्पेगेटी को अच्छी तरह नमक वाले पानी में अल डेंटे तक उबालें, और छानने से पहले 1 कप पास्ता का पानी बचा लें।","ग्वानचाले या पैनचेटा को सूखे पैन में मध्यम आँच पर 6 से 8 मिनट तलें जब तक किनारे कुरकुरे न हो जाएँ और चर्बी पिघल न जाए।","ज़र्दी, पूरा अंडा, पेकोरिनो और ज़्यादातर काली मिर्च को गाढ़ा पेस्ट बनने तक फेंटें। अगर ज़्यादा सख्त हो तो एक चम्मच पास्ता का पानी डालें।","पैन को आँच से उतार लें और 1 मिनट ठंडा होने दें, ताकि अंडे पैन से मिलते ही स्क्रैम्बल न हों।","छाना हुआ स्पेगेटी पैन में डालें और पिघली हुई चर्बी में 30 सेकंड अच्छी तरह मिलाएँ।","अंडे और चीज़ का मिश्रण डालें और तेज़ और लगातार मिलाएँ, थोड़ा थोड़ा पास्ता का पानी डालते हुए जब तक सॉस चमकदार न हो जाए और हर धागे पर लग न जाए।","चखें, और मिर्च डालें, और नमक सिर्फ ज़रूरत पर डालें, क्योंकि पेकोरिनो और पैनचेटा पहले ही नमकीन हैं।","गर्म कटोरों में तुरंत परोसें, ऊपर ज़्यादा पेकोरिनो और काली मिर्च डालकर।"],"tip":"अंडे डालने से पहले पैन को आँच से उतार लें। बची हुई गर्मी सॉस बनाती है, सीधी आँच अंडे स्क्रैम्बल कर देती है।","notes":["पेकोरिनो रोमानो तेज़ और नमकीन होता है, और यही पारंपरिक चीज़ है। पार्मेसन भी चलती है, लेकिन हल्की होती है, इसलिए थोड़ी ज़्यादा इस्तेमाल करें और नमक डालने से पहले चखें।","ग्वानचाले क्योर्ड पोर्क चीक होता है और क्लासिक स्वाद देता है। पैनचेटा सबसे करीबी आसान विकल्प है, और बेकन भी चलता है, हालाँकि ज़्यादा स्मोकी होता है।","पास्ता का पानी स्टार्च से भरा होता है। यह अंडे की सॉस को स्पेगेटी पर चिपकने में मदद करता है।","ताज़ी कुटी हुई काली मिर्च यहाँ अहम है। यह असली स्वाद है, सिर्फ गार्निश नहीं, इसलिए मोटी कूटें और खूब इस्तेमाल करें।"],"variations":["मटर के साथ: आखिरी मिनट में पास्ता के पानी में एक मुट्ठी मटर डालें, रंग और मिठास के लिए।","शाकाहारी तरीका: पोर्क की जगह मक्खन और जैतून के तेल में तली हुई मशरूम इस्तेमाल करें, और थोड़ी स्मोक्ड पाप्रिका डालें, हालाँकि नतीजा अलग डिश होगी।","हल्का वर्शन: 4 ज़र्दी की जगह 2 पूरे अंडे और 2 ज़र्दी इस्तेमाल करें, और थोड़ी कम चीज़, सॉस फिर भी नरम होगी।"],"serving":"4 लोगों के लिए मुख्य कोर्स के तौर पर है, गर्म कटोरों में, साथ सादा हरी सलाद और कुरकुरी रोटी के साथ। कार्बोनारा एक कटोरे का खाना है, इसलिए साइड डिश हल्की रखें और पास्ता को स्टार रहने दें। मिलाते ही परोसें, क्योंकि सॉस ठंडी होते ही गाढ़ी हो जाती है और नरमी खो देती है।","storage":"कार्बोनारा ताज़ी खाना बेहतर है और दोबारा गर्म करने पर अच्छी नहीं रहती, क्योंकि अंडे की सॉस गाढ़ी होकर फट सकती है। अगर रखना ही हो तो 1 दिन तक फ्रिज में रखें और थोड़े पानी के साथ पैन में बहुत हल्की आँच पर लगातार हिलाते हुए गर्म करें। फ्रीज़ न करें। सिर्फ पका हुआ पास्ता 2 दिन तक रहता है, लेकिन सॉस ताज़ी बनाएँ।","mistakes":["अंडे को आँच पर रखे हुए पैन में डालना। अंडे स्क्रैम्बल हो जाते हैं और सॉस दानेदार हो जाती है।","क्रीम इस्तेमाल करना। इससे अलग, भारी सॉस बनती है और पेकोरिनो का स्वाद छिप जाता है।","पास्ता का सारा पानी फेंक देना। इसके बिना सॉस ज़्यादा गाढ़ी होती है और पास्ता पर नहीं लगती।","चखने से पहले नमक डालना। पेकोरिनो और क्योर्ड पोर्क नमकीन होते हैं, इसलिए पहले चखें।"],"faq":[["क्या ग्वानचाले की जगह बेकन इस्तेमाल कर सकता हूँ?","हाँ। कुरकुरा होने तक तलें, और अगर चर्बी ज़्यादा हो तो थोड़ी निकाल लें। स्वाद ज़्यादा स्मोकी होगा, लेकिन तरीका वही है।"],["मेरी सॉस स्क्रैम्बल क्यों हो गई?","पैन ज़्यादा गर्म था। आँच से उतार लें, एक मिनट ठंडा करें, और अगली बार पास्ता के पानी के साथ जल्दी मिलाएँ।"],["क्या पोर्क के बिना कार्बोनारा बना सकता हूँ?","हाँ, मशरूम या मटर के साथ, लेकिन वह क्लासिक कार्बोनारा जैसा स्वाद नहीं देगा। अंडे और पेकोरिनो की सॉस वही रखें।"],["पास्ता के पानी की मात्रा कैसे मालूम करूँ?","छोटी सी मात्रा से शुरू करें और मिलाते हुए और डालते जाएँ। सॉस चमकदार और ढीली लगनी चाहिए, गाढ़ी और पेस्ट जैसी नहीं।"]]},"sushi":{"intro":"सुशी में पहले चावल अहम हैं, मछली बाद में। जापान में चावल को सिरका, चीनी और नमक से सीज़न किया जाता है, पंखे से ठंडा किया जाता है, और नरमी से संभाला जाता है ताकि हर दाना अलग और चमकदार रहे। यह घर वाला वर्शन सैल्मन और खीरे के रोल बनाता है, जो सीखने में सबसे आसान हैं, बाहर नोरी, बीच में चावल, और फिलिंग की साफ़ लाइन। सुशी ग्रेड सैल्मन इस्तेमाल करें, हाथ गीले रखें, और मज़बूती से लेकिन नरमी से रोल करें। पहला रोल टेढ़ा लग सकता है, और यह सामान्य है। तीसरे रोल तक आकार, कट और आत्मविश्वास सब आ जाते हैं, और नतीजा ताज़ा और साफ़ होता है।","ing":["सुशी चावल 2 कप (कच्चे)","चावल का सिरका 4 tbsp","चीनी 2 tbsp","नमक 1 tsp","नोरी शीट 4","सुशी ग्रेड सैल्मन 300g (स्ट्रिप्स में कटा हुआ)","खीरा 1 (पतली स्टिक्स में कटा हुआ)","मेयोनेज़ 3 tbsp","श्रीराचा 1 tsp (स्पाइसी मेयो के लिए)","परोसने के लिए सोया सॉस","अचार वाला अदरक","वसाबी","तिल 1 tbsp (वैकल्पिक)"],"steps":["चावल को धोएँ जब तक पानी साफ़ न हो जाए, पकाएँ, फिर ढककर 10 मिनट आराम दें।","सिरका, चीनी और नमक को गर्म करें जब तक घुल न जाएँ, गर्म चावल में हल्के से मिलाएँ, और पंखा झलकर ठंडा करें जब तक हल्का गर्म और चमकदार न हो जाए।","नोरी शीट को चमकदार तरफ नीचे बाँस की चटाई पर रखें, हाथ गीले करें, और चावल की पतली बराबर परत फैलाएँ, दूर वाले किनारे पर 2cm खाली रखें।","बीच में स्पाइसी मेयो की पतली लाइन लगाएँ, सैल्मन और खीरे की स्टिक्स एक साफ़ कतार में रखें, और तिल छिड़कें।","चटाई के करीबी किनारे को उठाएँ और अपनी तरफ से दूर मज़बूती से रोल करें, फिलिंग को अंदर करते हुए, और खाली किनारे को थोड़े पानी से बंद करने के लिए हल्का दबाएँ।","रोल को 2 मिनट आराम दें, फिर गीले तेज़ चाकू से 8 हिस्सों में काटें, हर कट के बीच ब्लेड को पोंछें।","बचे हुए चावल और फिलिंग के साथ दोहराएँ, हाथ गीले रखते हुए।","हिस्सों को कटी हुई तरफ ऊपर रखकर सजाएँ, और सोया सॉस, अचार वाले अदरक और थोड़ी सी वसाबी के साथ परोसें।"],"tip":"पास में पानी का कटोरा रखें और हाथ और चाकू अक्सर गीला करें। गीले हाथ चावल को चिपकने से रोकते हैं, और गीला ब्लेड रोल को दबाए बिना साफ़ काटता है।","notes":["सुशी चावल छोटे दाने वाला चावल होता है। लंबे दाने वाला चावल उसी तरह नहीं चिपकता, इसलिए साफ़ रोल के लिए इसे बदलें नहीं।","सुशी ग्रेड का मतलब है कच्चा खाने के लिए बेची जाने वाली मछली, जो पकड़े जाने से लेकर बिकने तक ठंडी रखी जाए। मछली वाले से पूछें, और आम मछली इस्तेमाल न करें जो पकाने के लिए होती है।","चावल का सिरका हल्का और मीठा होता है। इसकी जगह तेज़ माल्ट सिरका न इस्तेमाल करें, जो चावल पर हावी हो जाएगा।","नोरी कुरकुरी और गहरी होनी चाहिए। इसे बंद और सूखा रखें, क्योंकि गीली नोरी फट जाती है और साफ़ रोल नहीं होती।"],"variations":["टूना रोल: सैल्मन की जगह सुशी ग्रेड टूना इस्तेमाल करें, और खीरे की जगह एवोकाडो डालें।","पके हुए प्रॉन रोल: पके हुए प्रॉन, खीरा और थोड़ी मेयो इस्तेमाल करें, अगर आप कच्ची मछली नहीं चाहते तो अच्छा चुनाव है।","सब्ज़ी रोल: खीरा, एवोकाडो, गाजर की स्टिक्स और अचार वाली मूली इस्तेमाल करें, तिल के साथ, पूरी शाकाहारी रोल के लिए।"],"serving":"4 लोगों के लिए हल्के खाने के तौर पर है, हर व्यक्ति के लिए 2 रोल, या मिसो सूप और सलाद के साथ बड़े जापानी खाने के हिस्से के तौर पर। काटने के तुरंत बाद कमरे के तापमान पर परोसें, सोया सॉस के साथ, हर टुकड़े के बीच मुँह साफ़ करने के लिए अचार वाला अदरक, और वसाबी कम इस्तेमाल करें। सुशी हाथ से खाने वाला खाना है, इसलिए चॉपस्टिक्स और छोटी प्लेटें रखें, और हर कोई खुद परोसे।","storage":"सुशी उसी दिन खाना बेहतर है, रोल करने के कुछ घंटों के अंदर। फ्रिज चावल को सूखा और मछली को बेस्वाद कर देता है, इसलिए एक दिन पहले न बनाएँ। अगर रखना ही हो तो कसकर ढककर 6 घंटे तक फ्रिज में रखें, फिर परोसने से 20 मिनट पहले कमरे के तापमान पर ले आएँ। सुशी को फ्रीज़ न करें। सिर्फ पका हुआ सुशी चावल फ्रिज में 1 दिन तक रहता है।","mistakes":["गर्म चावल इस्तेमाल करना। यह नोरी को नरम कर देता है और रोल टूट जाता है, इसलिए चावल को हल्का गर्म होने तक ठंडा करें।","रोल में ज़्यादा फिलिंग भरना। ज़्यादा फिलिंग से रोल बंद नहीं होता, इसलिए फिलिंग को एक साफ़ कतार तक रखें।","सूखे चाकू से काटना। चावल चिपक जाता है, इसलिए हर कट से पहले ब्लेड गीला करें।","रोल करते हुए ज़्यादा ज़ोर लगाना। चावल दब जाता है और फिलिंग बाहर निकल आती है, इसलिए मज़बूती से लेकिन नरमी से रोल करें।"],"faq":[["क्या घर पर कच्चा सैल्मन खाना सुरक्षित है?","सिर्फ तब जब वह भरोसेमंद दुकान से सुशी ग्रेड सैल्मन हो, ठंडा रखा गया हो, और उसी दिन खाया जाए। शक हो तो पके हुए प्रॉन या सब्ज़ी इस्तेमाल करें।"],["क्या बाँस की चटाई के बिना सुशी बना सकता हूँ?","हाँ। क्लिंग फिल्म के नीचे चाय का तौलिया, या बेकिंग पेपर इस्तेमाल करें। चटाई आसान बना देती है, लेकिन ज़रूरी नहीं।"],["मेरा चावल चिपचिपा और नरम क्यों है?","वह काफी धोया नहीं गया, या सीज़न करते हुए ज़ोर से हिलाया गया। अच्छी तरह धोएँ और सीज़निंग को नरमी से मिलाएँ।"],["क्या चावल पहले से बना सकता हूँ?","हाँ, कुछ घंटे पहले। कमरे के तापमान पर ढककर रखें, फ्रिज में नहीं, और परोसने से पहले ही रोल करें।"]]},"ramen":{"intro":"रामेन एक कटोरे में सुकून है, और अच्छी घर वाली वर्शन के लिए सारा दिन सिमर होने वाली ब्रॉथ की ज़रूरत नहीं। यह चिकन रामेन जल्दी स्वाद बनाता है, लहसुन, अदरक और हरी प्याज़ को तिल के तेल में तलकर, चिकन स्टॉक को सोया और मिसो से गहरा करके, और नूडल्स को अलग पकाकर ताकि ब्रॉथ साफ़ रहे और नूडल्स स्प्रिंगी रहें। अंडा आखिरी टच है, बीच में नरम और ब्रॉथ से सीज़न्ड होता हुआ। टॉपिंग छोटे कटोरों में रखें और हर कोई अपना कटोरा खुद बनाए, गर्म ब्रॉथ आखिर में, ताकि नूडल्स बैठकर नरम न हों। यह तेज़, गर्म और बहुत सुकून देने वाला है।","ing":["चिकन ब्रेस्ट या थाई 500g","चिकन स्टॉक 1.5 लीटर","रामेन नूडल्स 4 हिस्से","लहसुन 4 कली","अदरक 3cm टुकड़ा","सोया सॉस 3 tbsp","मिसो पेस्ट 2 tbsp","तिल का तेल 1 tbsp","हरी प्याज़ 4","अंडे 4 (नरम उबले हुए)","परोसने के लिए चिली ऑयल","तिल","नोरी"],"steps":["अंडे को 6.5 मिनट उबालें, ठंडे पानी में ठंडा करें, छील लें, और परोसने से पहले आधा काटें।","बड़े पॉट में तिल का तेल गर्म करें, लहसुन, अदरक और हरी प्याज़ के सफ़ेद हिस्से को 2 मिनट तलें जब तक खुशबू न आए।","चिकन स्टॉक डालें, सोया सॉस डालें, और 15 मिनट हल्की आँच पर सिमर करें ताकि स्वाद मिल जाएँ।","चिकन को सिमर होती ब्रॉथ में 12 से 15 मिनट पकाएँ जब तक पक न जाए, फिर निकालकर स्लाइस करें और गर्म रखें।","मिसो को एक करछी गर्म ब्रॉथ के साथ फेंटें जब तक नरम न हो जाए, फिर वापस पॉट में मिलाएँ। मिसो डालने के बाद तेज़ न उबालें।","नूडल्स को पैकेट के अनुसार अलग पकाएँ, अच्छी तरह छानें, और 4 गर्म कटोरों में बाँट लें।","गर्म ब्रॉथ नूडल्स पर डालें, ऊपर चिकन की स्लाइस, अंडे के आधे हिस्से, हरी प्याज़ और तिल रखें।","चिली ऑयल और नोरी के साथ तुरंत परोसें, और ब्रॉथ के भाप करते हुए खाएँ।"],"tip":"नूडल्स को अलग पकाएँ। ब्रॉथ में पके हुए नूडल्स ब्रॉथ को सोख लेते हैं, ब्रॉथ को गंदा कर देते हैं, और परोसने से पहले नरम हो जाते हैं।","notes":["मिसो गहराई और नमक डालता है। सफ़ेद मिसो हल्का और मीठा होता है, लाल मिसो तेज़ होता है, इसलिए लाल इस्तेमाल करें तो कम से शुरू करें।","ताज़े रामेन नूडल्स 2 से 3 मिनट में पकते हैं और स्प्रिंगी रहते हैं। सूखे नूडल्स भी चलते हैं, लेकिन पैकेट का समय देखें और ज़्यादा न पकाएँ।","अदरक को कटा हुआ होना चाहिए, बारीक नहीं, ताकि वह ब्रॉथ को गंदा या दानेदार किए बिना स्वाद दे।","तिल का तेल स्वाद के लिए है, तेज़ आँच पर तलने के लिए नहीं। मध्यम आँच पर शुरू में डालें, और धुआँ न निकलने दें।"],"variations":["स्पाइसी रामेन: मिसो के साथ ब्रॉथ में 1 tbsp चिली पेस्ट या गोचुजांग मिलाएँ।","सब्ज़ी रामेन: चिकन की जगह मशरूम और टोफू इस्तेमाल करें, और सब्ज़ी का स्टॉक इस्तेमाल करें, वही खुशबूदार सामग्री रखते हुए।","पोर्क रामेन: चिकन की जगह पतली कटी हुई पकी हुई पोर्क इस्तेमाल करें, और ऊपर स्वीटकॉर्न और बीन स्प्राउट डालें।"],"serving":"4 लोगों के लिए है, गहरे कटोरों में, चॉपस्टिक्स और सूप के चम्मच के साथ, और टॉपिंग मेज़ के बीच में। ब्रॉथ को भाप करते हुए परोसें, ज़्यादा चिली ऑयल, सोया सॉस और तिल हाथ में रखें, ताकि हर व्यक्ति अपना कटोरा खुद सीज़न कर सके। रामेन तुरंत खाया जाता है, जब नूडल्स स्प्रिंगी और अंडा गर्म हो, इसलिए ब्रॉथ डालने से पहले सबको मेज़ पर बुलाएँ।","storage":"ब्रॉथ फ्रिज में 3 दिन तक रहती है, और 1 महीने तक फ्रीज़ हो सकती है। नूडल्स और टॉपिंग मिलाने के बाद अच्छी नहीं रहती, इसलिए अलग रखें और ताज़ा असेंबल करें। ब्रॉथ को उबलने तक गर्म करें, ताज़े नूडल्स पकाएँ, और टॉपिंग परोसने से पहले डालें। बचा हुआ कटा हुआ चिकन फ्रिज में 2 दिन तक रहता है।","mistakes":["मिसो डालने के बाद ब्रॉथ को तेज़ उबालना। इससे स्वाद हल्का हो जाता है, इसलिए हल्की सिमर रखें।","नूडल्स को ज़्यादा पकाना। वे गर्म ब्रॉथ में नरम हो जाते हैं, इसलिए स्प्रिंगी होने तक पकाएँ और अच्छी तरह छानें।","अंडा जल्दी डालना। वह गर्म ब्रॉथ में ज़्यादा पक जाता है, इसलिए आधा अंडा बिल्कुल आखिर में डालें।","ठंडे कटोरों में परोसना। ब्रॉथ जल्दी ठंडी हो जाती है, इसलिए पहले कटोरों को गर्म पानी से गर्म करें।"],"faq":[["क्या इंस्टेंट नूडल्स इस्तेमाल कर सकता हूँ?","हाँ, लेकिन फ्लेवर सैशे फेंक दें और इस ब्रॉथ को इस्तेमाल करें। नूडल ब्लॉक को अलग पकाएँ और अच्छी तरह छानें।"],["क्या ब्रॉथ पहले से बना सकता हूँ?","हाँ। 3 दिन पहले तक बनाकर फ्रिज में रखें। उबलने तक गर्म करें, फिर मिसो ताज़ा डालें और कटोरे असेंबल करें।"],["जैमी अंडा कैसे मिलेगा?","फ्रिज से ठंडा अंडा 6.5 मिनट उबालें, तुरंत ठंडे पानी में ठंडा करें, और नरमी से छीलें। ज़र्दी नरम और हल्की सी सेट होनी चाहिए।"],["क्या रामेन बहुत नमकीन होता है?","हो सकता है। ज़्यादा सोया सॉस डालने से पहले चखें, क्योंकि स्टॉक, सोया और मिसो सब नमक डालते हैं।"]]},"tacos":{"intro":"टैकोस अल पास्टर मेक्सिको सिटी में लेबनानी शावरमा से शुरू हुए, और फिर पूरी तरह मैक्सिकन बन गए, सूखी मिर्चों और अचिओटे में मैरीनेट किया हुआ पोर्क, किनारों पर चर्र, और गर्म कॉर्न टॉर्टिला में अनानास, प्याज़ और धनिया के साथ। मैरीनेड असली काम करता है, इसलिए इसे समय दें, 30 मिनट भी फर्क डालते हैं, और रात भर बेहतर है। पोर्क को तेज़ और जल्दी पकाएँ ताकि वह सूखे बिना चर्र हो जाए, टॉर्टिला को खुली आँच या सूखे पैन में गर्म करें, और टॉपिंग सादी रखें। मीठे अनानास का धुएँदार, मसालेदार पोर्क के साथ मेल ही असली बात है, इसलिए इसे छोड़ें नहीं, और नींबू और साल्सा के साथ परोसें।","ing":["पोर्क शोल्डर 700g (पतली कटी हुई)","सूखी ग्वाजिलो मिर्च 3","अंचो मिर्च 1","अचिओटे पेस्ट 2 tbsp","लहसुन 3 कली","सफ़ेद सिरका 3 tbsp","संतरे का रस 60ml","जीरा 1 tsp","ओरेगैनो 1 tsp","नमक","अनानास 300g (टुकड़ों में कटा हुआ)","कॉर्न टॉर्टिला 12","सफ़ेद प्याज़ 1","धनिया","नींबू 2","अपनी पसंद की साल्सा"],"steps":["सूखी मिर्चों को गर्म पानी में 15 मिनट भिगोएँ जब तक नरम न हो जाएँ, फिर छानें, थोड़ा भिगोया हुआ पानी बचाकर।","मिर्च, अचिओटे, लहसुन, सिरका, संतरे का रस, जीरा, ओरेगैनो और नमक को नरम मैरीनेड बनने तक ब्लेंड करें, ज़रूरत पर भिगोया हुआ पानी डालते हुए।","पोर्क को मैरीनेड में लपेटें, ढककर फ्रिज में कम से कम 30 मिनट, या बेहतरीन स्वाद के लिए रात भर रखें।","बड़े पैन या ग्रिडल को तेज़ आँच पर थोड़े तेल के साथ गर्म करें, और पोर्क को हिस्सों में हर तरफ 3 से 4 मिनट पकाएँ जब तक चर्र न हो जाए और पक न जाए।","उसी गर्म पैन में अनानास के टुकड़ों को हर तरफ 1 से 2 मिनट सेकें जब तक किनारे सुनहरे न हो जाएँ।","पोर्क को छोटे टुकड़ों में काटें और अनानास और पैन के रस के एक चम्मच के साथ मिलाएँ।","टॉर्टिला को सूखे पैन में या आँच पर गर्म करें जब तक नरम और हल्की सी दागदार न हो जाएँ, और कपड़े में लपेटकर रखें।","हर टॉर्टिला में पोर्क और अनानास भरें, ऊपर कटी हुई प्याज़ और धनिया डालें, और नींबू और साल्सा के साथ परोसें।"],"tip":"हिस्सों में पकाएँ और पैन को भरें नहीं। भरा हुआ पोर्क चर्र होने के बजाय भाप में पकता है, और आप वे कुरकुरे किनारे खो देते हैं जो अल पास्टर को खास बनाते हैं।","notes":["अचिओटे पेस्ट लाल रंग और मिट्टी जैसा स्वाद देता है। मैक्सिकन दुकानों या ऑनलाइन से मिलेगा, और सिर्फ फूड कलर से बदलें नहीं।","ग्वाजिलो मिर्च हल्की और फल जैसी होती है। अंचो गहराई डालती है। कम मिर्च चाहिए तो बीज निकाल दें, और सूखी मिर्च को हाथ लगाते हुए दस्ताने पहनें।","पोर्क शोल्डर तेज़ और जल्दी पकाने पर जूसी रहता है। लीन पोर्क लॉइन जल्दी सूखता है, इसलिए पतला काटें और कम समय पकाएँ।","कॉर्न टॉर्टिला पारंपरिक हैं। आटे की टॉर्टिला भी चलती हैं, लेकिन नरम होती हैं और जूसी फिलिंग को कम संभालती हैं।"],"variations":["चिकन अल पास्टर: वही मैरीनेड के साथ चिकन थाई इस्तेमाल करें, और चर्र होने तक पकाएँ, हल्के वर्शन के लिए।","एवोकाडो के साथ: कटा हुआ एवोकाडो और नींबू का रस डालें, अनानास को भी रखते हुए, क्रीमीनेस के लिए।","ज़्यादा स्पाइसी वर्शन: मैरीनेड में 1 चिपोटल इन एडोबो डालें, और साथ गर्म साल्सा परोसें।"],"serving":"4 लोगों के लिए है, हर व्यक्ति के लिए 3 टैको, और नींबू, साल्सा, ज़्यादा प्याज़ और धनिया मेज़ पर। टैको भरते ही परोसें, जब टॉर्टिला गर्म और पोर्क अभी सिज़लिंग हो, और हर कोई अपना नींबू और साल्सा खुद डाले। सादा चावल और बीन्स, या कुरकुरी बंद गोभी की सलाद, टैको को पूरा खाना बना देती है बिना उनसे ध्यान हटाए।","storage":"मैरीनेट किया हुआ कच्चा पोर्क फ्रिज में 1 दिन तक रहता है। पका हुआ पोर्क फ्रिज में 3 दिन तक रहता है, और गर्म पैन में थोड़े पानी के साथ दोबारा गर्म करने पर बेहतर रहता है, ताकि फिर कुरकुरा हो जाए। टॉर्टिला कमरे के तापमान पर लपेटकर 1 दिन, या फ्रिज में 3 दिन तक रहती हैं, और सूखे पैन में गर्म हो जाती हैं। भरे हुए टैको स्टोर न करें, वे गीले हो जाते हैं। अनानास अलग से 2 दिन तक रहता है।","mistakes":["ठंडा पैन इस्तेमाल करना। पोर्क मैरीनेड में उबल जाता है चर्र होने के बजाय, इसलिए पहले पैन को धुआँ निकलने तक गर्म करें।","मैरीनेड का समय छोड़ देना। 30 मिनट भी अहम हैं, और सिर्फ 5 मिनट मैरीनेट किया हुआ पोर्क का स्वाद फीका होता है।","टॉर्टिला में ज़्यादा भरना। वे फट जाती हैं और फिलिंग गिर जाती है, इसलिए हर टैको में 2 से 3 tbsp पोर्क इस्तेमाल करें।","नींबू भूल जाना। खट्टा रस रिच पोर्क को हल्का करता है, इसलिए हमेशा नींबू परोसें।"],"faq":[["क्या पोर्क को ग्रिल कर सकता हूँ?","हाँ। तेज़ आँच पर हर तरफ 3 से 4 मिनट ग्रिल करें, फिर काटकर अनानास के साथ मिलाएँ। ग्रिडल पैन घर के अंदर सबसे करीबी नतीजा देता है।"],["अगर अचिओटे पेस्ट न मिले तो क्या करूँ?","1 tbsp स्मोक्ड पाप्रिका, 1 tsp पिसा जीरा और चुटकी भर हल्दी रंग के लिए इस्तेमाल करें। स्वाद अलग होगा, लेकिन काम चल जाएगा।"],["क्या कॉर्न टॉर्टिला ग्लूटेन फ्री हैं?","सिर्फ मकई, पानी और नींबू से बनी खालिस कॉर्न टॉर्टिला कुदरती तौर पर ग्लूटेन फ्री होती हैं, लेकिन पैकेट पर क्रॉस कंटैमिनेशन चेक करें अगर यह अहम हो।"],["क्या मैरीनेड पहले से बना सकता हूँ?","हाँ। ब्लेंड करके 3 दिन तक फ्रिज में, या 1 महीने तक फ्रीज़ करके रखें। पोर्क को पकाने वाले दिन मैरीनेट करें।"]]},"pozole":{"intro":"पोज़ोले मेक्सिको की सेलिब्रेशन सूप है, होमिनी के साथ बनाई जाती है, बड़े सफ़ेद मकई के दाने जो लंबे सिमर में फूलकर नरम हो जाते हैं, और पोर्क जो चम्मच से टूटने तक पकता है। लाल वर्शन का रंग और गहराई सूखी ग्वाजिलो और अंचो मिर्चों से आती है, जो नरम ब्लेंड करके ब्रॉथ में मिलाई जाती हैं, जबकि टॉपिंग ताज़ी और कुरकुरी रहती है, कटी बंद गोभी, मूली, प्याज़, ओरेगैनो और नींबू। इसमें समय लगता है, लेकिन ज़्यादा समय बिना ध्यान के गुज़रता है, और एक पॉट बहुत लोगों को खिला देता है। वीकेंड पर पकाएँ, ब्रॉथ को रिच और टॉपिंग को अलग रखें, और हर कोई अपना कटोरा मेज़ पर खुद पूरा करे।","ing":["पोर्क शोल्डर 1kg (बड़े टुकड़ों में कटा हुआ)","सफ़ेद होमिनी 800g (छाना, धोया हुआ)","सूखी ग्वाजिलो मिर्च 4","अंचो मिर्च 2","प्याज़ 1","लहसुन 6 कली","तेज़ पत्ता 2","ओरेगैनो 2 tsp","जीरा 1 tsp","नमक","पानी या हल्का स्टॉक 3 लीटर","परोसने के लिए कटी बंद गोभी","मूली","प्याज़","नींबू","परोसने के लिए सूखा ओरेगैनो","चिली फ्लेक्स"],"steps":["सूखी मिर्चों को गर्म पानी में 15 मिनट भिगोएँ, छानें, और लहसुन और थोड़े भिगोए हुए पानी के साथ नरम ब्लेंड करें।","पोर्क, होमिनी, प्याज़, तेज़ पत्ता और पानी को बड़े पॉट में डालें, उबाल ले आएँ, और ऊपर आने वाली झाग उतार लें।","हल्की सिमर पर रखें, आधा ढक दें, और 90 मिनट पकाएँ, अगर पानी कम हो तो गर्म पानी डालते हुए।","ब्लेंड की हुई मिर्च की सॉस को छलनी से छानकर पॉट में डालें, अच्छी तरह मिलाएँ, और नमक, जीरा और ओरेगैनो से सीज़न करें।","30 मिनट और सिमर करें जब तक पोर्क नरम होकर टूटने लगे और ब्रॉथ रिच और लाल हो जाए।","पोर्क निकाल लें, दो काँटों से काट लें, और वापस पॉट में डालें। चखें और नमक और मिर्च ठीक करें।","पोज़ोले पूरा होते हुए टॉपिंग तैयार करें, कटी बंद गोभी, पतली मूली, कटी प्याज़, नींबू और ओरेगैनो।","गहरे कटोरों में डालें, खूब टॉपिंग डालें, और साथ गर्म टॉर्टिला परोसें।"],"tip":"मिर्च की सॉस को डालने से पहले छानें। छलनी छिलके और बीज रोक लेती है, और ब्रॉथ नरम और सिल्की रहती है दानेदार होने के बजाय।","notes":["होमिनी चूने से ट्रीट की हुई मकई होती है, जिससे दाने बड़े, नरम और हज़म में आसान हो जाते हैं। टिन वाली होमिनी तैयार होती है, सूखी होमिनी को रात भर भिगोना और ज़्यादा पकाना पड़ता है।","ग्वाजिलो मिर्च रंग और हल्की फल जैसी गर्मी देती है। अंचो गहरी, किशमिश जैसी गहराई डालती है। दोनों मिलकर क्लासिक लाल ब्रॉथ बनाती हैं।","पोर्क शोल्डर में इतनी चर्बी होती है कि लंबे सिमर में जूसी रहता है। लीन पोर्क सूख जाता है, इसलिए टुकड़े बड़े रखें और सिमर हल्की रखें।","शुरू में झाग उतार लें। इससे ब्रॉथ साफ़ और स्वाद साफ़ रहता है।"],"variations":["हरी पोज़ोले: लाल मिर्चों की जगह टोमैटिलो, हरी मिर्च और धनिया इस्तेमाल करें, ब्लेंड करके उसी तरह डालें।","चिकन पोज़ोले: पोर्क की जगह हड्डी वाली चिकन थाई इस्तेमाल करें, और सिमर का समय लगभग 45 मिनट कर दें।","शाकाहारी पोज़ोले: सब्ज़ी के स्टॉक के साथ मशरूम और बीन्स इस्तेमाल करें, और वही मिर्च सॉस और टॉपिंग डालें।"],"serving":"6 लोगों के लिए है, गहरे कटोरों में, टॉपिंग अलग कटोरों में मेज़ के बीच में। हर व्यक्ति कुरकुराहट के लिए बंद गोभी, बाइट के लिए मूली, प्याज़, ओरेगैनो और खूब नींबू डालता है, जो रिच ब्रॉथ को हल्का करता है। स्कूप करने के लिए गर्म कॉर्न टॉर्टिला के साथ परोसें, और ज़्यादा गर्मी चाहने वालों के लिए ज़्यादा चिली फ्लेक्स साइड पर रखें।","storage":"पोज़ोले फ्रिज में 4 दिन तक रहती है, और रात भर रखने से स्वाद बेहतर हो जाता है। ब्रॉथ और पोर्क को इकट्ठा, और टॉपिंग को अलग रखें। हल्की आँच पर उबलने तक गर्म करें, अगर गाढ़ी हो गई हो तो थोड़ा पानी डालें। 3 महीने तक फ्रीज़ हो सकती है, फ्रिज में रात भर रखकर पिघलाएँ। ताज़ी टॉपिंग को फ्रीज़ न करें।","mistakes":["पूरा समय तेज़ उबालना। पोर्क सख्त हो जाता है और ब्रॉथ गंदा हो जाता है, इसलिए हल्की सिमर रखें।","मिर्च की सॉस को छाने बिना डालना। छिलके और बीज ब्रॉथ को दानेदार बना देते हैं।","ताज़ी टॉपिंग के बिना परोसना। वे सजावट नहीं हैं, वे कुरकुराहट और खट्टेपन से रिच ब्रॉथ को बैलेंस करते हैं।","ब्रॉथ में कम नमक डालना। आखिर में चखें, क्योंकि होमिनी और पोर्क को चमकने के लिए अच्छी मात्रा में नमक चाहिए।"],"faq":[["क्या प्रेशर कुकर इस्तेमाल कर सकता हूँ?","हाँ। पोर्क और होमिनी को प्रेशर पर 35 से 40 मिनट पकाएँ, फिर खुले पॉट में मिर्च सॉस के साथ 10 मिनट पूरा करें।"],["क्या पोज़ोले बहुत स्पाइसी होती है?","लाल वर्शन गर्म होती है, बहुत तेज़ नहीं। हल्की ब्रॉथ के लिए मिर्च के बीज निकाल दें, और मेज़ पर चिली फ्लेक्स से गर्मी डालें।"],["क्या सूखी होमिनी इस्तेमाल कर सकता हूँ?","हाँ, लेकिन रात भर भिगोएँ और पोर्क डालने से पहले नरम होने तक सिमर करें, जिसमें एक घंटा ज़्यादा लग सकता है।"],["पोज़ोले के साथ क्या परोसूँ?","गर्म कॉर्न टॉर्टिला, और यहाँ दी गई ताज़ी टॉपिंग। सादा सलाद की ज़रूरत नहीं, टॉपिंग ही सलाद हैं।"]]},"padthai":{"intro":"पैड थाई थाईलैंड की सबसे प्रसिद्ध नूडल डिश है, और इसका जादू बैलेंस में है, मीठा, खट्टा, नमकीन और थोड़ी गर्मी, सब एक गर्म वोक में। सॉस इमली, फिश सॉस, पाम शुगर और मिर्च से बनती है, और वह चावल के नूडल्स पर लगती है जो भिगोए जाते हैं, उबाले नहीं जाते, ताकि वे नरम होने के बजाय स्प्रिंगी रहें। प्रॉन, अंडा, बीन स्प्राउट और चाइव्स तेज़ आँच पर जल्दी डाले जाते हैं, और डिश को कुटी हुई मूँगफली, नींबू और ज़्यादा स्प्राउट के साथ पूरा किया जाता है। शुरू करने से पहले सब कुछ तैयार रखें, क्योंकि वोक गर्म होते ही पकाना सिर्फ कुछ मिनट लेता है, और यही तेज़ी नूडल्स को नरम होने से बचाती है।","ing":["चपटी चावल नूडल्स 250g","प्रॉन 300g (छीले हुए)","अंडे 2 (हल्के फेंटे हुए)","इमली का पेस्ट 3 tbsp","फिश सॉस 3 tbsp","पाम शुगर या ब्राउन शुगर 3 tbsp","लहसुन 3 कली","चिली फ्लेक्स 1 tsp","बीन स्प्राउट 2 कप","गार्लिक चाइव्स या हरी प्याज़","भुनी मूँगफली 4 tbsp (कुटी हुई)","नींबू 1"],"steps":["चावल के नूडल्स को गुनगुने पानी में 20 से 30 मिनट भिगोएँ जब तक लचीले लेकिन सख्त रहें, फिर अच्छी तरह छानें।","इमली, फिश सॉस, चीनी और चिली फ्लेक्स को मिलाकर सॉस बनाएँ, और चखें। वह एक साथ मीठी, खट्टी और नमकीन होनी चाहिए।","वोक में तेज़ आँच पर तेल गर्म करें, लहसुन को 20 सेकंड तलें, फिर प्रॉन डालें और 2 मिनट पकाएँ जब तक हल्के गुलाबी न हो जाएँ।","प्रॉन को एक तरफ करें, अंडे डालें, और हल्के से स्क्रैम्बल करें जब तक सेट न हो जाएँ, फिर प्रॉन के साथ मिलाएँ।","छाने हुए नूडल्स और सॉस डालें, और 2 से 3 मिनट लगातार मिलाएँ जब तक नूडल्स नरम न हो जाएँ और सॉस सोख न ली जाए।","आधे बीन स्प्राउट और चाइव्स डालें, 30 सेकंड मिलाएँ, और वोक को आँच से उतार लें।","प्लेटों में बाँट लें, ऊपर बचे हुए स्प्राउट, कुटी हुई मूँगफली और हरी प्याज़ डालें।","नींबू, ज़्यादा चिली फ्लेक्स और फिश सॉस के साथ तुरंत परोसें, ताकि हर व्यक्ति अपनी मर्ज़ी से ठीक कर सके।"],"tip":"नूडल्स को भिगोएँ, उबालें नहीं। उबले हुए नूडल्स वोक में ज़्यादा पक जाते हैं और नरम और चिपचिपे हो जाते हैं।","notes":["इमली का पेस्ट खट्टा नोट देता है जो पैड थाई को पहचान देता है। अगर बहुत गाढ़ा हो तो सॉस मिलाने से पहले थोड़े गर्म पानी से पतला करें।","पाम शुगर कैरामल जैसी मिठास में पिघलता है। ब्राउन शुगर अच्छी चलती है, लेकिन सफ़ेद चीनी तेज़ होती है, इसलिए थोड़ी कम इस्तेमाल करें।","फिश सॉस नमकीन और तेज़ खुशबू वाली होती है। इसे सॉस में डालें, सीधा वोक में नहीं, ताकि बराबर मिले।","चपटी चावल नूडल्स मोटाई में अलग होती हैं। पतली नूडल्स जल्दी भीगती हैं, इसलिए 15 मिनट बाद चेक करें और सख्त रहते हुए छानें।"],"variations":["चिकन पैड थाई: प्रॉन की जगह पतली कटी हुई चिकन इस्तेमाल करें, अंडे डालने से पहले अच्छी तरह पकाएँ।","टोफू पैड थाई: सख्त टोफू इस्तेमाल करें, पहले सुनहरा होने तक तलें, शाकाहारी वर्शन के लिए, और चेक करें कि फिश सॉस का विकल्प आपको सूट करता हो।","ज़्यादा सब्ज़ी: नूडल्स के साथ कटी हुई गाजर और कटी बंद गोभी डालें, ज़्यादा कुरकुराहट और रंग के लिए।"],"serving":"4 लोगों के लिए है, गर्म प्लेटों पर, नींबू, कुटी हुई मूँगफली, ज़्यादा बीन स्प्राउट और चिली फ्लेक्स मेज़ पर। पैड थाई स्ट्रीट फूड है, इसलिए गर्म और कैज़ुअल परोसें, हर कोई अपनी प्लेट पर नींबू निचोड़े और अपनी मर्ज़ी से मूँगफली या गर्मी डाले। साथ हल्की खीरे की सलाद ताज़गी देती है, लेकिन ध्यान नूडल्स पर रखें।","storage":"पैड थाई ताज़ी खाना बेहतर है, सीधा वोक से। बचा हुआ खाना फ्रिज में 1 दिन तक रहता है, और गर्म वोक या पैन में थोड़े पानी के साथ लगातार हिलाते हुए दोबारा गर्म होता है। नूडल्स दोबारा गर्म करने पर नरम हो जाते हैं, इसलिए वही टेक्सचर की उम्मीद न रखें। फ्रीज़ न करें। सिर्फ सॉस फ्रिज में 1 हफ्ते तक रहती है।","mistakes":["नूडल्स को ज़्यादा पकाना। छानने पर सख्त होने चाहिए, क्योंकि वे सॉस में पककर पूरे होते हैं।","वोक का काफी गर्म न होना। नूडल्स भाप में पकते हैं और चिपक जाते हैं, इसलिए वोक को धुआँ निकलने तक गर्म करें।","सारे स्प्राउट जल्दी डालना। वे मुरझाकर नरम हो जाते हैं, इसलिए आधे आखिर में डालें और आधे टॉपिंग के लिए कच्चे रखें।","सॉस को चखना भूल जाना। पकाने से पहले बैलेंस करें, क्योंकि नूडल्स डालने के बाद मीठा, खट्टा और नमकीन ठीक नहीं हो सकता।"],"faq":[["क्या फिश सॉस के बिना पैड थाई बना सकता हूँ?","हाँ, चुटकी भर नमक के साथ सोया सॉस, या शाकाहारी फिश सॉस इस्तेमाल करें। स्वाद अलग होगा, लेकिन मीठा और खट्टा बैलेंस रहता है।"],["अगर मेरे नूडल्स चिपक जाएँ तो क्या करूँ?","वे ज़्यादा देर भीगे, या वोक काफी गर्म नहीं था। अच्छी तरह छानें, थोड़े तेल के साथ मिलाएँ, और अगली बार ज़्यादा गर्म वोक में पकाएँ।"],["क्या सूखी श्रिम्प इस्तेमाल कर सकता हूँ?","हाँ। 2 tbsp सूखी श्रिम्प भिगोएँ और लहसुन के साथ डालें। वे पारंपरिक नमकीन गहराई डालती हैं।"],["क्या पैड थाई ग्लूटेन फ्री है?","चावल के नूडल्स कुदरती तौर पर ग्लूटेन फ्री होते हैं, लेकिन फिश सॉस और इमली के पेस्ट में एडिटिव्स हो सकते हैं, इसलिए लेबल चेक करें।"]]},"pekingduck":{"intro":"पेकिंग डक चीन की महान सेलिब्रेशन डिश में से एक है, अपनी कुरकुरी स्किन के लिए मशहूर जो टूट जाती है, और मांस जो नीचे जूसी रहता है। राज़ स्किन को सुखाना और भूनने से पहले ग्लेज़ करना है, ताकि चर्बी निकल जाए और स्किन गहरी लैकर वाली सुनहरी हो जाए। इस घर वाली वर्शन में स्किन को सुखाने के लिए फ्रिज में रात भर आराम, माल्टोज़ और सिरके की सादी ग्लेज़, और गर्म ओवन इस्तेमाल होता है, फिर काटने से पहले आराम। पारंपरिक तरीके से परोसें, पतली मैंडरिन पैनकेक में होइसिन सॉस, हरी प्याज़ और खीरे के साथ, और हर कोई अपनी खुद असेंबल करे। यह एक प्रोजेक्ट है, रोज़ का खाना नहीं, और हर मिनट के काबिल है।","ing":["पूरी डक 2 से 2.5kg","माल्टोज़ या शहद 3 tbsp","चावल का सिरका 2 tbsp","शाओशिंग वाइन 2 tbsp","फाइव स्पाइस 1 tsp","नमक 1 tbsp","ब्लांच करने के लिए उबलता पानी","मैंडरिन पैनकेक 12","होइसिन सॉस 120ml","हरी प्याज़ 4","खीरा 1","कैविटी के लिए अदरक","लहसुन (वैकल्पिक)"],"steps":["डक को साफ़ करें, बहुत अच्छी तरह सुखाएँ, और काँटे से स्किन पर हल्के छेद करें, मांस को छेदे बिना।","सिंक में डक पर उबलता पानी डालें, जिससे स्किन कस जाती है, फिर दोबारा सुखाएँ।","माल्टोज़, सिरका, शाओशिंग वाइन, फाइव स्पाइस और नमक को गर्म करें जब तक माल्टोज़ घुल न जाए, और पूरी डक पर ब्रश करें।","डक को बिना ढके फ्रिज में रात भर आराम दें, ट्रे पर रैक के ऊपर, ताकि स्किन पूरी तरह सूख जाए।","200C पर सीने की तरफ ऊपर 30 मिनट भूनें, फिर 180C कर दें और 60 से 75 मिनट और भूनें, जब तक स्किन गहरी सुनहरी और कुरकुरी न हो जाए।","आधे समय में बची हुई ग्लेज़ से एक बार ब्रश करें, और अगर पंख की नोकें जल्दी भूरी हो जाएँ तो फॉयल से ढक दें।","काटने से पहले 20 मिनट आराम दें, ताकि रस सेटल हो जाए और स्किन कुरकुरी रहे।","स्किन और मांस को पतली स्लाइस में काटें, पैनकेक गर्म करें, और होइसिन, हरी प्याज़ और खीरे के साथ परोसें।"],"tip":"स्किन को रात भर सुखाएँ। गीली स्किन ओवन में भाप में पकती है और कभी कुरकुरी नहीं होती, जबकि सूखी स्किन पिघलकर खूबसूरत लैकर बन जाती है।","notes":["माल्टोज़ क्लासिक चमक और हल्की मिठास देता है। शहद भी चलता है, लेकिन जल्दी भूरा होता है, इसलिए आखिरी 20 मिनट में डक पर नज़र रखें।","फाइव स्पाइस तेज़ होता है। नापकर डालें, और ज़्यादा न डालें, वरना डक पर हावी हो जाएगा।","डक की स्किन के नीचे बहुत चर्बी होती है। स्किन में छेद करने से वह निकल जाती है, और रैक पर भूनने से डक अपनी चर्बी से दूर रहता है।","मैंडरिन पैनकेक पतले और नरम होते हैं। परोसने से पहले 2 मिनट भाप दें, और ढककर रखें ताकि सूख न जाएँ।"],"variations":["दुकान की डक के साथ: चीनी डेली से रोस्ट डक लें, गर्म ओवन में स्किन को कुरकुरा करें, और उसी तरह पैनकेक और होइसिन के साथ परोसें।","डक ब्रेस्ट वर्शन: डक ब्रेस्ट पर निशान लगाएँ, स्किन की तरफ नीचे सेकें जब तक कुरकुरा न हो जाए, ओवन में पूरा करें, और पैनकेक के लिए पतला काटें।","प्लम सॉस के साथ: मीठी, फल जैसी फिनिश के लिए होइसिन की जगह प्लम सॉस इस्तेमाल करें।"],"serving":"6 लोगों के लिए है, साझा खाने के केंद्र के तौर पर, कटी हुई डक प्लैटर पर, गर्म पैनकेक, होइसिन, हरी प्याज़ और खीरा मेज़ के बीच में। हर व्यक्ति पैनकेक पर होइसिन लगाता है, डक और स्किन की कुछ स्लाइस, हरी प्याज़ और खीरा डालता है, और रोल कर लेता है। साथ हल्की सूप या स्टर फ्राइड सब्ज़ी परोसें, और जब तक डक रहे पैनकेक आते रहें।","storage":"बची हुई डक फ्रिज में एयरटाइट डिब्बे में 2 दिन तक रहती है। मांस को ढके हुए पैन में थोड़े पानी के साथ हल्की आँच पर गर्म करें, और स्किन को अलग से गर्म ग्रिल या गर्म ओवन में कुछ मिनट कुरकुरा करें। पैनकेक फ्रिज में 2 दिन तक रहते हैं और भाप से गर्म होते हैं। कटी हुई स्किन को फ्रीज़ न करें, वह कुरकुराहट खो देती है।","mistakes":["रात भर सुखाना छोड़ देना। स्किन नरम और चर्बी वाली रहती है, ओवन कितना भी गर्म हो।","बहुत कम तापमान पर भूनना। चर्बी नहीं निकलती, इसलिए स्किन कुरकुरी के बजाय चिकनी होती है।","जल्दी काटना। रस निकल जाता है और स्किन भाप में आ जाती है, इसलिए पूरे 20 मिनट आराम दें।","मोटे पैनकेक इस्तेमाल करना। वे डक पर हावी हो जाते हैं, इसलिए पतले मैंडरिन पैनकेक इस्तेमाल करें और अच्छी तरह गर्म करें।"],"faq":[["क्या छोटे ओवन में पेकिंग डक बना सकता हूँ?","हाँ, अगर डक के आस पास हवा हो। लगभग 2kg की छोटी डक आसान होती है, और तरीका वही है।"],["अगर माल्टोज़ न मिले तो क्या करूँ?","थोड़े गर्म पानी से पतला किया हुआ शहद इस्तेमाल करें। ग्लेज़ थोड़ी गहरी होगी, इसलिए भूनने के आखिर में नज़र रखें।"],["क्या सिर्फ डक की टाँगें इस्तेमाल कर सकता हूँ?","हाँ। उसी तरह सुखाएँ और ग्लेज़ करें, और कुरकुरा होने तक लगभग 50 से 60 मिनट भूनें। पूरी डक से आसान होती हैं।"],["मेरी डक की स्किन कुरकुरी क्यों नहीं हुई?","स्किन काफी सूखी नहीं थी, या ओवन काफी गर्म नहीं था। रात भर सुखाएँ, अच्छी तरह छेद करें, और गर्म भूनें।"]]},"dimsum":{"intro":"डिम सम का मतलब है दिल को छूने वाला खाना, और यह बाँटकर खाने के लिए होता है, छोटे बाँस के स्टीमर एक के बाद एक मेज़ पर आते हैं, हर एक में अलग बाइट। यह घर वाली वर्शन दो क्लासिक बनाती है, प्रॉन हर गाउ, पारदर्शी रैपर के साथ, और पोर्क और प्रॉन सिउ माई, खुले ऊपर के साथ, दोनों हल्के से पकने तक स्टीम किए हुए और गर्म परोसे हुए। रैपर को हल्का हाथ और थोड़ा धैर्य चाहिए, लेकिन फिलिंग सादी है, और स्टीमिंग तेज़ है। मदद से बनाएँ, एक फिलिंग भरे, एक फोल्ड करे, और तैयार डंपलिंग को ढककर रखें ताकि सूख न जाएँ। चाय के साथ परोसें, कैंटोनीज़ यम चा की तरह, और खाने को धीरे चलने दें।","ing":["प्रॉन 300g (बारीक कटे हुए)","पोर्क कीमा 200g","हर गाउ के लिए गेहूँ स्टार्च 120g","टैपिओका स्टार्च 60g","सिउ माई के लिए वॉन्टन रैपर 20","अदरक 1 tbsp (कद्दूकस)","हरी प्याज़ 2","सोया सॉस 2 tbsp","तिल का तेल 1 tsp","सफ़ेद मिर्च","चीनी 1 tsp","शाओशिंग वाइन 1 tbsp","परोसने के लिए चिली ऑयल","सोया सॉस","काला सिरका"],"steps":["प्रॉन, पोर्क, अदरक, हरी प्याज़, सोया, तिल का तेल, चीनी, वाइन और सफ़ेद मिर्च को मिलाकर फिलिंग बनाएँ, और 20 मिनट ठंडा करें।","हर गाउ रैपर के लिए गेहूँ स्टार्च और टैपिओका स्टार्च को 180ml उबलते हुए पानी के साथ मिलाएँ, नरम आटा गूँधें, और ढककर 15 मिनट आराम दें।","हर गाउ आटे को लॉग बनाएँ, छोटे टुकड़ों में काटें, और हर एक को क्लीवर या बेलन से पतला गोल दबाएँ।","हर रैपर में एक चम्मच फिलिंग रखें, क्रिसेंट में फोल्ड करें, और किनारे को मज़बूती से प्लीट करके बंद करें।","सिउ माई के लिए हर वॉन्टन रैपर के बीच में एक चम्मच फिलिंग रखें, किनारों को फिलिंग के गिर्द जमा करें, और हल्का दबाएँ ताकि ऊपर खुला रहे।","बाँस के स्टीमर को छेद वाले बेकिंग पेपर या बंद गोभी के पत्तों से लाइन करें, और डंपलिंग को जगह छोड़कर रखें।","हर गाउ को 6 से 7 मिनट और सिउ माई को 8 मिनट स्टीम करें, जब तक रैपर पारदर्शी या सेट न हो जाए और फिलिंग पक न जाए।","स्टीमर में ही तुरंत परोसें, चिली ऑयल, सोया सॉस और काले सिरके के साथ, और साथ गर्म चाय।"],"tip":"डंपलिंग में ज़्यादा फिलिंग न भरें। एक लेवल चम्मच फिलिंग साफ़ बंद होती है, जबकि ज़्यादा फिलिंग स्टीमर में रैपर को फाड़ देती है।","notes":["गेहूँ स्टार्च हर गाउ रैपर को पारदर्शी और नाज़ुक बनाता है। सादा आटा वही नतीजा नहीं देगा, इसलिए एशियाई दुकान से गेहूँ स्टार्च लें।","आटे को हर समय ढककर रखें। वह कुछ मिनट में सूख जाता है और फोल्ड करते हुए फट जाता है।","आकार देने से पहले फिलिंग को ठंडा करें। ठंडी फिलिंग हिस्सा करना आसान होती है और रैपर में आकार रखती है।","ज़रूरत पर हिस्सों में स्टीम करें। भरे हुए स्टीमर चिपक जाते हैं, और डंपलिंग उठाते हुए फट जाते हैं।"],"variations":["सब्ज़ी डिम सम: मांस की जगह बारीक कटी मशरूम, बंद गोभी, गाजर और टोफू इस्तेमाल करें, उसी तरह सीज़न करके।","चिकन डिम सम: प्रॉन के साथ चिकन कीमा इस्तेमाल करें, और कुरकुराहट के लिए वॉटर चेस्टनट डालें।","दुकान के रैपर के साथ: दोनों के लिए गोल डंपलिंग रैपर इस्तेमाल करें, प्लीट करके बंद करें, आसान वर्शन के लिए जो फिर भी बेहतरीन स्वाद देता है।"],"serving":"4 लोगों के लिए है, साझा खाने के हिस्से के तौर पर, हर व्यक्ति के लिए 5 से 6 डंपलिंग, और चाय, और साथ सादा खीरे की सलाद या स्टर फ्राइड सब्ज़ी। स्टीमर को ढक्कन के साथ सीधा मेज़ पर परोसें, ताकि डंपलिंग खाने के पल तक गर्म और भाप वाले रहें। डिम सम छोटे बाइट में स्लो खाना है, इसलिए चाय भरती रहें, स्टीमर हिस्सों में लाएँ, और जल्दी न करें।","storage":"कच्चे डंपलिंग ट्रे पर 1 महीने तक अच्छी तरह फ्रीज़ होते हैं, फिर बैग में। फ्रोज़न से 3 से 4 मिनट ज़्यादा स्टीम करें। पके हुए डंपलिंग फ्रिज में 1 दिन तक रहते हैं, और 3 मिनट स्टीम से दोबारा गर्म होते हैं, माइक्रोवेव में नहीं, जो रैपर को सख्त कर देता है। बची हुई फिलिंग फ्रिज में ढककर 1 दिन तक रहती है।","mistakes":["ज़्यादा मोटे रैपर इस्तेमाल करना। वे स्टीम के बाद आटे जैसी रहती है, इसलिए पतला बेलें या दबाएँ।","सूखे स्टीमर पर स्टीम करना। डंपलिंग चिपककर फट जाते हैं, इसलिए स्टीमर को लाइन करें और हल्का तेल लगाएँ।","ढक्कन बार बार खोलना। भाप निकल जाती है और डंपलिंग बराबर नहीं पकते, इसलिए समय पूरा होने तक ढक्कन बंद रखें।","डंपलिंग को बहुत पहले बना लेना। रैपर सूखकर फट जाते हैं, इसलिए स्टीम करने से पहले ही आकार दें, या गीले कपड़े से ढककर रखें।"],"faq":[["क्या बाँस के स्टीमर के बिना डिम सम बना सकता हूँ?","हाँ। मेटल स्टीमर, पॉट पर कोलंडर, या ढके हुए वोक में रैक पर प्लेट इस्तेमाल करें। अच्छी तरह लाइन करें ताकि कुछ चिपके नहीं।"],["मेरे हर गाउ रैपर क्यों फट रहे हैं?","आटा सूख गया, या ज़्यादा ठंडा हो गया। ढककर रखें, छोटे हिस्सों से काम करें, और सख्त हो तो हल्का गूँध लें।"],["क्या फ्रोज़न प्रॉन इस्तेमाल कर सकता हूँ?","हाँ। पूरी तरह पिघलाएँ, सुखाएँ, और मिलाने से पहले काटें। गीले प्रॉन से ढीली फिलिंग बनती है।"],["डिम सम के साथ कौनसी सॉस जाती है?","चिली ऑयल, हल्की सोया सॉस और काला सिरका, स्वाद के अनुसार मिलाएँ। सिरके में थोड़ा कद्दूकस अदरक पारंपरिक है।"]]},"coqauvin":{"intro":"कॉक ऑ वैन क्लासिक फ्रेंच सुकून वाला खाना है, चिकन जो लाल वाइन में हल्की आँच पर पकता है जब तक हड्डी से अलग न हो जाए, मशरूम, पर्ल प्याज़ और बेकन के साथ, ऐसी सॉस में जो वाइन का स्वाद देती है बिना अल्कोहलिक लगे। यह बरगंडी से है, जहाँ वाइन पकाने का हिस्सा है, सिर्फ साथ पीने के लिए नहीं, और लंबी हल्की ब्रेज़ ही चिकन को नरम और सॉस को रिच बनाती है। पहले चिकन को अच्छी तरह ब्राउन करें, क्योंकि वह रंग स्वाद बन जाता है, फिर पॉट को ओवन में काम करने दें। मैश्ड आलू या कुरकुरी रोटी के साथ परोसें, और सॉस को आखिर में नमक और थोड़े मक्खन के साथ चखें ताकि चमक आए।","ing":["चिकन थाई","लेग्स 1kg (हड्डी के साथ)","लाल वाइन 500ml (मुमकिन हो तो बरगंडी स्टाइल)","बेकन लार्डन 150g","मशरूम 250g","पर्ल प्याज़ 12","गाजर 1","लहसुन 3 कली","थाइम 3 टहनी","चिकन स्टॉक 250ml","टमाटर पेस्ट 1 tbsp","मैदा 2 tbsp","मक्खन 2 tbsp","परोसने के लिए पार्सले","नमक","मिर्च"],"steps":["चिकन को अच्छी तरह सीज़न करें, हल्का मैदा लगाएँ, और गर्म ओवनप्रूफ पॉट में हिस्सों में ब्राउन करें जब तक दोनों तरफ गहरी सुनहरी न हो जाए। अलग रखें।","उसी पॉट में बेकन को कुरकुरा होने तक तलें, निकाल लें, और बेकन की चर्बी में मशरूम और पर्ल प्याज़ को ब्राउन करें।","गाजर, लहसुन और टमाटर पेस्ट डालें, और 2 मिनट हिलाते हुए पकाएँ जब तक खुशबू न आए।","वाइन डालें, पॉट की तह को खुरचकर सारा ब्राउन स्वाद उठाएँ, और 3 मिनट सिमर करें।","चिकन और बेकन को वापस पॉट में डालें, स्टॉक और थाइम डालें, और हल्की सिमर पर ले आएँ। लिक्विड चिकन के आधे तक आना चाहिए।","ढककर 160C पर ओवन में 75 से 90 मिनट पकाएँ, जब तक चिकन बहुत नरम न हो जाए।","चिकन निकाल लें, और सॉस को स्टोव पर 10 मिनट सिमर करें जब तक चम्मच पर लगने लगे। आखिर में मक्खन फेंटें।","चिकन को सॉस में वापस डालें, गर्म करें, और पार्सले छिड़ककर परोसें।"],"tip":"ब्रेज़िंग से पहले चिकन को ठीक से ब्राउन करें। फीका चिकन फीकी सॉस बनाता है, जबकि गहरी सुनहरी चिकन रिच, पूरे स्वाद वाली सॉस बनाती है।","notes":["हड्डी वाला चिकन लंबी ब्रेज़ में जूसी रहता है। बिना हड्डी वाला चिकन जल्दी पकता है और सूख सकता है, इसलिए इस्तेमाल करें तो ओवन का समय कम करें।","वह वाइन इस्तेमाल करें जो आप पीते। सस्ती कुकिंग वाइन से सख्त सॉस बनती है, जबकि फल जैसी लाल वाइन गहराई और रंग देती है।","पर्ल प्याज़ छोटी और मीठी होती है। न मिले तो क्वार्टर में कटी हुई शैलट इस्तेमाल करें।","आखिर में फेंटा हुआ मक्खन सॉस को नरम चमक देता है और वाइन को गोल कर देता है। डालने के बाद सॉस को न उबालें।"],"variations":["सफ़ेद वाइन वर्शन: सूखी सफ़ेद वाइन इस्तेमाल करें और आखिर में क्रीम डालें, हल्की कॉक ऑ वैन ब्लांक के लिए।","आलू के साथ: आखिरी 40 मिनट के लिए पॉट में छोटे नए आलू डालें, ताकि वे सॉस में पक जाएँ।","स्लो कुकर वर्शन: पहले सब कुछ ब्राउन करें, फिर लो पर 5 से 6 घंटे पकाएँ, और आखिर में सॉस को स्टोव पर गाढ़ा करें।"],"serving":"4 लोगों के लिए है, उथले कटोरों में, क्रीमी मैश्ड आलू, मक्खन वाले नूडल्स या कुरकुरी रोटी के साथ ताकि सॉस पकड़ी जाए। चिकन को सॉस, मशरूम और प्याज़ की भरी करछी के साथ, और पार्सले छिड़ककर परोसना चाहिए। यह रविवार की डिश है, इसलिए पॉट से मेज़ पर परोसें, साथ सादा हरी सलाद और बाकी वाइन, अगर चाहें, गिलास में।","storage":"कॉक ऑ वैन फ्रिज में 3 दिन तक रहता है, और अगले दिन और बेहतर लगता है। स्टोव पर हल्की आँच पर उबलने तक गर्म करें, अगर सॉस ज़्यादा गाढ़ी हो तो थोड़ा स्टॉक डालें। 3 महीने तक अच्छी तरह फ्रीज़ होता है, फ्रिज में रात भर रखकर पिघलाएँ। चिकन को उस की सॉस में स्टोर करें, ताकि सूख न जाए।","mistakes":["ब्राउनिंग छोड़ देना। सॉस में रंग और गहराई नहीं होगी, इसलिए हिस्सों में ब्राउन करने का समय लें।","ब्रेज़ को तेज़ उबालना। चिकन सख्त हो जाता है और सॉस जल्दी कम हो जाती है, इसलिए हल्की सिमर और कम ओवन रखें।","ज़्यादा वाइन और स्टॉक नहीं इस्तेमाल करना। सॉस तेज़ हो जाती है, इसलिए वाइन को स्टॉक से बैलेंस करें और परोसने से पहले चखें।","मक्खन जल्दी डालना। लंबी सिमर में वह फट जाता है, इसलिए बिल्कुल आखिर में, उबाल से हटाकर फेंटें।"],"faq":[["क्या बिना अल्कोहल के कॉक ऑ वैन बना सकता हूँ?","हाँ, वाइन की जगह ज़्यादा स्टॉक और 2 tbsp लाल वाइन सिरका और थोड़ा अंगूर का रस इस्तेमाल करें। स्वाद अलग होगा, लेकिन ब्रेज़ फिर भी काम करेगी।"],["क्या चिकन ब्रेस्ट इस्तेमाल कर सकता हूँ?","कर सकते हैं, लेकिन सिर्फ आखिरी 30 मिनट के लिए डालें, वरना सूख जाएगी। थाई और लेग्स इस डिश के लिए बहुत बेहतर हैं।"],["कौनसी वाइन इस्तेमाल करूँ?","सूखी, फल जैसी लाल वाइन, मुमकिन हो तो बरगंडी से। बहुत टैनिक या ओकी वाइन से बचें, जो लंबी ब्रेज़ में कड़वी हो सकती है।"],["क्या पहले से बना सकता हूँ?","हाँ, और बेहतर होती है। पूरी पकाएँ, ठंडा करें, फ्रिज में रखें, और अगले दिन हल्की आँच पर गर्म करें।"]]},"bouillabaisse":{"intro":"बूयाबेस मार्सिले से है, जहाँ मछली पकड़ने वाले उन मछलियों से सूप बनाते थे जो बिक नहीं पाती थीं, और अब यह फ्रांस की सबसे पसंदीदा सेलिब्रेशन डिश में से एक है। ब्रॉथ स्टार है, मछली के स्टॉक, टमाटर, सौंफ, संतरे के छिलके, केसर और जैतून के तेल से बनती है, और मछली और शेलफिश इसमें सिर्फ कुछ मिनट पकते हैं, ताकि नरम रहें। अगर हो सके तो दो हिस्सों में परोसें, ब्रॉथ छानकर कटोरों में और मछली प्लैटर पर, रूइये के साथ, केसर और लहसुन वाली मेयोनेज़, टोस्ट की हुई रोटी पर। सुनने में ग्रैंड लगती है, लेकिन तरीका सादा है, अच्छी ब्रॉथ बनाएँ, मछली को सही तरतीब से डालें, और ज़्यादा न पकाएँ।","ing":["मिक्स सख्त सफ़ेद मछली 800g (टुकड़ों में कटी हुई)","प्रॉन 300g","मसल 300g (साफ़ की हुई)","मछली का स्टॉक 1.5 लीटर","टमाटर 400g (कटे हुए)","टमाटर पेस्ट 2 tbsp","सौंफ 1 बल्ब","प्याज़ 1","लीक 1","केसर 1 बड़ी चुटकी","संतरे का छिलका 1 स्ट्रिप","लहसुन 4 कली","जैतून का तेल 4 tbsp","थाइम","परोसने के लिए कुरकुरी रोटी","रूइये","पार्सले","नींबू"],"steps":["बड़े पॉट में जैतून का तेल गर्म करें, प्याज़, लीक, सौंफ और लहसुन को 8 मिनट तलें जब तक नरम और मीठी न हो जाएँ।","टमाटर पेस्ट और कटे हुए टमाटर डालें, और 5 मिनट पकाएँ जब तक टमाटर टूटने न लगें।","मछली का स्टॉक डालें, केसर, संतरे का छिलका, थाइम और चुटकी भर नमक डालें, और 20 मिनट सिमर करें।","ब्रॉथ को छलनी से छानें, सब्ज़ियों को दबाकर सारा स्वाद निकालें, फिर ब्रॉथ को वापस पॉट में डालें।","ब्रॉथ को दोबारा हल्की सिमर पर ले आएँ, और सबसे सख्त मछली पहले डालें, 3 मिनट पकाएँ।","बाकी मछली और प्रॉन डालें, और 3 से 4 मिनट और पकाएँ, जब तक पक न जाएँ।","मसल डालें, ढक दें, और 3 मिनट पकाएँ जब तक खुल न जाएँ। जो बंद रहें उन्हें फेंक दें।","गर्म कटोरों में ब्रॉथ और सीफूड डालें, और रूइये लगी टोस्ट की हुई रोटी, पार्सले और नींबू के साथ परोसें।"],"tip":"मछली को ज़्यादा न पकाएँ। सबसे सख्त हिस्से पहले और नाज़ुक हिस्से आखिर में डालें, और मछली के फ्लेक होते ही पॉट को आँच से उतार लें।","notes":["केसर महंगा है, लेकिन एक चुटकी ब्रॉथ को रंग और खुशबू से बदल देती है। डालने से पहले 10 मिनट गर्म स्टॉक के एक चम्मच में भिगोएँ।","मछली का मिक्स इस्तेमाल करें, जैसे मॉन्कफिश, सी बास और रेड मलेट अगर मिल जाएँ। सिर्फ एक मछली से सूप पतला होता है।","संतरे का छिलका रोशन, खुशबूदार नोट डालता है जो मार्सिले में क्लासिक है। बिना सफ़ेद गूदे के चौड़ी स्ट्रिप इस्तेमाल करें, और परोसने से पहले निकाल लें।","रूइये अंडे की ज़र्दी, लहसुन, केसर, नींबू और जैतून के तेल को फेंटकर मेयोनेज़ बनाने से बनती है। केसर वाली दुकान की अयोली अच्छा शॉर्टकट है।"],"variations":["क्लैम के साथ: साफ़ किए हुए क्लैम को मसल के साथ डालें, और जो न खुलें उन्हें फेंक दें।","आसान वीकनाइट वर्शन: सिर्फ प्रॉन और एक सख्त सफ़ेद मछली इस्तेमाल करें, वही ब्रॉथ के साथ, और रोटी के साथ परोसें।","आलू के साथ: ब्रॉथ में कटे हुए आलू डालें और मछली डालने से पहले नरम होने तक सिमर करें, भारी सूप के लिए।"],"serving":"6 लोगों के लिए है, गहरे गर्म कटोरों में, मछली और शेलफिश ऊपर सजाए हुए, और रूइये वाली टोस्ट की प्लेट मेज़ के बीच में। हर व्यक्ति रूइये को ब्रॉथ में डालता है या रोटी पर लगाता है, और मछली पर नींबू निचोड़ता है। हरी सलाद और एक गिलास सूखी सफ़ेद वाइन के साथ परोसें, और रोटी आती रहे, क्योंकि ब्रॉथ छोड़ने के काबिल नहीं।","storage":"बूयाबेस ताज़ी खाना बेहतर है, उसी दिन जिस दिन बनी हो। सिर्फ ब्रॉथ फ्रिज में 2 दिन तक रहती है और 1 महीने तक अच्छी तरह फ्रीज़ होती है। बची हुई मछली दोबारा गर्म करने पर अच्छी नहीं रहती और रबरी हो सकती है, इसलिए ब्रॉथ को अलग रखें और दोबारा गर्म करते हुए ताज़ी मछली डालें। ब्रॉथ को उबलने तक गर्म करें, फिर इसमें ताज़ी सीफूड पकाएँ।","mistakes":["सीफूड को ज़्यादा पकाना। मछली और प्रॉन एक मिनट में नरम से सख्त हो जाते हैं, इसलिए पॉट पर नज़र रखें।","छानने का स्टेप छोड़ देना। ब्रॉथ चंकी रहती है और स्वाद कम साफ़ होता है, इसलिए छानें और सब्ज़ियों को दबाएँ।","ऑयली मछली इस्तेमाल करना। सैल्मन और मैकेरल नाज़ुक ब्रॉथ पर हावी हो जाती हैं, इसलिए सख्त सफ़ेद मछली इस्तेमाल करें।","सारी मछली एक साथ डालना। नाज़ुक मछली टूट जाती है जब तक सख्त मछली पकती है, इसलिए स्टेज में डालें।"],"faq":[["क्या दुकान का मछली स्टॉक इस्तेमाल कर सकता हूँ?","हाँ। अच्छी क्वालिटी वाला स्टॉक लें, और लिखे हुए तरीके से सब्ज़ी और केसर के साथ सिमर करें। फिर भी रिच लगेगा।"],["रूइये क्या है?","प्रोवेंस की केसर और लहसुन वाली मेयोनेज़, टोस्ट पर लगाई और सूप में मिलाई जाती है। यह रिचनेस और रंग डालती है।"],["क्या शेलफिश के बिना बूयाबेस बना सकता हूँ?","हाँ, सिर्फ मछली इस्तेमाल करें, और थोड़ा ज़्यादा मछली स्टॉक डालें। सूप फिर भी बेहतरीन होती है, हालाँकि कम अलग।"],["क्या केसर ज़रूरी है?","यह क्लासिक रंग और खुशबू देता है। इसके बिना सूप फिर भी अच्छी होती है, लेकिन वह बिल्कुल बूयाबेस नहीं होती।"]]},"paella":{"intro":"पाएया स्पेन के वालेंसिया से है, जहाँ यह बाहर चौड़ी उथली पैन में पकाई जाती है, और चावल, सीफूड नहीं, असली स्टार हैं। केसर इसे सुनहरा रंग देता है, अच्छा स्टॉक स्वाद देता है, और पकाने के आखिरी कुछ मिनट, बिना हिलाए, सोकाराट बनाते हैं, नीचे चावल की कुरकुरी टोस्टेड परत जिसके लिए सब लड़ते हैं। अगर मिले तो छोटे दाने वाला बॉम्बा चावल इस्तेमाल करें, बराबर परत में फैलाएँ, और स्टॉक डालने के बाद हिलाने से बचें। पैन में ही, मेज़ के बीच में, नींबू के साथ परोसें, और हर कोई इकट्ठा खाए।","ing":["बॉम्बा या छोटे दाने वाला चावल 400g","प्रॉन 300g","मसल 300g (साफ़ की हुई)","स्क्विड रिंग 200g (वैकल्पिक)","चिकन या मछली का स्टॉक 1 लीटर (गर्म)","केसर 1 बड़ी चुटकी","प्याज़ 1","लाल मिर्च 1","लहसुन 3 कली","टमाटर 2 (कद्दूकस)","स्मोक्ड पाप्रिका 1 tsp","जैतून का तेल 4 tbsp","नींबू 1","मटर 100g"],"steps":["केसर को 3 tbsp गर्म स्टॉक में 10 मिनट भिगोएँ, और बाकी स्टॉक गर्म रखें।","चौड़ी पाएया पैन में जैतून का तेल गर्म करें, प्याज़ और मिर्च को 6 मिनट तलें जब तक नरम न हो जाएँ, फिर लहसुन और पाप्रिका डालें।","कद्दूकस टमाटर डालें और 4 मिनट पकाएँ जब तक गहरा और गाढ़ा न हो जाए।","चावल डालें और 1 मिनट मिलाएँ ताकि सोफ्रिटो में लिपट जाए, फिर बराबर परत में फैलाएँ।","गर्म स्टॉक और केसर वाला लिक्विड डालें, नमक से सीज़न करें, और हल्के उबाल पर ले आएँ। इस के बाद हिलाएँ नहीं।","मध्यम आँच पर 15 मिनट पकाएँ, फिर सीफूड और मटर को ऊपर सजाएँ, हल्का सा चावल में दबाते हुए।","आँच कम करें, फॉयल से हल्का ढक दें, और 10 मिनट और पकाएँ, जब तक चावल नरम न हो जाए और मसल खुल न जाएँ।","पैन को ढककर 5 मिनट आराम दें, फिर पैन में ही नींबू के साथ परोसें, सोकाराट की कुरकुराहट सुनते हुए।"],"tip":"स्टॉक डालने के बाद चावल को न हिलाएँ। हिलाने से स्टार्च निकलता है और चावल चिपचिपा हो जाता है, और सोकाराट नहीं बनता।","notes":["बॉम्बा चावल बहुत लिक्विड सोख लेता है और अलग रहता है। लंबे दाने वाला चावल पाएया में नरम हो जाता है, इसलिए बॉम्बा न मिले तो छोटे दाने वाला चावल इस्तेमाल करें।","स्टॉक गर्म रखें। ठंडा स्टॉक पैन को ठंडा कर देता है और चावल बराबर नहीं पकता।","स्मोक्ड पाप्रिका गर्म, धुएँदार नोट देती है। मीठी पाप्रिका चलती है, लेकिन तेज़ पाप्रिका केसर पर हावी हो सकती है।","केसर को इस्तेमाल करने से पहले भिगोना चाहिए, ताकि रंग और खुशबू चावल में बराबर फैले।"],"variations":["चिकन और चोरिज़ो पाएया: सोफ्रिटो के साथ ब्राउन की हुई चिकन और कटी हुई चोरिज़ो डालें, और चिकन स्टॉक इस्तेमाल करें।","सब्ज़ी पाएया: सब्ज़ी का स्टॉक, आर्टिचोक, हरी फलियाँ और बटर बीन्स इस्तेमाल करें, वही केसर चावल के तरीके से।","मिक्स्ड पाएया: चिकन, प्रॉन और मसल मिलाएँ, चिकन जल्दी और सीफूड देर से डालते हुए, असली तरीके के अनुसार।"],"serving":"6 लोगों के लिए है, पैन में ही मेज़ के बीच में परोसी जाती है, नींबू और हरी सलाद के साथ। हर व्यक्ति किनारे से अंदर की तरफ हिस्सा लेता है, ताकि हर किसी को कुरकुरी नीचे वाली परत मिले। पाएया बाँटकर खाने की डिश है, इसलिए ज़्यादा नींबू, कुरकुरी रोटी और अयोली रखें अगर चाहें, और किचन में अलग प्लेटों में परोसें नहीं।","storage":"पाएया ताज़ी खाना बेहतर है, सीधा पैन से। बचा हुआ खाना फ्रिज में 2 दिन तक रहता है, और गर्म पैन में थोड़े स्टॉक के साथ ढककर भाप आने तक दोबारा गर्म होता है। चावल उतना कुरकुरा नहीं होगा, और सीफूड को ज़्यादा देर दोबारा गर्म नहीं करना चाहिए। शेलफिश वाली पाएया को फ्रीज़ न करें, टेक्सचर खराब होता है। सोकाराट सिर्फ उसी दिन होता है।","mistakes":["चावल को हिलाना। वह चिपचिपा हो जाता है और नीचे कभी कुरकुरा नहीं होता।","गलत चावल इस्तेमाल करना। लंबे दाने वाला चावल और रिसोट्टो चावल दोनों गलत टेक्सचर देते हैं।","ठंडा स्टॉक डालना। पकाना रुक रुक कर होता है, और चावल बराबर नहीं पकता।","पैन को ज़्यादा भरना। ऊपर ज़्यादा सीफूड चावल को टोस्ट होने के बजाय भाप में पका देता है, इसलिए परत बराबर और ज़्यादा गहरी न रखें।"],"faq":[["क्या पाएया पैन ज़रूरी है?","चौड़ी उथली पैन चलती है, जब तक चावल की परत पतली हो। गहरा पॉट चावल को ज़्यादा मोटा कर देता है और वह टोस्ट होने के बजाय भाप में पकता है।"],["क्या केसर के बिना पाएया बना सकता हूँ?","बना सकते हैं, रंग के लिए चुटकी भर हल्दी के साथ, लेकिन स्वाद अलग होगा। केसर पाएया का असली स्वाद है।"],["कैसे मालूम करूँ कि चावल पक गया?","चखकर देखें। नरम होना चाहिए हल्की सी बाइट के साथ, और लिक्विड सोख लिया जाना चाहिए। 5 मिनट आराम से पूरा हो जाता है।"],["मेरी पाएया नरम क्यों है?","चावल हिलाया गया, स्टॉक ठंडा था, या आँच कम थी। चावल को बिना हिलाए रखें और आँच स्टेडी रखें।"]]},"beefpho":{"intro":"फ़ो वियतनाम की सबसे प्रसिद्ध सूप है, और इसका दिल साफ़ ब्रॉथ है जो जली हुई प्याज़ और अदरक, स्टार ऐनीज़, दालचीनी, लौंग और फिश सॉस का स्वाद देता है, बीफ़ की हड्डियों के साथ हल्की आँच पर सिमर होता है जब तक रिच लेकिन कभी गंदा न हो जाए। नूडल्स अलग पकते हैं, बीफ़ को कागज़ की तरह पतला काटा जाता है और गर्म ब्रॉथ डालने पर पक जाता है, और कटोरा मेज़ पर बीन स्प्राउट, थाई बेसिल, धनिया, नींबू और मिर्च के साथ पूरा होता है। इसमें समय लगता है, लेकिन काम ज़्यादातर इंतज़ार और झाग उतारना है, और नतीजा एक हल्का, खुशबूदार और गहरा सुकून देने वाला कटोरा है।","ing":["बीफ़ की हड्डियाँ 1.5kg","मैरो या नकल हड्डियाँ","बीफ़ ब्रिस्केट या शिन 500g","चावल नूडल्स 500g (चपटे)","प्याज़ 2","अदरक 1 बड़ा टुकड़ा","स्टार ऐनीज़ 3","दालचीनी 1 स्टिक","लौंग 4","धनिया बीज 1 tsp","सौंफ बीज 1 tsp","फिश सॉस 4 tbsp","रॉक शुगर 1 tbsp","परोसने के लिए बीन स्प्राउट","थाई बेसिल","धनिया","नींबू","मिर्च"],"steps":["हड्डियों को उबलते पानी में 5 मिनट ब्लांच करें, छानें, धोएँ, और साफ़ पॉट में ताज़े ठंडे पानी के साथ वापस डालें।","प्याज़ के आधे हिस्से और अदरक को खुली आँच या गर्म ग्रिल पर जलाएँ जब तक जगह जगह काले न हो जाएँ, फिर पॉट में डालें।","स्टार ऐनीज़, दालचीनी, लौंग, धनिया और सौंफ को सूखे पैन में 2 मिनट टोस्ट करें जब तक खुशबू न आए, मलमल में बाँधें या खुले डालें और बाद में छान लें।","ब्रॉथ को बहुत हल्की आँच पर 2.5 घंटे सिमर करें, अक्सर झाग उतारते हुए, और ब्रिस्केट को आखिरी 60 मिनट के लिए डालें जब तक नरम न हो जाए।","ब्रिस्केट निकाल लें, हल्का ठंडा करें, पतला काटें, और ब्रॉथ को बारीक छलनी से छानें जब तक साफ़ न हो जाए।","ब्रॉथ को फिश सॉस और रॉक शुगर से सीज़न करें, चखते हुए, जब तक नमकीन, खुशबूदार और हल्का मीठा न हो जाए।","चावल नूडल्स को अलग पकाएँ, छानें, और कटोरों में ब्रिस्केट की स्लाइस और कच्चे पतले कटे बीफ़ के साथ बाँट लें।","हर कटोरे पर उबलती ब्रॉथ डालें, ताकि कच्चा बीफ़ गर्मी में पक जाए, और हर्ब्स, स्प्राउट, नींबू और मिर्च के साथ परोसें।"],"tip":"सिमर को हल्का रखें और अक्सर झाग उतारें। तेज़ उबाल ब्रॉथ को गंदा और चिकना बना देता है, जबकि खामोश सिमर इसे साफ़ और साफ़ स्वाद वाला रखता है।","notes":["प्याज़ और अदरक को जलाना धुएँदार मिठास डालता है जो फ़ो के लिए ज़रूरी है। इसे छोड़ें नहीं, और प्याज़ को पूरी तरह न छीलें, छिलका रंग डालता है।","रॉक शुगर फिश सॉस को बैलेंस करता है बिना ब्रॉथ को मीठा बनाए। आम चीनी भी चलती है, लेकिन थोड़ी कम इस्तेमाल करें।","कच्चे बीफ़ को आधा फ्रोज़न होते हुए काटें। वह पतला और बराबर काटा जाता है, और गर्म ब्रॉथ में सेकंडों में पक जाता है।","चावल नूडल्स को भिगोना या नरम होने तक पकाना चाहिए, फिर अच्छी तरह छानना चाहिए, ताकि कटोरे में सारी ब्रॉथ न सोख लें।"],"variations":["चिकन फ़ो: पूरी चिकन और चिकन की हड्डियाँ इस्तेमाल करें, 60 से 75 मिनट सिमर करें, और मांस को कटोरों के लिए काट लें।","शाकाहारी फ़ो: वही मसालों, जली हुई प्याज़ और अदरक के साथ मशरूम और सब्ज़ी का स्टॉक इस्तेमाल करें, और ऊपर टोफू और मशरूम रखें।","ज़्यादा स्पाइसी फ़ो: ताज़ी कटी हुई मिर्च और चिली सॉस मेज़ पर डालें, ब्रॉथ में नहीं, ताकि हर व्यक्ति गर्मी को कंट्रोल करे।"],"serving":"6 लोगों के लिए है, गहरे कटोरों में, हर्ब्स, स्प्राउट, नींबू और मिर्च अलग कटोरों में मेज़ के बीच में। हर व्यक्ति अपनी हर्ब्स डालता है और नींबू निचोड़ता है, और चॉपस्टिक्स और चम्मच से खाता है, पहले नूडल्स, फिर ब्रॉथ। फ़ो भाप करते हुए परोसी जाती है और तुरंत खाई जाती है, जब हर्ब्स ताज़ी और बीफ़ अभी पका हो।","storage":"ब्रॉथ फ्रिज में 4 दिन तक रहती है और 3 महीने तक अच्छी तरह फ्रीज़ होती है। ब्रॉथ, नूडल्स और टॉपिंग को अलग रखें, और ताज़ा असेंबल करें। ब्रॉथ को उबलने तक गर्म करें, ताज़े नूडल्स पकाएँ, और परोसने से पहले बीफ़ काटें। बचा हुआ पका ब्रिस्केट फ्रिज में 2 दिन तक रहता है। भरे हुए कटोरे स्टोर न करें।","mistakes":["ब्रॉथ को तेज़ उबालना। वह गंदा हो जाती है और चर्बी सूप में मिल जाती है, इसलिए बारीक सिमर रखें।","झाग न उतारना। पॉट में रहने वाली झाग और चर्बी स्वाद और सफाई को हल्का कर देती है।","नूडल्स को ज़्यादा पकाना। वे ब्रॉथ सोख लेते हैं और नरम हो जाते हैं, इसलिए अलग पकाएँ और अच्छी तरह छानें।","सीज़निंग को चखना भूल जाना। फिश सॉस और चीनी को आखिर में बैलेंस करना ज़रूरी है, इसलिए थोड़ी थोड़ी मात्रा में सीज़न करें और अक्सर चखें।"],"faq":[["क्या प्रेशर कुकर में फ़ो बना सकता हूँ?","हाँ। हड्डियों को प्रेशर पर 60 से 75 मिनट पकाएँ, फिर छानें और सीज़न करें। स्वाद बहुत करीब होता है, हालाँकि ब्रॉथ थोड़ी कम साफ़ होती है।"],["कच्ची स्लाइस के लिए कौनसा बीफ़ बेहतर है?","सरलॉइन या आई ऑफ़ राउंड, आधा फ्रोज़न होते हुए बहुत पतला कटा हुआ। वह गर्म ब्रॉथ में सेकंडों में पक जाता है।"],["क्या फ़ो ग्लूटेन फ्री है?","चावल नूडल्स और ज़्यादातर फिश सॉस कुदरती तौर पर ग्लूटेन फ्री होते हैं, लेकिन अपनी फिश सॉस और होइसिन के लेबल चेक करें।"],["क्या ब्रॉथ पहले से बना सकता हूँ?","हाँ, और रात भर रखने से बेहतर होती है। फ्रिज में रखें, जमी हुई चर्बी हटा दें, और उबलने तक गर्म करें।"]]},"poutine":{"intro":"पूटीन कनाडा के क्यूबेक से है, और यह शानदार तौर पर सादा है, गर्म कुरकुरे फ्राइज़, ताज़े चीज़ कर्ड जो काटने पर चीकते हैं, और ऊपर डाली गई रिच ब्राउन ग्रेवी ताकि कर्ड हल्के से पिघलने लगें। फ्राइज़ इतने कुरकुरे होने चाहिए कि ग्रेवी को बिना एक मिनट में गीला हुए संभाल सकें, इसलिए दो बार तलना काबिल है, और ग्रेवी बहुत गर्म होनी चाहिए, क्योंकि गर्मी ही कर्ड को नरम करती है। तुरंत परोसें, कटोरे में, काँटे के साथ, और खाएँ जब फ्राइज़ किनारों पर कुरकुरे और ग्रेवी नीचे जमा हो रही हो।","ing":["आलू 1kg (फ्लाउरी किस्म)","चीज़ कर्ड 250g (कमरे के तापमान पर)","बीफ़ या सब्ज़ी का स्टॉक 500ml","मक्खन 2 tbsp","मैदा 2 tbsp","सोया सॉस 1 tsp","वूस्टरशायर सॉस 1 tsp","लहसुन 1 कली","काली मिर्च","डीप फ्राई के लिए तेल","नमक","परोसने के लिए हरी प्याज़ (वैकल्पिक)"],"steps":["आलू को मोटे बैटन में काटें, ठंडे पानी में 30 मिनट भिगोएँ, फिर छानें और बहुत अच्छी तरह सुखाएँ।","तेल को 160C तक गर्म करें, चिप्स को हिस्सों में 5 से 6 मिनट तलें जब तक हल्के और नरम न हो जाएँ, फिर छानकर 10 मिनट आराम दें।","चिप्स आराम करते हुए, पैन में मक्खन पिघलाएँ, मैदा मिलाएँ, और 2 मिनट पकाएँ जब तक हल्का सुनहरा न हो जाए।","गर्म स्टॉक को थोड़ा थोड़ा करके फेंटें, फिर सोया, वूस्टरशायर, लहसुन और मिर्च डालें, और 5 मिनट सिमर करें जब तक नरम और चमकदार न हो जाए।","तेल को 190C तक गर्म करें, और चिप्स को दोबारा हिस्सों में 2 से 3 मिनट तलें जब तक गहरे सुनहरे और बहुत कुरकुरे न हो जाएँ। छानकर तुरंत नमक डालें।","गर्म चिप्स को गर्म कटोरों में डालें, ऊपर चीज़ कर्ड बिखेरें, और कर्ड को कमरे के तापमान पर रखें ताकि वे पिघले बिना नरम हों।","ऊपर से बहुत गर्म ग्रेवी डालें, ताकि वह खाली जगह में जाए और कर्ड को पिघलाना शुरू करे।","काँटे के साथ तुरंत परोसें, अगर चाहें तो ऊपर हरी प्याज़ डालकर, और गर्म खाएँ।"],"tip":"चीज़ कर्ड को कमरे के तापमान पर इस्तेमाल करें। ठंडे कर्ड सख्त रहते हैं और नरम नहीं होते, जबकि कमरे के तापमान वाले कर्ड गर्म ग्रेवी के नीचे नरम और चीकने हो जाते हैं।","notes":["फ्लाउरी आलू सबसे फ्लफी चिप्स बनाते हैं। वैक्सी आलू घने रहते हैं और उसी तरह कुरकुरे नहीं होते।","चीज़ कर्ड ताज़े और चीकने होने चाहिए। अगर कर्ड न मिले तो ताज़ी मोज़रेला के टुकड़े इस्तेमाल करें, हालाँकि चीक नहीं होगी।","ग्रेवी इतनी पतली होनी चाहिए कि बह सके, स्टू जैसी गाढ़ी नहीं। ठंडी होते ही गाढ़ी हो जाती है, इसलिए बहुत गर्म परोसें।","दो बार तलना कुरकुरे चिप्स का राज़ है जो देर तक रहते हैं। पहली फ्राई अंदर पकाती है, दूसरी फ्राई बाहर कुरकुरा करती है।"],"variations":["पुल्ड पोर्क के साथ: ऊपर हल्की आँच पर पका पुल्ड पोर्क और ज़्यादा ग्रेवी डालें, भारी मेन कोर्स के लिए।","मशरूम के साथ: ग्रेवी में तली हुई मशरूम और थाइम डालें, और सब्ज़ी का स्टॉक इस्तेमाल करें, शाकाहारी वर्शन के लिए।","नाश्ता पूटीन: ऊपर एक फ्राइड अंडा डालें, और साथ बेकन परोसें।"],"serving":"4 लोगों के लिए है, स्नैक, साइड, या शेयरिंग मेन कोर्स के तौर पर, गहरे कटोरों में काँटों के साथ। ग्रेवी डालते ही परोसें, जब चिप्स कुरकुरे और कर्ड नरम हो रहे हों, और बैठा रहने न दें, क्योंकि चिप्स जल्दी नरम हो जाते हैं। पूटीन कैज़ुअल खाना है, इसलिए मेज़ के बीच में परोसें, और ज़्यादा ग्रेवी जग में रखें जो चाहे।","storage":"पूटीन ताज़ी खाना बेहतर है और मिलाने के बाद दोबारा गर्म करने पर अच्छी नहीं रहती, क्योंकि चिप्स नरम हो जाते हैं। हिस्सों को अलग रखें, चिप्स, कर्ड और ग्रेवी, फ्रिज में 2 दिन तक। चिप्स को गर्म ओवन में कुरकुरा होने तक दोबारा गर्म करें, ग्रेवी को उबलने तक गर्म करें, और ताज़ा असेंबल करें। सिर्फ ग्रेवी 1 महीने तक अच्छी तरह फ्रीज़ होती है।","mistakes":["ठंडे चीज़ कर्ड इस्तेमाल करना। वे सख्त रहते हैं और फ्राइज़ में नहीं पिघलते।","गुनगुनी ग्रेवी डालना। वह कर्ड को नरम नहीं करती, इसलिए ग्रेवी को भाप निकलने तक गर्म करें।","चिप्स को सिर्फ एक बार तलना। वे कुछ मिनट में ग्रेवी के नीचे नरम हो जाते हैं, इसलिए दो बार तलें।","दूसरी फ्राई से पहले चिप्स पर नमक डालना। नमक पानी निकालता है और कुरकुरा होने से रोकता है, इसलिए सिर्फ आखिर में नमक डालें।"],"faq":[["चीज़ कर्ड क्या हैं?","दूध के जमने के ताज़े टुकड़े, हल्के से दबाए हुए, काटने पर चीकने वाली टेक्सचर के साथ। वे पूटीन का असली इंग्रेडिएंट हैं।"],["क्या फ्रोज़न चिप्स इस्तेमाल कर सकता हूँ?","हाँ। ओवन या एयर फ्रायर में बहुत कुरकुरा होने तक पकाएँ, फिर गर्म ग्रेवी और कर्ड के साथ असेंबल करें। ताज़े चिप्स को दो बार तलना बेहतर है, लेकिन फ्रोज़न चिप्स भी चलते हैं।"],["क्या पूटीन शाकाहारी है?","सब्ज़ी के स्टॉक और शाकाहारी वूस्टरशायर सॉस के साथ हो सकती है। पारंपरिक ग्रेवी में बीफ़ स्टॉक होता है, इसलिए अपना स्टॉक चेक करें।"],["क्या ग्रेवी पहले से बना सकता हूँ?","हाँ। 3 दिन पहले तक बनाकर फ्रिज में रखें, और चिप्स पर डालने से पहले उबलने तक गर्म करें।"]]},"bobotie":{"intro":"बोबोटी दक्षिण अफ्रीका की पसंदीदा बेक्ड कीमा डिश है, केप मलय पकाने की जड़ें रखती है, जहाँ मसालेदार कीमे को फल से मीठा किया जाता है, भिगोई हुई रोटी से रिच बनाया जाता है, और तेज़ पत्तों के साथ सुनहरी अंडे की कस्टर्ड टॉपिंग के नीचे बेक किया जाता है। स्वाद गर्म और हल्का मीठा होता है, करी पाउडर, हल्दी, चटनी, किशमिश और खुबानी सब मिलकर काम करते हैं, और टेक्सचर नरम और सुकून देने वाला होता है। पीले चावल, चटनी और सादा सलाद के साथ परोसें, और मीठा और नमकीन बैलेंस को बोलने दें। भीड़ के लिए पहले से बनाने की बेहतरीन डिश है, क्योंकि दोबारा गर्म करने पर खूबसूरत रहती है और अगले दिन और बेहतर लगती है।","ing":["बीफ़ या लैम्ब कीमा 750g","प्याज़ 1","लहसुन 2 कली","अदरक 1 tsp","करी पाउडर 2 tbsp","हल्दी 1 tsp","सफ़ेद रोटी 2 स्लाइस","दूध 250ml","अंडे 3","तेज़ पत्ते 4","चटनी 3 tbsp","किशमिश 3 tbsp","सूखी खुबानी 4 (कटी हुई)","नींबू का रस 1 tbsp","बादाम 2 tbsp (फ्लेक्ड)","नमक","मिर्च"],"steps":["रोटी को 125ml दूध में भिगोएँ जब तक नरम न हो जाए, फिर ज़्यादा दूध निकालकर रोटी को चूरा कर लें।","प्याज़, लहसुन और अदरक को तेल में 5 मिनट तलें जब तक नरम न हो जाएँ, फिर करी पाउडर और हल्दी डालकर 1 मिनट तलें।","कीमा डालें और टूटते हुए तलें, जब तक हर तरफ भूरा न हो जाए और लिक्विड पक न जाए।","भिगोई हुई रोटी, चटनी, किशमिश, खुबानी, नींबू का रस और सीज़निंग मिलाएँ, और 5 मिनट पकाएँ। चखें और मीठा खट्टा बैलेंस ठीक करें।","कीमे को मक्खन लगी बेकिंग डिश में डालें, बराबर दबाएँ, और तेज़ पत्ते ऊपर लगा दें।","बाकी दूध को 2 अंडों और चुटकी भर नमक के साथ फेंटें, और कीमे पर हल्के से डालें।","180C पर 35 से 40 मिनट बेक करें, जब तक टॉपिंग सेट और सुनहरी न हो जाए, और किनारे बुलबुले न बनाने लगें।","10 मिनट आराम दें, फ्लेक्ड बादाम छिड़कें, और पीले चावल और ज़्यादा चटनी के साथ परोसें।"],"tip":"बेक करने से पहले कीमे को चखें। मीठा, खट्टा और स्पाइसी बैलेंस इस स्टेज पर ठीक होना चाहिए, क्योंकि बेक करने से ठीक नहीं होगा।","notes":["भिगोई हुई रोटी कीमे को नरम और हल्का रखती है। इसके बिना बोबोटी घनी और सूखी हो सकती है।","करी पाउडर बहुत अलग होता है। अगर मिले तो हल्का केप मलय स्टाइल करी पाउडर इस्तेमाल करें, और चखने के बाद ही ज़्यादा डालें।","चटनी मिठास और खट्टापन डालती है। फल वाली चटनी पारंपरिक है, और आम की चटनी भी अच्छी चलती है।","तेज़ पत्ते ऊपर लगते हैं, मिलाए नहीं जाते, ताकि वे कस्टर्ड को स्वाद दें और परोसते हुए खूबसूरत लगें।"],"variations":["मसूर के साथ: आधा कीमा पकी हुई भूरी मसूर से बदलें, हल्के वर्शन के लिए वही मसालों के साथ।","शाकाहारी बोबोटी: वही फल, चटनी और अंडे की टॉपिंग के साथ मसूर और मशरूम इस्तेमाल करें।","ज़्यादा स्पाइसी वर्शन: प्याज़ के साथ 1 कटी हुई ताज़ी मिर्च डालें, और साथ ज़्यादा चटनी और सांबल परोसें।"],"serving":"6 लोगों के लिए है, पीले चावल, फल वाली चटनी और कुरकुरी हरी सलाद या कटे हुए टमाटर और प्याज़ की सलाद के साथ। बेकिंग डिश से सीधा, बड़े स्क्वायर में परोसें, सुनहरी टॉपिंग और हर हिस्से पर एक तेज़ पत्ता के साथ। बोबोटी फैमिली डिश है, इसलिए डिश को मेज़ के बीच में रखें, चावल और चटनी के साथ, और हर कोई खुद ले।","storage":"बोबोटी फ्रिज में ढककर 3 दिन तक रहती है, और 160C पर ओवन में गर्म होने तक अच्छी तरह दोबारा गर्म होती है। 3 महीने तक अच्छी तरह फ्रीज़ होती है, फ्रिज में रात भर रखकर पिघलाएँ। अंडे की टॉपिंग दोबारा गर्म करने पर थोड़ा पानी छोड़ सकती है, इसलिए हल्की आँच पर और फॉयल से ढककर गर्म करें। पीला चावल अलग से 2 दिन तक रहता है।","mistakes":["बिना रोटी के बहुत लीन कीमा इस्तेमाल करना। वह सूखा और टूटने वाला हो जाता है, इसलिए भिगोई हुई रोटी रखें।","टॉपिंग को ज़्यादा बेक करना। वह रबरी हो जाती है, इसलिए सेट और सुनहरी होते ही निकाल लें।","आराम छोड़ देना। बोबोटी गर्म काटने पर टूट जाती है, इसलिए परोसने से पहले 10 मिनट आराम दें।","ज़्यादा मीठा बना देना। कीमे को चखें, और चटनी और फल को नींबू के रस से बैलेंस करें, ज़्यादा चीनी से नहीं।"],"faq":[["क्या बोबोटी पहले से बना सकता हूँ?","हाँ। पूरी असेंबल करके 1 दिन तक फ्रिज में रखें, और ज़रूरत पर बेक करें, बेक के समय में 10 मिनट और डालकर।"],["क्या बोबोटी स्पाइसी है?","यह गर्म मसालेदार है, तेज़ नहीं। करी पाउडर स्वाद देता है, और फल और चटनी इसे हल्का रखते हैं।"],["पीला चावल क्या है?","हल्दी, किशमिश और कभी कभी दालचीनी के साथ पका चावल, दक्षिण अफ्रीका में बोबोटी के साथ परोसा होता है। सादा चावल भी चलता है।"],["क्या लैम्ब कीमा इस्तेमाल कर सकता हूँ?","हाँ। लैम्ब से ज़्यादा रिच बोबोटी बनती है। ब्राउन करने के बाद ज़्यादा चर्बी निकाल लें, ताकि बेक चिकना न हो।"]]},"moussaka":{"intro":"मूसाका ग्रीस की महान लेयर्ड बेक है, नरम बैंगन, दालचीनी की खुशबू वाला रिच टमाटर और लैम्ब या बीफ़ कीमा सॉस, और मोटी बेचमेल की टॉपिंग जो ओवन में सुनहरी हो जाती है। इसमें थोड़ा समय लगता है, क्योंकि हर परत असेंबल करने से पहले अलग पकाई जाती है, लेकिन यही इसकी स्ट्रक्चर और स्वाद देता है, और पहले से बनाकर आराम देना बेहतर है, ताकि परतें सेट हो जाएँ और साफ़ स्लाइस हों। गर्म परोसें, स्क्वायर में, सादी सलाद के साथ, और आराम के समय में जल्दी न करें। यह रविवार की डिश है, जेनरस और सुकून देने वाली, और मेज़ को खुशी से खिलाती है।","ing":["बैंगन 2 बड़े (कटे हुए)","आलू 3 (कटे हुए, वैकल्पिक)","लैम्ब या बीफ़ कीमा 600g","प्याज़ 1","लहसुन 3 कली","टमाटर 400g (कटे हुए)","टमाटर पेस्ट 2 tbsp","दालचीनी 1 tsp","ओरेगैनो 1 tsp","जायफल","दूध 500ml","मक्खन 50g","मैदा 50g","अंडे 2","चीज़ 80g (कद्दूकस)","केफालोटिरी या पार्मेसन"],"steps":["बैंगन की स्लाइस पर नमक डालें और 30 मिनट आराम दें, फिर सुखाएँ और सुनहरा और नरम होने तक तलें या भूनें। अलग रखें।","आलू की स्लाइस को हल्का नरम होने तक उबालें या भूनें, अगर इस्तेमाल कर रहे हों, और अलग रखें।","प्याज़ और लहसुन को नरम होने तक तलें, कीमा डालें, और अच्छी तरह ब्राउन करें, टूटते हुए।","टमाटर पेस्ट, कटे हुए टमाटर, दालचीनी, ओरेगैनो और सीज़निंग डालें, और 20 मिनट सिमर करें जब तक गाढ़ा न हो जाए।","मक्खन पिघलाकर, मैदा मिलाकर, और गर्म दूध फेंटकर बेचमेल बनाएँ जब तक गाढ़ा और नरम न हो जाए। हल्का ठंडा करें, फिर अंडे और आधी चीज़ फेंटें।","मक्खन लगी बेकिंग डिश में आलू, फिर बैंगन, फिर कीमा सॉस की परत लगाएँ, एक बार दोहराएँ, और बेचमेल से पूरा करें।","बाकी चीज़ और थोड़ा जायफल छिड़कें, और 180C पर 40 से 45 मिनट बेक करें जब तक सुनहरा और बुलबुले वाला न हो जाए।","काटने से पहले 20 मिनट आराम दें, ताकि परतें सेट हो जाएँ, और सलाद के साथ गर्म परोसें।"],"tip":"काटने से पहले मूसाका को आराम दें। ओवन से गर्म निकालकर वह टूट जाती है, आराम करने पर साफ़, खूबसूरत परतों में कटती है।","notes":["बैंगन पर नमक डालने से कड़वा पानी निकल जाता है और वह ज़्यादा तेल नहीं सोखता। तलने से पहले सुखाएँ।","दालचीनी ग्रीक कीमा सॉस का असली मसाला है। हल्का इस्तेमाल करें, ताकि सॉस को गर्म करे बिना मीठा लगे।","बेचमेल इतनी गाढ़ी होनी चाहिए कि ऊपर बैठ सके। अगर पतली हो तो कीमे में डूब जाती है, इसलिए चम्मच पर लगने तक पकाएँ।","चीज़ को बारीक कद्दूकस करें ताकि बेचमेल में बराबर पिघले और ऊपर अच्छी तरह भूरा हो।"],"variations":["शाकाहारी मूसाका: कीमे की जगह मसूर और मशरूम इस्तेमाल करें, वही मसाले और बेचमेल रखते हुए।","कॉर्जेट के साथ: बैंगन के साथ भुनी हुई कॉर्जेट की परत डालें, ज़्यादा सब्ज़ी के लिए।","हल्का वर्शन: बैंगन को तलने के बजाय भूनें, और बेचमेल के लिए सेमी स्किम्ड दूध इस्तेमाल करें।"],"serving":"6 लोगों के लिए है, बड़े स्क्वायर में, टमाटर, खीरा, प्याज़ और जैतून की सादी ग्रीक सलाद, और साथ कुरकुरी रोटी के साथ। गर्म परोसें, बहुत गर्म नहीं, ताकि स्वाद सेटल हो जाएँ और परतें कायम रहें। मूसाका बाँटकर खाने की डिश है, इसलिए बेकिंग डिश को मेज़ पर लाएँ, और ज़्यादा सलाद और रोटी के साथ परोसें जो चाहे।","storage":"मूसाका फ्रिज में ढककर 3 दिन तक रहती है, और 160C पर ओवन में गर्म होने तक अच्छी तरह दोबारा गर्म होती है। हिस्सों में 3 महीने तक अच्छी तरह फ्रीज़ होती है, फ्रिज में रात भर रखकर पिघलाएँ। फॉयल से ढककर दोबारा गर्म करें ताकि ऊपर ज़्यादा भूरा न हो। पूरी डिश को माइक्रोवेव न करें, बेचमेल फट सकती है।","mistakes":["बैंगन पर नमक डालना छोड़ देना। वह कड़वा रहता है और तेल सोख लेता है, जिससे बेक चिकना हो जाता है।","पतली बेचमेल बनाना। वह डूब जाती है और ऊपर कभी सुनहरा सेट नहीं होता।","जल्दी काटना। परतें फिसल जाती हैं, इसलिए कम से कम 20 मिनट आराम दें।","कीमा सॉस को कम पकाना। पानी वाली सॉस बेक को गीला बना देती है, इसलिए गाढ़ा होने तक सिमर करें।"],"faq":[["क्या मूसाका पहले से बना सकता हूँ?","हाँ, और पहले से बनाना बेहतर है। असेंबल करके 1 दिन तक फ्रिज में रखें, और ज़रूरत पर बेक करें, 10 मिनट और डालकर।"],["क्या लैम्ब की जगह बीफ़ इस्तेमाल कर सकता हूँ?","हाँ। बीफ़ से हल्की मूसाका बनती है। लैम्ब पारंपरिक और ज़्यादा रिच है, इसलिए अपनी पसंद चुनें।"],["क्या मूसाका ग्लूटेन फ्री है?","लिखे हुए तरीके से नहीं, क्योंकि बेचमेल में मैदा है। बेचमेल के लिए ग्लूटेन फ्री मैदा ब्लेंड इस्तेमाल करें, और अपना स्टॉक चेक करें।"],["मेरी बेचमेल दानेदार क्यों है?","दूध जल्दी डाला गया, या मैदा नहीं पका। लगातार फेंटें, गर्म दूध धीरे डालें, और नरम होने तक पकाएँ।"]]},"hummus":{"intro":"अच्छा हम्मस टेक्सचर के बारे में है, सिल्की, हल्का और व्हिप्ड, कभी दानेदार या भारी नहीं। यह लेवेंट से है, जहाँ चने, ताहिनी, नींबू और लहसुन को बर्फ वाले पानी के साथ ब्लेंड किया जाता है जब तक डिप हल्की और फ्लफी न हो जाए, फिर जैतून का तेल, पाप्रिका और पूरे चने के साथ पूरा किया जाता है। राज़ है ताहिनी को पहले, अकेले ब्लेंड करना, जब तक पूरी तरह नरम न हो जाए, और सबसे नरम नतीजे के लिए गर्म चने, या छिलके उतारे हुए चने इस्तेमाल करना। मेज़्ज़े स्प्रेड के हिस्से के तौर पर परोसें, गर्म पिट्टा, जैतून और सलाद के साथ, और हर कोई स्कूप करके बाँट ले।","ing":["चने 400g (पके हुए, छाने हुए)","ताहिनी 120g (अच्छी तरह हिलाई हुई)","नींबू का रस 3 tbsp","लहसुन 1 छोटी कली","बर्फ वाला पानी 4 से 6 tbsp","जैतून का तेल 2 tbsp (और परोसने के लिए ज़्यादा)","नमक 1 tsp","जीरा 1/2 tsp (वैकल्पिक)","परोसने के लिए पाप्रिका","पार्सले","परोसने के लिए गर्म पिट्टा रोटी"],"steps":["अगर टिन वाले चने इस्तेमाल कर रहे हों तो उन्हें अपने लिक्विड में 5 मिनट गर्म करें, छानें, और थोड़ा लिक्विड बचा लें। समय हो तो ढीले छिलके उतार लें।","ताहिनी, नींबू का रस, लहसुन और नमक को 2 मिनट ब्लेंड करें जब तक बहुत नरम, हल्की और हल्की फ्लफी न हो जाए।","गर्म चने डालें और 3 से 4 मिनट ब्लेंड करें, किनारों को खुरचते हुए, जब तक पूरी तरह नरम न हो जाए।","बर्फ वाला पानी एक चम्मच करके डालें, हर बार ब्लेंड करते हुए, जब तक हम्मस हल्का, व्हिप्ड और स्कूप करने के काबिल नरम न हो जाए।","चखें और नींबू, नमक और लहसुन को ठीक करें। वह रोशन और नमकीन होना चाहिए, ताहिनी के स्वाद के साथ, तेज़ नहीं।","उथले कटोरे में डालें, ऊपर चम्मच के पीछे से घुमाएँ, और जैतून का तेल डालें।","ऊपर कुछ पूरे चने, चुटकी भर पाप्रिका और कटी हुई पार्सले डालें।","कमरे के तापमान पर गर्म पिट्टा, सब्ज़ी की स्टिक्स और जैतून के साथ परोसें।"],"tip":"ताहिनी को पहले ब्लेंड करें, चने से पहले। अकेले ब्लेंड की हुई ताहिनी हल्की और क्रीमी हो जाती है, और यही हम्मस को सिल्की बनाता है।","notes":["ताहिनी की क्वालिटी सबसे ज़्यादा अहम है। छिलके उतारे हुए तिल से बनी बहने वाली, अच्छी तरह हिलाई हुई ताहिनी इस्तेमाल करें। मोटी, सूखी ताहिनी से भारी हम्मस बनती है।","बर्फ वाला पानी हम्मस में हवा फेंटता है और तेल डाले बिना ढीला करता है। धीरे डालें, वरना हम्मस बहने लगती है।","लहसुन छोटा और ताज़ा होना चाहिए। एक बड़ा कच्चा कली पूरे कटोरे पर हावी हो सकता है, इसलिए कम से शुरू करें।","गर्म चने ठंडे चनों से ज़्यादा नरम ब्लेंड होते हैं, क्योंकि उन का स्टार्च नरम होता है। ठंडे चने इस्तेमाल करें तो पहले गर्म करें।"],"variations":["भुनी लाल मिर्च हम्मस: 1 भुनी लाल मिर्च ब्लेंड करें, और नींबू थोड़ा कम करें।","चुकंदर हम्मस: रंग और मिठास के लिए 1 छोटा पका हुआ चुकंदर ब्लेंड करें, खूबसूरत गुलाबी वर्शन।","स्पाइसी हम्मस: ताहिनी के साथ 1 tsp हरीसा या चिली पेस्ट डालें, और ऊपर चिली ऑयल डालें।"],"serving":"6 लोगों के लिए है, मेज़्ज़े स्प्रेड के हिस्से के तौर पर, गर्म पिट्टा, जैतून, अचार, सलाद और दूसरी डिप के साथ। हम्मस को चौड़ी उथली कटोरे में परोसें, घुमाव में जैतून का तेल जमा हुआ, और हर कोई पिट्टा फाड़कर स्कूप करे। सैंडविच स्प्रेड, भुनी सब्ज़ी की बेस, या ग्रिल्ड मांस और फलाफेल के साथ साइड के तौर पर भी बेहतरीन है।","storage":"हम्मस फ्रिज में एयरटाइट डिब्बे में 4 दिन तक रहती है, ऊपर जैतून के तेल की पतली परत के साथ। परोसने से पहले कमरे के तापमान पर ले आएँ, और अच्छी तरह हिलाएँ। 3 महीने तक अच्छी तरह फ्रीज़ होती है, फ्रिज में रात भर रखकर पिघलाएँ, फिर दोबारा नरम फेंटें। 2 घंटे से ज़्यादा कमरे के तापमान पर न छोड़ें।","mistakes":["सब कुछ एक साथ ब्लेंड करना। ताहिनी कभी नरम नहीं होती, इसलिए पहले अकेले ब्लेंड करें।","ठंडे, सूखे चने इस्तेमाल करना। वे दानेदार ब्लेंड होते हैं, इसलिए गर्म करें और बर्फ वाला पानी धीरे डालें।","ज़्यादा लहसुन डालना। कच्चा लहसुन हम्मस के बैठने पर तेज़ हो जाता है, इसलिए कम इस्तेमाल करें और चखें।","सीधा फ्रिज से परोसना। ठंडी हम्मस सख्त और फीकी होती है, इसलिए पहले गर्म होने दें।"],"faq":[["क्या सूखे चने इस्तेमाल कर सकता हूँ?","हाँ। रात भर भिगोएँ, चुटकी भर बाइकार्बोनेट ऑफ़ सोडा के साथ बहुत नरम होने तक पकाएँ, और गर्म इस्तेमाल करें। वे सबसे नरम हम्मस देते हैं।"],["मेरी हम्मस दानेदार क्यों है?","ताहिनी पहले ब्लेंड नहीं हुई, चने ठंडे थे, या छिलके रह गए। ज़्यादा देर ब्लेंड करें और बर्फ वाला पानी डालें।"],["क्या ताहिनी के बिना हम्मस बना सकता हूँ?","बना सकते हैं, ज़्यादा जैतून का तेल और थोड़े तिल के तेल के साथ, लेकिन वह क्लासिक हम्मस जैसा स्वाद नहीं देगा। ताहिनी डिश का दिल है।"],["क्या हम्मस सेहतमंद है?","यह चने, ताहिनी, नींबू और जैतून के तेल से बनती है, यहाँ कोई नंबर नहीं दिए गए। तेल और नमक वे हिस्से हैं जिन पर नज़र रखें, इसलिए सब्ज़ी और पिट्टा के साथ परोसें।"]]},"falafel":{"intro":"असली फलाफेल कच्चे भिगोए हुए चनों से बनती है, कभी टिन वाले या पके हुए चनों से नहीं, और यही इसे हल्का, फ्लफी अंदर और कुरकुरी, खुरदरी क्रस्ट देती है। चनों को प्याज़, लहसुन, पार्सले, धनिया और जीरे के साथ मोटा पीसा जाता है, आराम दिया जाता है ताकि मिश्रण कायम रहे, फिर आकार दिया जाता है और गहरा सुनहरा होने तक तला जाता है। गर्म पिट्टा में सलाद और ताहिनी सॉस के साथ परोसें, या मेज़्ज़े स्प्रेड के हिस्से के तौर पर हम्मस के साथ। मिश्रण पहले से बनाकर ठंडा किया जा सकता है, और फलाफेल कुछ मिनट में तल जाती है, इसलिए भीड़ के लिए बेहतरीन है, जब तक पैन को भरें नहीं।","ing":["सूखे चने 250g (रात भर भिगोए हुए)","प्याज़ 1","लहसुन 3 कली","पार्सले 1 बड़ा गुच्छा","धनिया 1 गुच्छा","जीरा 2 tsp","धनिया पाउडर 1 tsp","बेकिंग पाउडर 1/2 tsp","मैदा 2 tbsp","नमक 1 tsp","काली मिर्च","चिली फ्लेक्स","तलने के लिए तेल","परोसने के लिए पिट्टा","सलाद","ताहिनी सॉस"],"steps":["चनों को बहुत से ठंडे पानी में रात भर भिगोएँ, फिर बहुत अच्छी तरह छानें। पकाएँ नहीं।","चने, प्याज़, लहसुन, हर्ब्स, मसाले, नमक और मिर्च को फूड प्रोसेसर में डालें, और मोटा और क्रम्बली होने तक पल्स करें, पेस्ट नहीं।","कटोरे में डालें, मैदा और बेकिंग पाउडर मिलाएँ, ढककर फ्रिज में 30 मिनट रखें ताकि सख्त हो जाए।","पहले एक फलाफेल टेस्ट करें, छोटी बॉल बनाएँ, तलें, और चेक करें कि कायम रहती है और अंदर तक पकती है।","बाकी को गीले हाथों से छोटी बॉल या पैटीज़ में आकार दें, अखरोट के साइज़ की।","तेल को 175C तक गर्म करें, और हिस्सों में 3 से 4 मिनट तलें, एक बार पलटकर, जब तक गहरा सुनहरा और कुरकुरा न हो जाए।","वायर रैक पर छानें, कागज़ पर नहीं, ताकि क्रस्ट कुरकुरी रहे, और थोड़ा नमक छिड़कें।","पिट्टा में सलाद, टमाटर, खीरा और ताहिनी सॉस के साथ गर्म परोसें, या हम्मस के साथ मेज़्ज़े प्लेट पर।"],"tip":"कच्चे भिगोए हुए चने इस्तेमाल करें, कभी पके हुए चने नहीं। पके हुए चनों से नरम, मशी फलाफेल बनती है जो तेल में टूट जाती है।","notes":["रात भर भिगोना ज़रूरी है। कम भीगे हुए चने अंदर सख्त रहते हैं, इसलिए ठंडे पानी में पूरे 12 घंटे दें।","पल्स करें, प्यूरी नहीं। हर्ब के नज़र आने वाले टुकड़ों के साथ मोटी टेक्सचर फलाफेल को हल्का, फ्लफी बाइट देती है।","मिश्रण को ठंडा करना आकार कायम रखने में मदद करता है। अगर गीला लगे तो एक चम्मच मैदा डालें, लेकिन ज़्यादा न डालें वरना फलाफेल भारी हो जाती है।","तेल का तापमान अहम है। बहुत ठंडा हो तो फलाफेल तेल सोख लेती है, बहुत गर्म हो तो बाहर भूरी हो जाती है अंदर कच्ची रहते हुए।"],"variations":["बेक्ड फलाफेल: तेल ब्रश करके 200C पर 20 से 25 मिनट बेक करें, एक बार पलटकर, हल्के वर्शन के लिए।","ब्रॉड बीन्स के साथ: आधे चने को भिगोई हुई स्प्लिट ब्रॉड बीन्स से बदलें, इजिप्शियन स्टाइल तामिया के लिए।","स्पाइसी फलाफेल: मिश्रण में 1 कटी हुई ताज़ी मिर्च और ज़्यादा जीरा डालें, और चिली सॉस के साथ परोसें।"],"serving":"4 लोगों के लिए है, हर व्यक्ति के लिए 4 से 5 फलाफेल, गर्म पिट्टा में सलाद और ताहिनी के साथ, या मेज़्ज़े स्प्रेड के हिस्से के तौर पर। तेल से निकलते ही परोसें, जब क्रस्ट कुरकुरी और अंदर गर्म और फ्लफी हो, नींबू और ज़्यादा ताहिनी के साथ। फलाफेल हाथ से खाने वाला खाना है, इसलिए खूब पिट्टा, सलाद और सॉस रखें, और हर कोई अपनी खुद बनाए।","storage":"कच्चा फलाफेल मिश्रण फ्रिज में ढककर 2 दिन तक रहता है। पकी हुई फलाफेल फ्रिज में 2 दिन तक रहती है, और गर्म ओवन में कुरकुरा होने तक दोबारा गर्म होती है, लगभग 8 मिनट। माइक्रोवेव न करें, वह नरम हो जाती है। कच्ची आकार दी हुई फलाफेल 1 महीने तक अच्छी तरह फ्रीज़ होती है, फ्रोज़न से एक मिनट ज़्यादा तलें।","mistakes":["टिन वाले चने इस्तेमाल करना। वे पहले से पके हुए होते हैं, इसलिए फलाफेल मशी होकर टूट जाती है।","मिश्रण को ज़्यादा प्रोसेस करना। नरम पेस्ट से घनी, भारी फलाफेल बनती है, इसलिए हल्का पल्स करें और मोटा रखें।","बहुत ठंडे तेल में तलना। फलाफेल तेल सोख लेती है और चिकनी हो जाती है, इसलिए पहले तेल को ठीक से गर्म करें।","बहुत बड़ा आकार देना। बड़ी फलाफेल अंदर कच्ची रहती है, इसलिए अखरोट के साइज़ की रखें।"],"faq":[["क्या फलाफेल को तलने के बजाय बेक कर सकता हूँ?","हाँ। वह कम कुरकुरी होती है, लेकिन फिर भी मज़ेदार होती है। तेल ब्रश करें, 200C पर बेक करें, और आधे समय में एक बार पलटें।"],["मेरी फलाफेल क्यों टूट गई?","मिश्रण ज़्यादा गीला था, या तेल ज़्यादा ठंडा था। मिश्रण को ठंडा करें, थोड़ा मैदा डालें, और पहले एक टेस्ट करें।"],["क्या मैदा डालकर टिन वाले चने इस्तेमाल कर सकता हूँ?","रिकमेंड नहीं किया जाता। मैदे के साथ भी पके हुए चनों से घनी फलाफेल बनती है। भिगोए हुए कच्चे चने ज़रूरी हैं।"],["फलाफेल के साथ कौनसी सॉस जाती है?","नींबू और पानी से पतली की हुई ताहिनी सॉस, और पिट्टा में सलाद। चिली सॉस और अचार भी पारंपरिक हैं।"]]},"feijoada":{"intro":"फ़ेजोआडा ब्राज़ील की राष्ट्रीय डिश है, एक रिच काले बीन्स का स्टू, पोर्क, सॉसेज और स्मोक्ड मांस के मिक्स के साथ, हल्की आँच पर पकाया जाता है जब तक बीन्स क्रीमी और मांस नरम न हो जाए। पारंपरिक तौर पर शनिवार को परोसी जाती है, लंबे फैमिली लंच के तौर पर, सफ़ेद चावल, सॉटे की हुई कोलार्ड ग्रीन्स, फ़रोफ़ा, टोस्टेड कसावा आटा, और संतरे की स्लाइस के साथ ताकि रिचनेस कम हो। इसमें समय लगता है, और यह भीड़ को खिलाती है, इसलिए बड़ा पॉट पकाएँ, साथ वाली चीज़ें सादी रखें, और खाने को लंबा चलने दें। बीन्स को रात भर भिगोएँ, मांस को अच्छी तरह ब्राउन करें, और पॉट को लंबी, हल्की सिमर दें, और नतीजा गहरा सुकून देने वाला होता है।","ing":["सूखे काले बीन्स 500g (रात भर भिगोए हुए)","पोर्क शोल्डर 500g (क्यूब में कटा हुआ)","स्मोक्ड सॉसेज 300g (स्लाइस में कटी हुई)","बेकन या सॉल्ट पोर्क 200g (डाइस में कटा हुआ)","प्याज़ 1","लहसुन 4 कली","तेज़ पत्ते 3","जीरा 1 tsp","ओरेगैनो 1 tsp","संतरा 1 (परोसने के लिए)","चावल","कोलार्ड ग्रीन्स (फ़रोफ़ा या टोस्टेड ब्रेडक्रम्ब परोसने के लिए, वैकल्पिक)"],"steps":["बीन्स को रात भर ठंडे पानी में भिगोएँ, छानें, और धोएँ।","पोर्क, सॉसेज और बेकन को बड़े पॉट में हिस्सों में ब्राउन करें, फिर अलग रखें, चर्बी पॉट में रखते हुए।","उसी पॉट में प्याज़ और लहसुन को नरम होने तक तलें, फिर जीरा और ओरेगैनो डालें।","मांस को वापस पॉट में डालें, बीन्स, तेज़ पत्ते और 3cm ढकने के लिए काफी पानी डालें।","उबाल ले आएँ, झाग उतारें, फिर बहुत हल्की सिमर पर, आधा ढककर, 2 से 2.5 घंटे पकाएँ।","कभी कभी हिलाएँ, ज़रूरत पर गर्म पानी डालते हुए, जब तक बीन्स क्रीमी और मांस नरम न हो जाए।","चखें और नमक और मिर्च से सीज़न करें। मांस नमक डालता है, इसलिए ज़्यादा डालने से पहले चखें।","गहरे कटोरों में सफ़ेद चावल, सॉटे की हुई कोलार्ड ग्रीन्स, फ़रोफ़ा और संतरे की स्लाइस के साथ परोसें।"],"tip":"बीन्स को रात भर भिगोएँ और हल्की आँच पर सिमर करें। जल्दी वाले बीन्स सख्त रहते हैं, और तेज़ उबाल उन्हें क्रीमी बीन्स के बजाय मश में तोड़ देता है।","notes":["काले बीन्स ज़रूरी हैं। वे क्रीमी और गहरे हो जाते हैं, और पूरे स्टू को रंग देते हैं। किडनी बीन्स से अलग डिश बनती है।","मांस का मिक्स फ़ेजोआडा को गहराई देता है। जो मिले इस्तेमाल करें, लेकिन क्लासिक स्वाद के लिए कुछ स्मोक्ड ज़रूर रखें।","तेज़ पत्ते परोसने से पहले निकाल लें। वे स्टू को स्वाद देते हैं, लेकिन खाने में अच्छे नहीं लगते।","संतरे की स्लाइस सजावट नहीं हैं। उन का खट्टापन पोर्क और बीन्स की रिचनेस को काटता है, इसलिए खूब परोसें।"],"variations":["चिकन के साथ: आधा पोर्क चिकन थाई से बदलें, आखिरी 45 मिनट के लिए डालते हुए, हल्के वर्शन के लिए।","शाकाहारी फ़ेजोआडा: सब्ज़ी के स्टॉक के साथ मशरूम, स्मोक्ड टोफू और ज़्यादा बीन्स इस्तेमाल करें, वही सीज़निंग रखते हुए।","प्रेशर कुकर वर्शन: भिगोए हुए बीन्स और मांस को प्रेशर पर 35 मिनट पकाएँ, फिर गाढ़ा करने के लिए 15 मिनट बिना ढके सिमर करें।"],"serving":"8 लोगों के लिए है, लंबे फैमिली लंच के तौर पर, सफ़ेद चावल, लहसुन के साथ सॉटे की हुई कोलार्ड ग्रीन्स, फ़रोफ़ा और संतरे की स्लाइस मेज़ के बीच में। हर व्यक्ति चावल पर बीन्स और मांस परोसता है, ग्रीन्स और फ़रोफ़ा डालता है, और मुँह ताज़ा करने के लिए बाइट के बीच संतरा खाता है। ठंडे ड्रिंक के साथ परोसें और पॉट को स्टोव पर रखें, क्योंकि दूसरी बार लेना एक्सपेक्टेड है।","storage":"फ़ेजोआडा फ्रिज में 4 दिन तक रहती है, और रात भर रखने से स्वाद बेहतर हो जाता है। हल्की आँच पर उबलने तक गर्म करें, अगर गाढ़ी हो गई हो तो थोड़ा पानी डालें। हिस्सों में 3 महीने तक बहुत अच्छी तरह फ्रीज़ होती है, फ्रिज में रात भर रखकर पिघलाएँ। चावल, ग्रीन्स और फ़रोफ़ा ताज़े बनाएँ, या अलग से 2 दिन तक रखें।","mistakes":["रात भर भिगोना छोड़ देना। बीन्स को ज़्यादा समय लगता है और बराबर नहीं पकते।","तेज़ उबालना। बीन्स टूट जाते हैं और स्टू मशी हो जाता है, इसलिए हल्की सिमर रखें।","नमक जल्दी डालना। नमक बीन्स को सख्त कर सकता है, इसलिए चखने के बाद आखिर में अच्छी तरह सीज़न करें।","साथ वाली चीज़ों के बिना परोसना। चावल, ग्रीन्स, फ़रोफ़ा और संतरा डिश का हिस्सा हैं, एक्स्ट्रा नहीं।"],"faq":[["क्या टिन वाले काले बीन्स इस्तेमाल कर सकता हूँ?","हाँ, मुश्किल में। ब्राउन किए हुए मांस के साथ आखिरी 30 मिनट के लिए डालें, और पानी कम करें, लेकिन स्टू कम रिच होगा।"],["क्या फ़ेजोआडा बहुत फैटी है?","यह रिच स्टू है, पोर्क और सॉसेज से बना। हल्के वर्शन के लिए लीन कट इस्तेमाल करें और ब्राउन करने के बाद ज़्यादा चर्बी निकाल लें।"],["फ़रोफ़ा क्या है?","टोस्टेड कसावा आटा, अक्सर प्याज़ और बेकन के साथ, बीन्स और चावल पर छिड़का जाता है। टोस्टेड ब्रेडक्रम्ब अच्छा विकल्प है।"],["क्या फ़ेजोआडा पहले से बना सकता हूँ?","हाँ, और अगले दिन बेहतर होती है। पूरी पकाएँ, ठंडा करें, फ्रिज में रखें, और हल्की आँच पर गर्म करें।"]]},"meatpie":{"intro":"ऑसी मीट पाई एक आइकन है, हाथ में पकड़ा जाने वाला, सुनहरा और ऑस्ट्रेलिया भर में फुटबॉल गेम, बेकरी और किचन टेबल पर खाया जाने वाला। कुरकुरी शॉर्टक्रस्ट बेस और फ्लेकी पफ पेस्ट्री लिड के अंदर रिच बीफ़ फिलिंग होती है, प्याज़, टमाटर, वूस्टरशायर सॉस और थोड़ी वेजीमाइट के साथ हल्की आँच पर पकाई हुई, इतनी गाढ़ी कि पाई काटने पर आकार कायम रहे, लेकिन इतनी जूसी कि ऊपर टमाटर सॉस चाहिए। फिलिंग को पहले बनाकर पूरी तरह ठंडा करें, क्योंकि गर्म फिलिंग पेस्ट्री को पिघला देती है, फिर लिड के गहरा सुनहरा होने तक बेक करें। गर्म परोसें, टमाटर सॉस के साथ, और हाथों से खाएँ, ऑस्ट्रेलियाई तरीके से।","ing":["बीफ़ चक 700g (छोटे डाइस में कटा हुआ)","प्याज़ 1","लहसुन 2 कली","टमाटर पेस्ट 2 tbsp","बीफ़ स्टॉक 400ml","वूस्टरशायर सॉस 2 tbsp","वेजीमाइट 1 tsp","मैदा 2 tbsp","थाइम 1 tsp","बेस के लिए शॉर्टक्रस्ट पेस्ट्री","लिड के लिए पफ पेस्ट्री","अंडा 1 (फेंटा हुआ, ग्लेज़ के लिए)","परोसने के लिए टमाटर सॉस","नमक","मिर्च"],"steps":["बीफ़ को गर्म पॉट में हिस्सों में ब्राउन करें, फिर अलग रखें। उसी पॉट में प्याज़ और लहसुन को ब्राउन करें।","टमाटर पेस्ट और मैदा डालें, 1 मिनट पकाएँ, फिर स्टॉक डालकर हिलाएँ ताकि ब्राउन स्वाद उठ जाए।","बीफ़ को वापस डालें, वूस्टरशायर, वेजीमाइट और थाइम डालें, और 60 से 75 मिनट हल्की आँच पर सिमर करें जब तक नरम और गाढ़ा न हो जाए।","फिलिंग को पूरी तरह ठंडा करें, मुमकिन हो तो फ्रिज में। गर्म फिलिंग पेस्ट्री को पिघला देगी और गीला बना देगी।","ग्रीस की हुई पाई टिन या मफिन टिन को शॉर्टक्रस्ट पेस्ट्री से लाइन करें, ठंडी बीफ़ फिलिंग से भरें, और किनारों पर अंडा ब्रश करें।","ऊपर पफ पेस्ट्री लिड लगाएँ, किनारों को दबाकर बंद करें, काट लें, और हर लिड में छोटा स्टीम होल काटें।","फेंटे हुए अंडे से ब्रश करें, और 200C पर 25 से 30 मिनट बेक करें, जब तक गहरा सुनहरा और कुरकुरा न हो जाए।","5 मिनट आराम दें, टिन से निकाल लें, और टमाटर सॉस के साथ गर्म परोसें।"],"tip":"पेस्ट्री भरने से पहले फिलिंग को पूरी तरह ठंडा करें। हल्की सी गर्म फिलिंग भी पेस्ट्री को नरम कर देती है और ओवन में कुरकुरा होने से रोकती है।","notes":["बीफ़ चक हल्की आँच पर पकाने से नरम और रिच हो जाता है। लीन स्टूइंग बीफ़ सूख जाता है, और कीमे से अलग, नरम पाई बनती है।","वेजीमाइट नमकीन, यीस्टी गहराई डालती है जो पहचान में मुश्किल लेकिन बिला शुबा ऑस्ट्रेलियाई है। सिर्फ थोड़ी इस्तेमाल करें, वरना फिलिंग पर हावी हो जाएगी।","बेस के लिए शॉर्टक्रस्ट स्ट्रक्चर देती है, लिड के लिए पफ पेस्ट्री फ्लेक देती है। दोनों के लिए पफ पेस्ट्री इस्तेमाल करने से बेस गीला हो जाता है।","अंडे की वॉश सुनहरी चमक देती है। बेक करने से पहले ब्रश करें, और स्टीम होल में जमा न होने दें।"],"variations":["मशरूम के साथ: प्याज़ के साथ कटी हुई मशरूम डालें, ज़्यादा स्वाद और हल्की फिलिंग के लिए।","चिकन पाई: वही सॉस के साथ चिकन थाई इस्तेमाल करें, 40 मिनट पकाएँ, चिकन वर्शन के लिए।","चीज़ और बेकन पाई: बेक करने से पहले ठंडी फिलिंग में कद्दूकस चीज़ और पका हुआ बेकन डालें।"],"serving":"6 लोगों के लिए है, अलग पाई के तौर पर, ओवन से गर्म, ऊपर टमाटर सॉस और साथ सादा सलाद या मटर के साथ। मीट पाई हाथ से खाने वाला खाना है, इसलिए प्लेटों पर काँटे के साथ परोसें, लेकिन गर्म होते हुए हाथों से खाने की हौसला अफज़ाई करें। लंच, पिकनिक और स्पोर्ट देखने के लिए बेहतरीन हैं, मेज़ पर ज़्यादा टमाटर सॉस के साथ।","storage":"पकी हुई पाई फ्रिज में ढककर 3 दिन तक रहती है, और 180C पर ओवन में गर्म और कुरकुरा होने तक दोबारा गर्म होती है, लगभग 15 मिनट। 3 महीने तक अच्छी तरह फ्रीज़ होती है, पकी हुई या कच्ची, फ्रिज में रात भर रखकर पिघलाएँ। सिर्फ फिलिंग फ्रिज में 3 दिन और फ्रीज़र में 3 महीने तक रहती है। कुरकुरी क्रस्ट चाहिए तो पाई को माइक्रोवेव न करें।","mistakes":["पेस्ट्री को गर्म रहते हुए भरना। पेस्ट्री पिघल जाती है और गीली हो जाती है, इसलिए फिलिंग को पूरी तरह ठंडा करें।","बेस को कम बेक करना। नीचे फीका और नरम रहता है, इसलिए लिड के गहरा सुनहरा होने और बेस के सेट होने तक बेक करें।","स्टीम होल भूल जाना। भाप जमा होकर लिड को फाड़ देता है, इसलिए हर पाई में छोटा होल काटें।","फिलिंग को ज़्यादा पतला बनाना। काटने पर बह जाती है, इसलिए चम्मच पर माउंड बनने तक सिमर करें।"],"faq":[["क्या दुकान की पेस्ट्री इस्तेमाल कर सकता हूँ?","हाँ। अच्छी क्वालिटी वाली शॉर्टक्रस्ट और पफ पेस्ट्री अच्छी चलती हैं, और बहुत समय बचाती हैं। इस्तेमाल करने तक ठंडा रखें।"],["क्या एक बड़ी पाई बना सकता हूँ?","हाँ। 20cm पाई डिश इस्तेमाल करें, शॉर्टक्रस्ट से लाइन करें, भरें, पफ पेस्ट्री से ढक दें, और 40 से 45 मिनट बेक करें।"],["वेजीमाइट किस लिए है?","यह फिलिंग में नमकीन, यीस्टी गहराई डालती है। न मिले तो थोड़ी ज़्यादा वूस्टरशायर सॉस और चुटकी भर नमक इस्तेमाल करें।"],["क्या मीट पाई फ्रीज़ कर सकता हूँ?","हाँ, पकी हुई या कच्ची, 3 महीने तक। फ्रोज़न से बेक करें, 10 से 15 मिनट और डालकर, जब तक गर्म न हो जाए।"]]},"haleem":{"intro":"हलीम असल में सब्र का खाना है, एक ऐसा व्यंजन जो घंटों की पकाई का इनाम गाढ़ी, रेशमी दलिए और मशहूर रेशेदार बनावट के रूप में देता है, जिसे रेस्ता कहते हैं। गेहूं, जौ और चार दालें रात भर भिगोई जाती हैं, फिर पूरी तरह नरम होने तक पकाई जाती हैं, जबकि गोश्त अलग से तब तक पकता है जब तक वह बारीक रेशों में न बिखर जाए। फिर दोनों को पारंपरिक घोटा में मिलाकर मथा जाता है, जब तक दाने और गोश्त एक न हो जाएं। हलीम की जड़ें अरबी व्यंजन हरीस में हैं, जो मुगल काल में हैदराबाद आया और सदियों में पाकिस्तान भर में पसंद किया जाने वाला समृद्ध व्यंजन बन गया। यह रमज़ान की रातों, मुहर्रम की महफ़िलों और बड़े पारिवारिक सप्ताहांतों का खाना है, जिसे तली हुई प्याज़, अदरक, हरी मिर्च, नींबू और चाट मसाले के साथ गरम परोसा जाता है।","ing":["गेहूं (गंदुम) 1 कप (रात भर भिगोए हुए)","जौ ½ कप (रात भर भिगोए हुए)","चना दाल ½ कप","मसूर दाल ¼ कप","मूंग दाल ¼ कप","माश दाल ¼ कप","गोश्त 1 kg","गोश्त की हड्डियां 250 g","घी या तेल 1 कप","प्याज़ 2 बड़ी (पतली कटी हुई)","अदरक पेस्ट 2 tbsp","लहसुन पेस्ट 2 tbsp","दही 1 कप (फेंटा हुआ)","लाल मिर्च पाउडर 2 tbsp","कश्मीरी मिर्च पाउडर 1 tbsp","धनिया पाउडर 1½ tbsp","हल्दी पाउडर 1 tsp","हलीम मसाला 2 tbsp","नमक 2 tbsp","जीरा 1 tbsp","काली मिर्च 1 tsp","लौंग 6 से 8","हरी इलायची 5","काली इलायची 2","दालचीनी 2","जावंत्री 2","जायफल ¼ टुकड़ा","चक्र फूल 1","घी ½ कप","प्याज़ 1 मध्यम (पतली कटी हुई, तड़के के लिए)","अदरक 2 tbsp (बारीक कटी हुई)","हरा धनिया ½ कप (कटा हुआ)","पुदीना ½ कप (कटा हुआ)","हरी मिर्च 4","नींबू 3 (गार्निश के लिए)","चाट मसाला (छिड़कने के लिए)"],"steps":["गेहूं, जौ और सारी दालें साफ पानी से तब तक धोएं जब तक पानी साफ न निकले, फिर खूब पानी डालकर रात भर भिगो दें, या कम से कम 8 घंटे। मसूर, मूंग और माश दाल कम से कम 2 घंटे भिगोएं।","भिगोए हुए दाने और दालें छानकर एक बड़े भारी बर्तन में 12 कप पानी, 1 tsp हल्दी और 1 tsp नमक के साथ डालें, और ढककर हल्की आंच पर 2 से 2.5 घंटे तक पकाएं, जब तक सब कुछ पूरी तरह नरम और लिजलिजा न हो जाए।","जीरा, काली मिर्च, लौंग, हरी और काली इलायची, दालचीनी, जावंत्री, जायफल और चक्र फूल को सूखी कड़ाही में 1 मिनट भूनें, ठंडा करके बारीक पाउडर बना लें।","एक बड़े भारी बर्तन में 1 कप घी या तेल गरम करें, कटी हुई प्याज़ को गहरा सुनहरा भूरा होने तक तलें, और आधी प्याज़ गार्निश के लिए निकाल लें। अदरक और लहसुन का पेस्ट डालकर 1 मिनट भूनें।","गोश्त और हड्डियां डालकर तेज़ आंच पर 5 से 7 मिनट सेंकें, फिर लाल मिर्च पाउडर, कश्मीरी मिर्च पाउडर, धनिया पाउडर, हल्दी, हलीम मसाला, नमक और आधा पिसा हुआ मसाला डालकर 2 मिनट चलाएं। फेंटा हुआ दही डालकर तब तक पकाएं जब तक तेल अलग न हो जाए, फिर 6 कप पानी डालें।","ढककर तब तक पकाएं जब तक गोश्त पूरी तरह नरम होकर बिखर न जाए, प्रेशर कुकर में 45 मिनट या सामान्य बर्तन में 2.5 घंटे। गोश्त निकालें, खाली हड्डियां फेंक दें, और गोश्त को हाथ से मूसल या दो कांटों से बारीक रेशों में फाड़ लें। कोरमा की ग्रेवी बचा लें।","पके हुए दानों और दालों को हैंड ब्लेंडर से हल्का सा पीसें, थोड़ी बनावट रहने दें, और बचे हुए गोश्त को बची हुई ग्रेवी के साथ डालें। हल्की आंच पर 30 से 45 मिनट तक ज़ोर से मथते हुए और चलाते हुए पकाएं, बचा हुआ मसाला डालते हुए, जब तक मिश्रण गाढ़ा, चिपचिपा और रेशेदार न हो जाए।","एक छोटी कड़ाही में ½ कप घी गरम करें, कटी हुई प्याज़ को कुरकुरा और सुनहरा तलें, और गरम घी और प्याज़ को हलीम पर डालें। 5 मिनट ढकें, फिर गरम कटोरों में तली हुई प्याज़, अदरक, धनिया, पुदीना, हरी मिर्च, नींबू की फांकें और चाट मसाले के साथ परोसें, और साथ में गरम नान दें।"],"tip":"गेहूं और जौ को कम से कम 12 घंटे भिगोएं, और गोश्त को हाथ से मथें। फूड प्रोसेसर गोश्त के रेशों को छोटा काट देता है और रेस्ता की बनावट बिगाड़ देता है। भारी तले वाला बर्तन इस्तेमाल करें और बार-बार चलाएं, क्योंकि गाढ़ी हलीम नीचे लगकर जल जाती है।","notes":["गेहूं और जौ को लंबे समय तक भिगोना ज़रूरी है, कम से कम 8 घंटे और बेहतर है रात भर, वरना वे कुरकुरे रह जाते हैं और टूटने में बहुत ज़्यादा समय लेते हैं।","टांग या कंधे का गोश्त, बड़े टुकड़ों में, लंबे रेशे देता है जो रेस्ता की बनावट बनाते हैं। हड्डियां बर्तन में भरपूरता और समृद्धि देती हैं।","हलीम मसाला हर ब्रांड में तेज़ या हल्का होता है। पहली बार दी हुई मात्रा इस्तेमाल करें, और अगली बार ठीक करें।","घी से पारंपरिक स्वाद आता है। तेल भी चल जाता है, और आधा घी आधा तेल एक अच्छा बीच का रास्ता है।"],"variations":["चिकन हलीम: गोश्त की जगह उतने ही वज़न का हड्डी वाला चिकन लें, जो बहुत जल्दी पकता है और हल्का स्वाद देता है।","मटन हलीम: समृद्ध स्वाद के लिए बकरी का गोश्त या भेड़ का कंधा इस्तेमाल करें, जो शाही मुगलई रसोई में पारंपरिक है।","शाकाहारी ओट्स हलीम: गोश्त छोड़ दें, दालें दोगुनी कर दें, रोल्ड ओट्स डालें, और स्वादिष्ट गहराई के लिए सब्ज़ी के शोरबे और ज़्यादा तली हुई प्याज़ का इस्तेमाल करें।"],"serving":"गरम, चौड़े, उथले कटोरों में परोसें, और गार्निश एक थाली में मेज़ पर रखें ताकि हर कोई अपनी पसंद के अनुसार तली हुई प्याज़, अदरक, धनिया, पुदीना, हरी मिर्च, नींबू और चाट मसाला डाल सके। हलीम पारंपरिक रूप से गरम तंदूरी नान के साथ परोसी जाती है, या चम्मच से अकेले भी खाई जाती है। बर्तन को मेज़ पर तब लाएं जब वह अभी उबल रहा हो।","storage":"ठंडा करके एयरटाइट डिब्बे में फ्रिज में 3 दिन तक रखें। ठंडा होने पर हलीम गाढ़ी हो जाती है। थोड़ा पानी या गोश्त का शोरबा डालकर हल्की से मध्यम आंच पर धीरे से गरम करें, लगातार चलाते हुए ताकि नीचे न लगे। 3 महीने तक फ्रीज़ करें, फ्रिज में रात भर थॉ करें, और गार्निश सिर्फ परोसते वक़्त ताज़ी डालें।","mistakes":["गोश्त पर फूड प्रोसेसर इस्तेमाल करना। इससे रेशे छोटे कट जाते हैं और रेशेदार हलीम के बजाय दानेदार सूप बनता है।","रात भर भिगोना छोड़ देना। दाने कुरकुरे रह जाते हैं और टूटने में बहुत ज़्यादा समय लेते हैं।","तेज़ आंच पर पकाना और न चलाना। गाढ़ी हलीम तले पर लगकर जल जाती है।","इसे बहुत पतला परोसना। हल्की आंच पर उबालते और मथते रहें जब तक स्टार्च इसे इतना गाढ़ा न कर दे कि यह चम्मच पर ढेर बन जाए।"],"faq":[["क्या मैं हलीम फ्रीज़ कर सकता हूं?","जी हां। हलीम बहुत अच्छी तरह फ्रीज़ होती है। इसे पूरी तरह ठंडा करें, एयरटाइट डिब्बों में बांटकर 3 महीने तक फ्रीज़ करें। गरम करने से पहले फ्रिज में रात भर थॉ करें।"],["हलीम को दोबारा कैसे गरम करें?","ठंडा होने पर हलीम बहुत गाढ़ी हो जाती है। इसे एक बर्तन में थोड़ा पानी या गोश्त का शोरबा डालकर हल्की से मध्यम आंच पर गरम करें, लगातार चलाते हुए ताकि तले पर न लगे।"],["क्या मैं हलीम ग्लूटेन-मुक्त बना सकता हूं?","पारंपरिक हलीम गेहूं और जौ पर निर्भर करती है, जिनमें ग्लूटेन होता है। ग्लूटेन-मुक्त बनाने के लिए गेहूं और जौ की जगह रोल्ड ओट्स और ब्राउन राइस इस्तेमाल करें।"],["अगर मेरी हलीम बहुत पतली हो तो क्या करूं?","इसे हल्की आंच पर बिना ढके उबालते रहें और लकड़ी के चम्मच से मथते रहें। दालों और गेहूं का स्टार्च अतिरिक्त नमी भाप बनकर निकलने पर मिश्रण को गाढ़ा कर देता है।"]]},"chicken-korma":{"intro":"चिकन कोरमा पाकिस्तान की मशहूर जश्न वाली करी है, जो शादियों, ईद के खानों और दावतों में परोसी जाती है, शीरमाल या गरम नान के साथ। यह मुगल दरबार से आई है, जहां गोश्त को दही और मसालों में मैरिनेट करके धीमी आंच पर पकाया जाता था। असली कोरमे का राज़ सादा है: हड्डी वाला चिकन, कुरकुरी तली हुई प्याज़, फुल फैट दही और गरम मसालों का मिश्रण — न टमाटर, न क्रीम। प्याज़ को गहरा सुनहरा भूरा तलकर दही के साथ पीसा जाता है, जिससे ग्रेवी को मशहूर लाल-भूरा रंग और रेशमी बनावट मिलती है। यह हल्का, भरपूर और खुशबूदार है, आखिर में केवड़ा पानी और अदरक डाला जाता है, और अगले दिन यह और भी स्वादिष्ट लगता है।","ing":["चिकन 1 kg","हड्डी वाला","बिना खाल के","8 से 10 टुकड़ों में कटा हुआ","प्याज़ 3 मध्यम (पतली कटी हुई)","दही 1 कप","फुल फैट","फेंटी हुई (½ कप मैरिनेट के लिए, ½ कप प्याज़ के पेस्ट के लिए)","अदरक-लहसुन पेस्ट 3 tsp (1 tbsp)","धनिया पाउडर 3 tsp (1 tbsp)","लाल मिर्च पाउडर 1 tsp","हल्दी पाउडर ½ tsp","नमक 1½ tsp","तेल या घी ½ कप","तेज पत्ता 3","हरी इलायची 6","काली इलायची 2","लौंग 7","दालचीनी 2 टुकड़े","जीरा 1½ tsp","जायफल ¼ टुकड़ा","जावंत्री 2","चक्र फूल ½","केवड़ा पानी 1 tsp","ताज़ा अदरक 1 इंच का टुकड़ा","बारीक कटा हुआ (गार्निश के लिए)","कटे हुए बादाम ½ tbsp","गार्निश के लिए (वैकल्पिक)","पानी 2 कप"],"steps":["हरी इलायची, काली इलायची, लौंग, दालचीनी, जीरा, जायफल, जावंत्री और चक्र फूल को बारीक पाउडर बना लें। चिकन को पिसे हुए मसालों और ½ कप दही के साथ मिलाकर ढककर 30 मिनट मैरिनेट करें।","एक बड़े भारी बर्तन में तेल या घी मध्यम-तेज़ आंच पर गरम करें और कटी हुई प्याज़ को बार-बार चलाते हुए गहरा सुनहरा भूरा और कुरकुरा होने तक तलें, लगभग 15 मिनट। उन्हें छलनी वाले चम्मच से निकालकर निथारकर ठंडा करें।","ठंडी हुई तली प्याज़ को बची हुई ½ कप दही के साथ पूरी तरह चिकना होने तक ब्लेंड करें।","उसी तेल में तेज पत्ते डालकर 30 सेकंड तक भूनें जब तक खुशबू न आने लगे, फिर अदरक-लहसुन पेस्ट डालकर 1 से 2 मिनट भूनें।","मैरिनेट किया हुआ चिकन धनिया पाउडर, लाल मिर्च पाउडर, हल्दी और नमक के साथ डालकर तेज़ आंच पर 4 मिनट भूनें, जब तक चिकन का रंग न बदल जाए।","1 कप पानी डालकर उबाल लाएं, फिर ढककर हल्की से मध्यम आंच पर 25 से 30 मिनट पकाएं, जब तक चिकन नरम न हो जाए।","तली प्याज़ और दही का पेस्ट बचे हुए 1 कप पानी के साथ डालकर मिलाएं और तेज़ आंच पर 4 से 5 मिनट पकाएं, जब तक ग्रेवी लाल-भूरी न हो जाए और तेल ऊपर न आ जाए।","केवड़ा पानी और आधा बारीक कटा अदरक डालकर मिलाएं, 2 से 3 मिनट धीमी आंच पर पकाएं, फिर 5 मिनट रखें। बचे हुए अदरक और कटे हुए बादाम से सजाकर नान या रोटी के साथ गरम परोसें।"],"tip":"दही को पूरी तरह चिकना होने तक फेंटें और हल्की आंच पर लगातार चलाते हुए डालें। ठंडी या गांठ वाली दही को बहुत गरम बर्तन में डालना ही उसके फटने और दानेदार होने की सबसे बड़ी वजह है।","notes":["हड्डी वाला, बिना खाल का चिकन सबसे बढ़िया ग्रेवी देता है। हड्डियां स्वाद देती हैं और गोश्त दही में पकने पर रसीला रहता है।","सिर्फ फुल फैट दही इस्तेमाल करें। कम फैट वाली दही पतली होती है, आसानी से फट जाती है और कभी कोरमे की क्रीमी ग्रेवी नहीं देती।","असली कोरमे में न टमाटर होते हैं, न क्रीम। रंग तली प्याज़ और लाल मिर्च पाउडर से आता है, और भरपूरपन दही और घी से।","प्याज़ को खूब तेल में गहरा सुनहरा भूरा होने तक तलें, न हल्का, न जला हुआ। हल्की प्याज़ से हल्की, मीठी ग्रेवी बनती है; जली प्याज़ पूरी कोरमा कड़वा कर देती है।"],"variations":["बादामी कोरमा: 20 बादाम और 10 काजू भिगोकर बारीक पेस्ट बना लें और प्याज़-दही के पेस्ट के साथ मिलाएं, जिससे ग्रेवी और भी भरपूर और मेवेदार हो जाएगी।","मटन कोरमा: चिकन की जगह 1 kg हड्डी वाला मटन या बकरे का गोश्त लें और ढककर 1 से 1.5 घंटे पकाएं, ज़रूरत पड़ने पर पानी और बालते हुए, जब तक नरम न हो जाए।","आलू कोरमा: 2 बड़े आलू, हर एक को 8 टुकड़ों में काटकर, खड़े मसालों के बाद चिकन डालने से पहले 3 से 5 मिनट तलें।"],"serving":"गोरमा को गरम, चौड़े बर्तन में परोसें, ग्रेवी चिकन के ऊपर डालकर, बारीक कटे अदरक और कटे हुए बादाम से सजाकर। कोरमा पारंपरिक रूप से गरम तंदूरी नान, शीरमाल या ताफ़तान के साथ परोसा जाता है, या रोटी या सादे बासमती चावल के साथ। साथ में रायता और कचुंबर सलाद भी मेज़ पर रखें।","storage":"ठंडा करके एयरटाइट डिब्बे में फ्रिज में 3 दिन तक रखें। हल्की आंच पर बर्तन में धीरे-धीरे गरम करें, बार-बार चलाते हुए, अगर ग्रेवी गाढ़ी हो गई हो तो थोड़ा पानी मिलाएं। 3 महीने तक फ्रीज़ करें, फ्रिज में रात भर थॉ करें, और अदरक और बादाम की गार्निश सिर्फ परोसते वक्त ताज़ा डालें।","mistakes":["ठंडी या बिना फेंटी दही को बहुत गरम बर्तन में डालना। यह दानेदार दही में फट जाती है और फिर कभी वापस नहीं मिलती।","प्याज़ को बहुत हल्का या बहुत ज़्यादा तलना। हल्की प्याज़ से हल्की, मीठी ग्रेवी बनती है; जली प्याज़ पूरी कोरमा कड़वा कर देती है।","मैरिनेट छोड़ देना। दही और मसालों में 30 मिनट मैरिनेट करने से चिकन नरम होता है और स्वाद बनता है।","बहुत ज़्यादा पानी डालना या तुरंत परोस देना। ग्रेवी इतनी गाढ़ी रखें कि वह चिकन पर चिपक जाए, और कोरमे को 5 मिनट रखें ताकि तेल ऊपर आ जाए और स्वाद बैठ जाए।"],"faq":[["क्या मैं चिकन कोरमा फ्रीज़ कर सकता हूं?","जी हां। इसे पूरी तरह ठंडा करें, एयरटाइट डिब्बों में भरकर 3 महीने तक फ्रीज़ करें। फ्रिज में रात भर थॉ करें और हल्की आंच पर धीरे-धीरे गरम करें, बार-बार चलाते हुए।"],["मेरी कोरमे में दही क्यों फट गई?","दही तब फटती है जब वह ठंडी, गांठ वाली हो या बहुत गरम बर्तन में डाली जाए। हमेशा दही को चिकना होने तक फेंटें, बर्तन को आंच से उतारकर या आंच हल्की करके डालें, और डालते वक्त लगातार चलाते रहें।"],["क्या मैं कोरमे के लिए बिना हड्डी का चिकन इस्तेमाल कर सकता हूं?","जी हां। बिना हड्डी की जांघ सबसे अच्छी रहती है और रसीली रहती है। ढककर पकाने का समय लगभग 20 मिनट कर दें, क्योंकि बिना हड्डी का चिकन हड्डी वाले टुकड़ों से जल्दी पकता है।"],["क्या मैं बाज़ार की तली हुई प्याज़ इस्तेमाल कर सकता हूं?","जी हां। पाकिस्तानी या भारतीय किराने की दुकान से मिलने वाली कुरकुरी तली प्याज़ (बारिस्ता) अच्छी रहती है। 1 से 1¼ कप इस्तेमाल करें, और ध्यान रखें कि उन पर कॉर्नफ्लाउर न लगा हो।"]]},"aloo-paratha":{"intro":"आलू पराठा पंजाब का सबसे पसंदीदा भरा हुआ नाश्ते का पराठा है, मसालेदार मैश किए हुए आलू से भरी हुई गेहूं की रोटी, जिसे तवे पर घी के साथ सुनहरा सेंका जाता है। यह पंजाब और पाकिस्तान में सर्दियों की सुबहों और ढाबों का नाश्ता है: बाहर से नरम, परतदार और अंदर से गरम, खट्टा-मीठा आलू का मसाला, तवे से उतरते ही ऊपर सफ़ेद मक्खन के साथ खाया जाता है। आटा सादा है — गेहूं का आटा, नमक, तेल और पानी, जिसे नरम होने तक रखा जाता है। भरावन उबले आलू हैं, जिन्हें पूरी तरह चिकना मैश करके प्याज़, हरी मिर्च, ताज़ा धनिया, अदरक और लाल मिर्च, जीरा, गरम मसाला और अमचूर के क्लासिक मसालों के साथ मिलाया जाता है। बिना फटे बेलने के लिए थोड़ी प्रैक्टिस चाहिए, लेकिन जब आटा नरम हो और भरावन ठंडा और चिकना हो, तो पराठे खूबसूरती से फूलते हैं।","ing":["गेहूं का आटा 2 कप","और बेलने के लिए थोड़ा अतिरिक्त","नमक 1 tsp (½ tsp आटे के लिए, ½ tsp भरावन के लिए)","तेल 2 tbsp (आटे के लिए)","पानी लगभग ¾ कप (गूंथने के लिए)","आलू 3 मध्यम","उबले","छीले","मैश किए हुए","प्याज़ 1 छोटी","बारीक कटी हुई","हरी मिर्च 2","बारीक कटी हुई","ताज़ा धनिया पत्ते 2 tbsp (बारीक कटे हुए)","अदरक पेस्ट 1 tsp","लाल मिर्च पाउडर 1 tsp","जीरा पाउडर ½ tsp","गरम मसाला ½ tsp","अमचूर (सूखा आम पाउडर) ¾ tsp","धनिया बीज ½ tsp","अजवाइन ¼ tsp","घी 2 tbsp (सेंकने के लिए)"],"steps":["आलुओं को नमकीन पानी में पूरी तरह नरम होने तक उबालें, लगभग 20 मिनट, फिर छीलकर पूरी तरह चिकना मैश करें, बिना किसी गांठ के। मैश को फैलाकर पूरी तरह ठंडा होने दें।","एक बड़े कटोरे में आटा, ½ tsp नमक और तेल डालें। थोड़ा-थोड़ा पानी डालते हुए नरम, चिकना और न चिपकने वाला आटा गूंथें, लगभग 5 मिनट। ढककर 30 मिनट रख दें।","ठंडे मैश किए आलू में प्याज़, हरी मिर्च, धनिया पत्ते, अदरक पेस्ट, लाल मिर्च पाउडर, जीरा पाउडर, गरम मसाला, अमचूर, धनिया बीज, अजवाइन और ½ tsp नमक मिलाएं। भरावन को 4 बराबर गोलों में बांट लें।","रखे हुए आटे को 4 बराबर गोलों में बांटें। एक गोले को लगभग 4 इंच की छोटी रोटी में बेलें, बीच में भरावन का एक गोला रखें, फिर किनारों को ऊपर उठाकर मज़बूती से बंद करें।","भरे हुए गोले पर हल्का आटा छिड़कें और उसे धीरे-धीरे और बराबर दबाव से लगभग 7 इंच की गोल पराठे में बेलें, बेलते समय घुमाते रहें ताकि वह बराबर रहे।","तवा या चपटी कड़ाही को मध्यम-तेज़ आंच पर गरम करें। पराठा उस पर रखें और 30 से 40 सेकंड तक सेंकें जब तक छोटे बुलबुले न दिखें, फिर पलट दें।","ऊपर की तरफ लगभग ½ tsp घी लगाएं, फिर से पलटें और करछुल से हल्के से दबाएं, फिर दूसरी तरफ भी थोड़ा घी लगाएं। दोनों तरफ सुनहरे-भूरे धब्बे आने तक सेंकें, हर पराठे के लिए लगभग 2 मिनट।","तवे से उतरते ही गरम परोसें, ऊपर सफ़ेद मक्खन, ठंडी दही और अचार के साथ। बाकी पराठों के साथ यही दोहराएं।"],"tip":"आलुओं को पूरी तरह चिकना मैश करें और भरने से पहले पूरी तरह ठंडा होने दें। गरम या गांठ वाला मैश नरम और गीला होता है, और बेलते समय आटे से बाहर निकल जाता है।","notes":["पुराने आलू इस्तेमाल करें, नए नहीं। पुराने, स्टार्च वाले आलू सूखे और फूले हुए मैश होते हैं; नए आलू चिपचिपे और गीले हो जाते हैं और पराठा फाड़ देते हैं।","आटा नरम और लचीला होना चाहिए, सख्त नहीं। सख्त आटा भरावन बंद करते समय फट जाता है और बिना फटे पतला नहीं बेला जाता।","भरावन आटे के गोले से थोड़ा छोटा रखें। ज़्यादा भरावन बाहर निकल जाता है; बहुत कम भरावन से पराठा चपटा और खाली लगता है।","बराबर दबाव से धीरे-धीरे बेलें और बेलते समय पराठे को घुमाते रहें। एक जगह ज़ोर से दबाने से आटा पतला हो जाता है और भरावन बाहर निकल जाता है।"],"variations":["पनीर आलू पराठा: भरावन में ½ कप कसा हुआ पनीर मिलाएं, जिससे भरावन और भी भरपूर, नरम और आसानी से एक साथ रहता है।","मेथी आलू पराठा: भरावन में 2 tbsp बारीक कटी ताज़ा मेथी पत्तियां मिलाएं, जिससे सर्दियों का थोड़ा कड़वा, खुशबूदार स्वाद मिलता है।","चीज़ आलू पराठा: हर भरावन के गोले में 2 tbsp कसा हुआ मोज़रेला या चेडर डालें, जिससे बीच में नरम, पिघला हुआ स्वाद मिलता है जो बच्चों को पसंद आता है।"],"serving":"तवे से उतरते ही गरम परोसें, हर व्यक्ति को एक या दो पराठे, ऊपर पिघलता हुआ सफ़ेद मक्खन, ठंडी दही या योगर्ट का कटोरा, आम या मिक्स अचार और हरी चटनी के साथ। आलू पराठा पारंपरिक रूप से नाश्ते का व्यंजन है, लेकिन चाय के कप के साथ किसी भी भोजन में परोसा जाता है।","storage":"पके हुए पराठे एयरटाइट डिब्बे में फ्रिज में 2 दिन तक रखे जा सकते हैं; थोड़े घी के साथ गरम तवे पर फिर से कुरकुरा होने तक गरम करें। अकेला आलू का भरावन फ्रिज में 2 दिन तक और आटा कसकर लपेटकर 2 दिन तक रहता है। पके हुए पराठों को बीच में बटर पेपर रखकर 1 महीने तक फ्रीज़ करें और जमे हुए ही तवे पर गरम करें।","mistakes":["गरम या गांठ वाले आलू भरना। गरम मैश नरम और गीला होता है, और गांठें आटे को छेद देती हैं, इसलिए बेलते समय भरावन बाहर निकल जाता है।","सख्त आटा गूंथना या आराम न देना। सख्त, बिना आराम किया आटा बंद करते समय फट जाता है और बेलते समय टूट जाता है।","पराठे में ज़्यादा भरावन डालना। आटे से ज़्यादा भरावन किनारों से बाहर निकल जाता है और तवे पर चिपक जाता है।","बहुत गरम या बहुत ठंडे तवे पर सेंकना। बहुत गरम तवा बाहर से जला देता है, अंदर कच्चा रहता है; ठंडा तवा पराठे को सुखा देता है और वह नरम और परतदार होने के बजाय सख्त हो जाता है।"],"faq":[["क्या मैं आलू पराठा पहले से बनाकर फ्रीज़ कर सकता हूं?","जी हां। पराठे सेंकें, पूरी तरह ठंडा करें, हर एक के बीच बटर पेपर रखकर ढेर लगाएं और 1 महीने तक फ्रीज़ करें। जमे हुए ही थोड़े घी के साथ गरम तवे पर कुरकुरा और पूरी तरह गरम होने तक गरम करें।"],["बेलते समय आलू का भरावन बाहर क्यों निकल जाता है?","भरावन तब बाहर निकलता है जब मैश गरम या गांठ वाला हो, आटा सख्त हो, या भरावन ज़्यादा हो। आलुओं को पूरी तरह चिकना मैश करें, पूरी तरह ठंडा करें, आटे को 30 मिनट आराम दें, और भरावन का गोला आटे के गोले से थोड़ा छोटा रखें।"],["क्या मैं भरावन में प्याज़ छोड़ सकता हूं?","जी हां। प्याज़ वैकल्पिक है; कई पंजाबी घरों में आलू पराठा बिना प्याज़ के बनता है। इसे छोड़ दें और वही ताज़ा, खट्टा स्वाद पाने के लिए थोड़ा ज़्यादा धनिया और नींबू का रस डालें।"],["क्या मैं सेंकने के लिए घी की जगह तेल इस्तेमाल कर सकता हूं?","जी हां। घी की जगह किसी भी हल्के तेल से पराठे सेंकें, वे फिर भी कुरकुरे और सुनहरे बनेंगे। घी से क्लासिक धुएँ जैसी खुशबू और परतदार बनावट मिलती है, इसलिए जब हो सके घी ही इस्तेमाल करें।"]]},"kheer":{"intro":"खीर पाकिस्तान की क्लासिक चावल की खीर है — बासमती चावल को फुल-क्रीम दूध में धीमी आंच पर तब तक पकाया जाता है जब तक वह गाढ़ी और मलाईदार न हो जाए, फिर चीनी, इलायची, केसर और गुलाब जल से मीठा और खुशबूदार बनाया जाता है, और ऊपर से बादाम, काजू, पिस्ता और सुनहरी किशमिश डाली जाती है। यह पाकिस्तान और उत्तर भारत में ईद, शादियों और पारिवारिक दावतों की मिठाई है, छोटी कटोरियों में गरम या ठंडी परोसी जाती है, और ऊपर जमी हुई पतली मलाई हर किसी को चाहिए होती है। इसमें सिर्फ मुट्ठी भर सामग्री और एक भारी तले की कड़ाही चाहिए, लेकिन इसमें धैर्य का फल मिलता है: धीमी आंच, बार-बार चलाना और समय, साधारण दूध और चावल को रेशमी और खुशबूदार मिठाई में बदल देते हैं।","ing":["बासमती चावल ¼ कप","धोकर 20 मिनट भिगोया हुआ","फुल-क्रीम दूध 1 लीटर","चीनी 6 बड़े चम्मच","हरी इलायची पाउडर ½ छोटा चम्मच (या 5–6 हरी इलायची, कुटी हुई)","केसर एक उदार चुटकी (14–16 रेशे)","1 बड़े चम्मच गरम दूध में भिगोया हुआ","बादाम 1 बड़ा चम्मच (कटे हुए)","काजू 1 बड़ा चम्मच (कटे हुए)","पिस्ता 1 बड़ा चम्मच (कटे हुए)","सुनहरी किशमिश 1 बड़ा चम्मच","गुलाब जल 1 बड़ा चम्मच (वैकल्पिक)"],"steps":["¼ कप बासमती चावल को दो-तीन बार धोएं जब तक पानी साफ न हो जाए, फिर 15 से 20 मिनट तक पर्याप्त पानी में भिगोएं। छानकर अलग रखें।","1 लीटर फुल-क्रीम दूध भारी तले की कड़ाही में डालें और धीमी से मध्यम-धीमी आंच पर रखें। बीच-बीच में चलाते रहें ताकि दूध तले में न लगे, और उबाल आने दें।","एक छोटी कटोरी में 1 बड़ा चम्मच गरम दूध निकालें, उसमें एक चुटकी केसर डालें और भिगोने के लिए अलग रखें। केसर दूध को रंग और स्वाद देगा।","जब दूध उबलने लगे, चावल छानकर कड़ाही में डालें। अच्छी तरह मिलाएं, आंच धीमी करें और बिना ढके, बार-बार चलाते हुए धीमी आंच पर पकाएं जब तक चावल आधा न पक जाए।","6 बड़े चम्मच चीनी डालें और घुलने तक मिलाएं। धीमी आंच पर पकाना जारी रखें, बीच-बीच में चलाते हुए और कड़ाही के किनारों पर जमी मलाई को खुरचकर खीर में मिलाते हुए, जब तक चावल लगभग पक न जाए।","½ छोटा चम्मच हरी इलायची पाउडर, 1-1 बड़ा चम्मच कटे हुए बादाम, काजू और पिस्ता, और केसर वाला दूध डालें। अच्छी तरह मिलाएं और धीमी आंच पर तब तक पकाएं जब तक चावल पूरी तरह नरम न हो जाए और खीर गाढ़ी न हो जाए।","जब चावल पूरी तरह नरम हो जाएं और खीर चम्मच के पीछे चिपकने लगे, आंच बंद कर दें। 1 बड़ा चम्मच सुनहरी किशमिश और अगर चाहें तो 1 बड़ा चम्मच गुलाब जल मिलाएं। याद रखें, खीर ठंडी होने पर और गाढ़ी हो जाती है।","अलग-अलग कटोरियों में डालें और गरम परोसें, या पूरी तरह ठंडा करके कम से कम 2 घंटे फ्रिज में रखें। परोसने से पहले ऊपर से कटे हुए पिस्ता और बादाम डालें।"],"tip":"आंच धीमी रखें और बार-बार चलाएं, कड़ाही के किनारों को खुरचते रहें। किनारों पर जमी दूध की मलाई सबसे स्वादिष्ट हिस्सा होती है — उसे वापस खीर में मिलाएं और खीर पतली होने के बजाय रेशमी बन जाती है।","notes":["फुल-क्रीम दूध ही इस्तेमाल करें। कम वसा वाला दूध पतली, पानी जैसी खीर बनाता है जो कितनी भी देर पकाएं, कभी मलाईदार नहीं होती।","सबसे अच्छी खुशबू के लिए बासमती चावल इस्तेमाल करें। कोई भी खुशबूदार लंबे दाने वाला चावल चलेगा, लेकिन साधारण छोटे दाने वाला चावल चिपचिपा हो जाता है और स्वाद फीका कर देता है।","चावल और दूध का अनुपात 1:16 रखें — 1 लीटर दूध में ¼ कप चावल। ज़्यादा चावल खीर को गाढ़ा और भारी बना देता है; कम चावल से वह पतली और दूधिया रहती है।","खीर ठंडी होने पर बहुत गाढ़ी हो जाती है, इसलिए आंच तब बंद करें जब वह आपकी चाहत से थोड़ी पतली हो। अगर ज़्यादा गाढ़ी जम जाए तो परोसने से पहले थोड़ा गरम दूध मिलाएं।"],"variations":["सेवइयां खीर: चावल की जगह ¾ कप भुनी हुई सेवइयां लें, 10 मिनट तक नरम होने तक पकाएं, फिर उसी तरह चीनी, इलायची और मेवे डालें।","गुड़ वाली खीर: चीनी की जगह कसा हुआ गुड़ लें, लेकिन उसे तभी डालें जब खीर पककर 4 से 5 मिनट ठंडी हो चुकी हो, वरना दूध फट सकता है।","खोया खीर: ज़्यादा समृद्ध, रबड़ी जैसी खीर के लिए चीनी के साथ ½ कप मला हुआ खोया मिलाएं, और चीनी 1 बड़ा चम्मच कम कर दें।"],"serving":"छोटी-छोटी कटोरियों में गरम या ठंडी परोसें, ऊपर से कटे हुए पिस्ता और बादाम और केसर के कुछ रेशे डालें। खीर त्योहार के खाने के बाद की क्लासिक मिठाई है, और इसे अक्सर गरम पूरियों के साथ परोसा जाता है। एक छोटी कटोरी ही काफी है — यह बहुत समृद्ध होती है।","storage":"बची हुई खीर को बंद डिब्बे में फ्रिज में रखें और 1 से 2 दिन में खाएं। ठंडी परोसें, या धीरे से गरम करके परोसें। अगर खीर बहुत गाढ़ी हो गई हो तो गरम करने से पहले थोड़ा दूध मिलाएं। खीर को फ्रीज़ न करें — दूध फट जाता है और बनावट दानेदार हो जाती है।","mistakes":["तेज़ आंच पर या पतले तले की कड़ाही में पकाना। दूध तले में जल जाता है और जला हुआ स्वाद पूरे बर्तन में फैल जाता है।","कम वसा वाला दूध इस्तेमाल करना। खीर पतली और पानी जैसी रहती है और असली खीर जैसी मलाईदार, समृद्ध बनावट कभी नहीं बनती।","ज़्यादा चावल डालना। प्रति लीटर दूध में ¼ कप से ज़्यादा चावल खीर को रेशमी होने के बजाय गाढ़ा, भारी और चिपचिपा बना देता है।","खीर को बिना चलाए छोड़ देना। दूध तले में लगकर जल जाता है, और चावल गांठों में जम जाता है जो फिर नहीं टूटतीं।"],"faq":[["क्या मैं खीर पहले से बना सकती हूँ?","हाँ। खीर ठंडी होने के बाद अगले दिन और भी स्वादिष्ट लगती है। एक दिन पहले बनाएं, बंद डिब्बे में फ्रिज में रखें और 1 से 2 दिन में खाएं। अगर बहुत गाढ़ी जम गई हो तो परोसने से पहले थोड़ा दूध मिलाएं।"],["मेरी खीर पतली और पानी जैसी क्यों है?","पतली खीर का मतलब आमतौर पर कम वसा वाला दूध, कम पकाने का समय, या कम चावल है। फुल-क्रीम दूध इस्तेमाल करें, 1 लीटर दूध में ¼ कप चावल का अनुपात रखें, और धीमी आंच पर तब तक पकाएं जब तक चावल पूरी तरह नरम न हो जाए और मिश्रण चम्मच के पीछे चिपकने न लगे।"],["क्या मैं चीनी की जगह गुड़ इस्तेमाल कर सकती हूँ?","हाँ, लेकिन गुड़ तभी डालें जब खीर पककर 4 से 5 मिनट ठंडी हो चुकी हो। उबलते दूध में गुड़ डालने से दूध फट सकता है।"],["खीर गरम परोसनी चाहिए या ठंडी?","दोनों तरह से। कड़ाही से उतारकर गरम परोसें, या पूरी तरह ठंडा करके कम से कम 2 घंटे फ्रिज में रखें। ठंडी खीर गाढ़ी होती है, और पाकिस्तान में ईद और शादियों में खीर अक्सर इसी तरह परोसी जाती है।"]]},"seekh-kebab":{"intro":"सीख कबाब पाकिस्तान का धुएँदार, कोयले पर सेका हुआ क्लासिक है — कीमा प्याज़, लहसुन, अदरक, हरी मिर्च, धनिया और पुदीने के साथ गूँधा जाता है, बेसन और अंडे से बाँधा जाता है, सीखों पर लगाया जाता है और कोयले पर तब तक सेका जाता है जब तक बाहर से कुरकुरा और अंदर से रसदार न हो जाए। यह ईद, शादियों और पारिवारिक दावतों के बारबेक्यू का मुख्य आकर्षण है, गरम नान, कटी हुई प्याज़, नींबू और पुदीने की चटनी के साथ परोसा जाता है। इस रेसिपी के लिए सिर्फ एक कटोरा और एक ग्रिल चाहिए, लेकिन इसमें सावधानी का फल मिलता है: कीमे में चर्बी, सूखी प्याज़, अच्छी गुँधाई और 30 मिनट की ठंडक ही कबाबों को सीख पर टिकाए रखती है, वरना वे कोयलों में गिर जाते हैं।","ing":["भेड़ का कीमा (या गाय का कीमा, 20% चर्बी वाला) 500g","प्याज़ 1 मध्यम","बारीक कटी हुई","लहसुन 4 कलियाँ","बारीक कटा हुआ","अदरक 2cm टुकड़ा","कसा हुआ","हरी मिर्च 2","बारीक कटी हुई","ताज़ा धनिया पत्ते 30g (बारीक कटे हुए)","ताज़ा पुदीना पत्ते 15g (बारीक कटे हुए)","बेसन 2 tbsp","जीरा पाउडर 2 tsp","धनिया पाउडर 2 tsp","गरम मसाला 1 tsp","लाल मिर्च पाउडर 1 tsp","हल्दी पाउडर 1/2 tsp","नमक 1 tsp","अंडा 1","हल्का फेंटा हुआ","तेल (ब्रश करने के लिए)"],"steps":["प्याज़, लहसुन, अदरक, हरी मिर्च, धनिया और पुदीना बारीक काटें।","कीमे में कटी हुई सामग्री, बेसन, अंडा और सारे मसाले मिलाएं, और अच्छी तरह गूँधें जब तक मिश्रण बँध न जाए।","मिश्रण को 30 मिनट के लिए फ्रिज में ठंडा करें ताकि कबाब अपना आकार बनाए रखें।","हल्के तेल लगे हाथों से लगभग 80-90g मिश्रण को हर सीख के चारों ओर लगाकर लगभग 15cm लंबा, बराबर मोटा बेलन बनाएँ।","गरम कोयलों पर सेकें, बार-बार पलटते हुए और तेल लगाते हुए, जब तक बाहर से कुरकुरे और अंदर से पक न जाएँ — कोयले पर लगभग 10-12 मिनट (200C ओवन में 25 मिनट)।","कबाबों को 2 मिनट आराम दें, फिर उन्हें सीखों से उतारकर गरम प्लेट में रखें।","ऊपर से थोड़ा चाट मसाला और कटा हुआ धनिया छिड़कें।","गरम नान, कटी हुई प्याज़, नींबू के टुकड़े और पुदीने की चटनी के साथ गरम परोसें।"],"tip":"लगभग 20% चर्बी वाला कीमा इस्तेमाल करें और कटी हुई प्याज़ का पानी निचोड़ लें — दुबला या गीला कीमा सीख से गिर जाता है। मिश्रण को 30 मिनट ठंडा करना ही कबाबों को कोयलों पर सीख से चिपकाए रखता है।","notes":["लगभग 20% चर्बी वाला कीमा इस्तेमाल करें। दुबला कीमा सूख जाता है और टूट जाता है, और कबाब सीख से गिर जाते हैं।","मिलाने से पहले कटी हुई प्याज़ का पानी निचोड़ लें। गीली प्याज़ ही कबाबों के सीख से फिसलने की मुख्य वजह है।","आकार देने से पहले मिश्रण को 30 मिनट ठंडा करें। गरम कीमा कोयलों पर सीख से चिपकता नहीं है।","कबाबों को बराबर मोटा रखें, लगभग 2.5cm, ताकि वे बाहर से जले बिना अंदर तक पक जाएँ।"],"variations":["चिकन सीख कबाब: उन्हीं मसालों के साथ 500g चिकन कीमा (जाँघ का) इस्तेमाल करें, और नमी के लिए 1 tbsp क्रीम मिलाएं — चिकन कीमा दुबला होता है, इसलिए इसे ज़्यादा न पकाएँ।","बीफ़ सीख कबाब: 20% चर्बी वाला 500g बीफ़ कीमा और वही मसाला मिश्रण इस्तेमाल करें। बीफ़ कबाब सख्त होते हैं और ग्रिल पर 1 से 2 मिनट ज़्यादा लेते हैं।","हरा सीख कबाब (हरियाली): एक मुट्ठी और धनिया-पुदीना और 2 और हरी मिर्च डालें, और लाल मिर्च पाउडर छोड़ दें — ताज़ा, हरा और जड़ी-बूटियों वाला कबाब मिलेगा।"],"serving":"कबाबों को सीखों से उतारकर गरम नान या पराठे, कटी हुई कच्ची प्याज़, नींबू के टुकड़े और पुदीने की चटनी के साथ गरम परोसें, ऊपर से थोड़ा चाट मसाला छिड़कें। ये बारबेक्यू की थाली का मुख्य आकर्षण हैं — इन्हें रायते और सलाद के साथ रखें और हर कोई अपनी रैप बना ले। दस कबाब मुख्य भोजन के रूप में 4 लोगों के लिए, या मिली-जुली ग्रिल के हिस्से के रूप में 8 लोगों के लिए काफी हैं।","storage":"बचे हुए पके कबाबों को बंद डिब्बे में फ्रिज में रखें और 2 दिन में खाएं। गरम ओवन या ग्रिल पैन में धीरे से गरम करें जब तक अंदर तक गरम न हो जाएँ, ताकि वे रसदार रहें। बिना पके, आकार दिए हुए कबाबों को 24 घंटे तक फ्रिज में या 1 महीने तक फ्रीज़र में रखा जा सकता है — सेकने से पहले फ्रिज में पिघलाएँ। पिघले हुए कबाबों को दोबारा फ्रीज़ न करें।","mistakes":["दुबला कीमा इस्तेमाल करना। 20% से कम चर्बी वाला कीमा सूख जाता है और सीख से टूटकर गिर जाता है।","ठंडा करना छोड़ देना। गरम कीमे को आकार देने से नरम कबाब बनते हैं जो गरमी लगते ही सीख से फिसल जाते हैं।","प्याज़ में पानी छोड़ देना। गीली प्याज़ मिश्रण को बँधने नहीं देती और कबाब टूट जाते हैं।","कबाबों को असमान बनाना। मोटे और पतले हिस्से अलग-अलग गति से पकते हैं, इसलिए कुछ हिस्से जल जाते हैं जबकि दूसरे अंदर से कच्चे रह जाते हैं।"],"faq":[["सीख कबाब के लिए सबसे अच्छा मांस कौन सा है?","लगभग 20% चर्बी वाला भेड़ या गाय का कीमा। दुबला कीमा सूख जाता है और सीख से गिर जाता है; चर्बी कबाबों को रसदार रखती है और बाँधने में मदद करती है।"],["मेरे कबाब सीख से क्यों गिर जाते हैं?","आमतौर पर गीली प्याज़ या गरम, बिना ठंडा किया हुआ मिश्रण। कटी हुई प्याज़ का पानी निचोड़ लें, अच्छी तरह गूँधें, और आकार देने से पहले मिश्रण को 30 मिनट ठंडा करें।"],["क्या मैं बिना कोयले के सीख कबाब बना सकती हूँ?","हाँ। 200C पर पहले से गरम ओवन में 25 मिनट बेक करें, फिर हर तरफ 5 मिनट ग्रिल करें जब तक कुरकुरे न हो जाएँ। तेज़ आंच पर ग्रिल पैन भी काम करता है।"],["क्या मैं सीख कबाब पहले से बना सकती हूँ?","हाँ। कबाबों को सीखों पर आकार देकर ढकें और 24 घंटे तक फ्रिज में रखें, फिर परोसने से ठीक पहले सेकें। बिना पके, आकार दिए हुए कबाबों को 1 महीने तक फ्रीज़ भी कर सकते हैं; सेकने से पहले फ्रिज में पिघलाएँ।"]]},"kabuli-pulao":{"intro":"काबुली पुलाव अफ़ग़ानिस्तान का राष्ट्रीय व्यंजन है — सुनहरे बासमती चावल, नरम और हल्के मसालों वाला गोश्त, ऊपर से कैरामेलाइज़्ड गाजर और रसीली किशमिश, और कटे हुए बादाम और पिस्ते के साथ। चावल को उसका सुनहरा रंग केसर से नहीं, कैरामेलाइज़्ड चीनी से मिलता है, और गोश्त को उसके ही शोरबे में नरम होने तक पकाया जाता है, जो फिर चावल को स्वाद देता है। यह अफ़ग़ान खाने की शान है, शादियों और पारिवारिक दावतों में परोसा जाता है, एक साझा थाली से खाया जाता है, अक्सर दस्तरख़ान पर बैठकर।","ing":["बासमती चावल 1 किलो","धोकर ठंडे पानी में 2 घंटे भिगोया हुआ","बकरे की टांग या शाना","हड्डी सहित 800 ग्राम","6 सेमी के टुकड़ों में कटा हुआ","वनस्पति तेल 200 मिली","प्याज़ 1","कटा हुआ","कुचला हुआ लहसुन या लहसुन का पेस्ट 1 बड़ा चम्मच","नमक 2 बड़े चम्मच","सफ़ेद चीनी 75 ग्राम (1/3 कप)","गरम मसाला 2 छोटे चम्मच (पिसी हुई लौंग, तेज़ पत्ता, इलायची और दालचीनी)","ताज़ा पिसी हुई इलायची 1.5 छोटा चम्मच","गाजर 250 ग्राम","छीलकर लंबी सलाइयों में कटी हुई","किशमिश या सूखे अंगूर 75 ग्राम","मिले हुए कटे हुए बादाम","पिस्ते 75 ग्राम (सजाने के लिए)"],"steps":["एक बड़ी कड़ाही में 50 मिली तेल मध्यम आंच पर गरम करें और प्याज़ को 6-8 मिनट तक सुनहरा होने तक पकाएं।","गोश्त, लहसुन और 1 बड़ा चम्मच नमक डालें और 8-10 मिनट तक पकाएं, जब तक गोश्त चारों ओर से अच्छी तरह भूरा न हो जाए। पानी डालें, आंच धीमी करें और गोश्त के नरम होने तक पकाएं, बीच-बीच में ऊपर से झाग हटाते रहें। गोश्त निकालकर अलग रख दें; शोरबा बचा लें।","आधी चीनी को एक गरम, सूखी कड़ाही में मध्यम आंच पर रखें और कड़ाही को हिलाते हुए 5-6 मिनट तक पकाएं, जब तक चीनी कैरामेलाइज़ न हो जाए।","ध्यान से 250 मिली (1 कप) बचा हुआ शोरबा, नमक, 1 छोटा चम्मच गरम मसाला और एक चुटकी इलायची पाउडर डालें। उबाल आने दें, फिर आंच से उतारकर अलग रख दें।","भीगे हुए चावल को छानें और एक बड़ी कड़ाही में उबलते पानी में 5 मिनट तक पकाएं, जब तक वह लगभग पक न जाए। छानकर वापस कड़ाही में डाल दें।","कैरामेलाइज़्ड चीनी वाला मिश्रण चावल पर डालें, एक चुटकी गरम मसाला डालें, और हल्के हाथ से सावधानी से मिलाएं जब तक चावल समान रूप से लिपटकर सुनहरा न हो जाए।","एक कड़ाही में 1 बड़ा चम्मच तेल मध्यम-तेज़ आंच पर गरम करें। गाजर और बची हुई चीनी डालें और 5 मिनट तक चलाएं, जब तक वह हल्की कैरामेलाइज़्ड और चमकदार न हो जाए। किशमिश डालें और 1 मिनट और पकाएं, फिर एक चुटकी इलायची मिलाकर अलग रख दें।","एक कड़ाही में 1 बड़ा चम्मच तेल धुआं उठने तक गरम करें और चावल पर डाल दें। बड़े चम्मच के पिछले सिरे से चावल में छेद करें ताकि भाप निकल सके। ऊपर से मसालेदार गाजर और गोश्त के टुकड़े रखें, ढककर चाय के तौलिए और फिर ढक्कन से कसकर बंद करें। तेज़ आंच पर 5 मिनट पकाएं, फिर आंच धीमी करके 10 मिनट और पकाएं। आंच से उतारकर ढका हुआ 10 मिनट छोड़ दें। परतों में परोसें: चावल, फिर गोश्त, फिर बचा हुआ चावल, ऊपर से मसालेदार गाजर, बादाम और पिस्ते।"],"tip":"गोश्त को जल्दबाज़ी में न पकाएं: उसे धीमी आंच पर तब तक पकाएं जब तक वह सचमुच नरम न हो जाए, और शोरबा बचा लें — वही चावल को स्वाद देता है। चावल को सिर्फ लगभग पकने तक उबालें; वह भाप में पूरा पकता है, और ज़्यादा पका हुआ चावल पुलाव को गीला कर देता है।","notes":["चावल को पूरे 2 घंटे भिगोएं। लंबे समय तक भीगा हुआ बासमती समान रूप से पकता है और टूटने के बजाय लंबा और अलग-अलग रहता है।","चीनी को ध्यान से कैरामेलाइज़ करें: वह गहरी सुनहरी होनी चाहिए, गहरी भूरी नहीं। जली हुई चीनी पूरे व्यंजन को कड़वा कर देती है।","हड्डी वाला गोश्त इस्तेमाल करें। हड्डियों से शोरबे में कोलेजन मिलता है और चावल बिना हड्डी वाले गोश्त से कहीं ज़्यादा समृद्ध बनता है।","अंतिम भाप के लिए बर्तन को चाय के तौलिए और ढक्कन से अच्छी तरह बंद करें। निकलती भाप चावल को पूरा करने के बजाय सुखा देती है।"],"variations":["चिकन काबुली पुलाव: गोश्त की जगह 800 ग्राम हड्डी वाली चिकन लें और सिर्फ 30-40 मिनट तक नरम होने तक पकाएं।","बीफ़ काबुली पुलाव: गोश्त की जगह 800 ग्राम हड्डी वाला बीफ़ लें और नरम होने तक पकाएं, लगभग 2 घंटे।","शाकाहारी पुलाव: गोश्त छोड़ दें और चावल को सब्ज़ी के शोरबे में पकाएं; गाजर और किशमिश दोगुनी कर दें और चने डालें।"],"serving":"एक बड़ी साझा थाली से परोसें: चावल की एक परत, फिर गोश्त, फिर बचा हुआ चावल, ऊपर से मसालेदार गाजर, किशमिश, बादाम और पिस्ते। साथ में सलाद और दही दें।","storage":"बचा हुआ खाना बंद डिब्बे में फ्रिज में रखें और 2 दिन में खाएं। थोड़े पानी या शोरबे के साथ ढकी हुई कड़ाही में धीमी आंच पर गरम करके परोसें। सजावट को फ्रीज़ न करें — अगर चावल और गोश्त फ्रीज़ कर रहे हैं तो गाजर, किशमिश और मेवे अलग रखें।","mistakes":["परतें लगाने से पहले चावल को पूरा पकाना। अधपका चावल भाप में पूरा पकता है; पूरा पका हुआ चावल गीला हो जाता है।","कैरामेलाइज़्ड चीनी को जलाना। गहरी भूरी चीनी कड़वी लगती है और चावल को सुनहरे के बजाय मैला रंग देती है।","भिगोना छोड़ देना। बिना भीगा बासमती असमान रूप से पकता है और बर्तन में टूट जाता है।","अंतिम भाप के लिए बर्तन को बिना बंद किए छोड़ देना। चावल सूख जाता है और ऊपरी परत सख्त रह जाती है।"],"faq":[["काबुली पुलाव बिरयानी से कैसे अलग है?","काबुली पुलाव में इलायची और गरम मसाले का हल्का स्वाद होता है, इसका सुनहरा रंग केसर से नहीं, कैरामेलाइज़्ड चीनी से आता है, और ऊपर से मीठी कैरामेलाइज़्ड गाजर और किशमिश डाली जाती है। बिरयानी में मसाले ज़्यादा होते हैं, तली हुई प्याज़ की परतें होती हैं, और आमतौर पर केसर से रंग दिया जाता है।"],["क्या मैं बिना हड्डी वाला गोश्त इस्तेमाल कर सकती हूँ?","हाँ, लेकिन हड्डी वाला गोश्त बेहतर है: हड्डियाँ शोरबे को स्वाद देती हैं जिसमें चावल पकता है। अगर आप बिना हड्डी वाला गोश्त इस्तेमाल करते हैं तो उसे कम समय तक पकाएं और बार-बार देखें ताकि वह सूख न जाए।"],["मेरा चावल गीला क्यों हो गया?","शायद चावल को परतें लगाने से पहले ज़्यादा देर पकाया गया था, या अंतिम भाप के लिए बर्तन बंद नहीं किया गया था। सिर्फ 5 मिनट तक अधपका करें जब तक लगभग पक न जाए, और बर्तन को चाय के तौलिए और ढक्कन से बंद करें ताकि चावल हल्की भाप में पूरा पके।"],["क्या मैं काबुली पुलाव पहले से बना सकती हूँ?","हाँ। गोश्त पकाकर और कैरामेलाइज़्ड चीनी वाला मिश्रण एक दिन पहले बनाकर फ्रिज में रख दें। उसी दिन चावल अधपका करें, सब कुछ परतों में लगाएं और भाप दें। बचा हुआ खाना फ्रिज में 2 दिन तक रहता है।"]]},"dolma":{"intro":"डोलमा — आर्मेनियाई में इसे टोलमा कहा जाता है — आर्मेनिया की क्लासिक भरवां अंगूर की पत्तियों का व्यंजन है: मसालेदार कीमा, लंबे दाने वाले चावल, प्याज़, अजमोद, पुदीना और लहसुन की भराई को नरम बेल की पत्तियों में लपेटा जाता है, मसालों में ऑलस्पाइस, दालचीनी और जीरा डाला जाता है, फिर नींबू की फाँकों के साथ बर्तन में कसकर जमाकर शोरबे में धीमी आंच पर तब तक पकाया जाता है जब तक चावल पक न जाए और पत्तियाँ नरम न हो जाएँ। यह आर्मेनिया में पारिवारिक जमावड़ों, शादियों और उत्सवों का व्यंजन है, बड़ी मात्रा में बनाया जाता है और दही या खीरा-टमाटर सलाद के साथ गरम परोसा जाता है। रोल बनाना थोड़ा अभ्यास माँगता है, लेकिन तरीका सरल है: धोएँ, मिलाएँ, रोल करें, कसकर जमाएँ, और धीमी आंच को बाकी काम करने दें।","ing":["अंगूर की पत्तियाँ 30-40 (1 जार, नमकीन पानी वाली) या ताज़ा पत्तियाँ","उबली हुई","कीमा किया हुआ भेड़ या गाय का मांस 500g (या दोनों का मिश्रण)","लंबे दाने वाला चावल 1 कप","धुला हुआ","प्याज़ 1 बड़ी","बारीक कटी हुई","ताज़ा अजमोद 1/2 कप","बारीक कटा हुआ","ताज़ा पुदीना 1/4 कप","बारीक कटा हुआ","लहसुन 3-4 कलियाँ","कूटा हुआ","पिसा हुआ ऑलस्पाइस 1 छोटा चम्मच","पिसी हुई दालचीनी 1/2 छोटा चम्मच","पिसी हुई काली मिर्च 1/4 छोटा चम्मच","पिसा हुआ जीरा 1/4 छोटा चम्मच","टमाटर सॉस या टमाटर पेस्ट 1/2 कप","नींबू 1","पतले टुकड़ों में कटा हुआ","जैतून का तेल 2-3 बड़े चम्मच","नमक 1 छोटा चम्मच","या स्वादानुसार","चिकन या सब्ज़ी का शोरबा 3 कप"],"steps":["जार वाली अंगूर की पत्तियों को ठंडे पानी में अच्छी तरह धोएँ ताकि अतिरिक्त नमकीन पानी निकल जाए; अगर ताज़ा पत्तियाँ इस्तेमाल कर रही हैं तो उन्हें उबलते पानी में 1-2 मिनट उबालें, फिर बर्फ के पानी में ठंडा करके सुखाएँ।","एक बड़े कटोरे में कीमा, धुला हुआ चावल, कटी हुई प्याज़, अजमोद, पुदीना, कूटा हुआ लहसुन, ऑलस्पाइस, दालचीनी, काली मिर्च, जीरा, 1 बड़ा चम्मच जैतून का तेल और 1/2 छोटा चम्मच नमक मिलाएँ, और हाथ से अच्छी तरह मिलाएँ जब तक सब बराबर न मिल जाए।","अंगूर की पत्ती को सीधा रखें, नसों वाला हिस्सा ऊपर, डंठल काटें, और पत्ती के नीचे के पास बीच में 1-2 बड़े चम्मच भराई रखें।","नीचे का किनारा भराई पर मोड़ें, किनारे अंदर मोड़ें, और कसकर एक साफ बेलन में रोल करें; सभी पत्तियों और भराई के साथ यही दोहराएँ।","एक बड़े बर्तन में कुछ टूटी हुई अंगूर की पत्तियाँ या नींबू की फाँकें बिछाएँ, फिर रोल किए हुए डोलमा को परतों में कसकर जमाएँ, परतों के बीच नींबू की फाँकें रखें।","टमाटर सॉस या पेस्ट को बचा हुआ जैतून का तेल, नमक और काली मिर्च के साथ मिलाएँ, और डोलमा पर डालें; ऊपर से और नींबू की फाँकें रखें।","इतना शोरबा डालें कि डोलमा ढक जाए, ऊपर एक गरम-सहनशील प्लेट या कुछ अंगूर की पत्तियाँ रखें ताकि वे दबे रहें, उबाल लाएँ, फिर ढककर धीमी आंच पर 1 से 1.5 घंटे तक पकाएँ जब तक चावल पक न जाए और पत्तियाँ नरम न हो जाएँ।","आंच से उतारें, थोड़ी देर रखें, और दही या खीरा-टमाटर सलाद के साथ गरम परोसें।"],"tip":"रोल को कसकर जमाएँ — अगर उन्हें हिलने की जगह मिली तो पकते समय वे खुल जाएँगे। ऊपर रखी प्लेट वैकल्पिक नहीं है; यह हर रोल को कसा हुआ और डूबा हुआ रखती है ताकि चावल बराबर पके।","notes":["जार वाली अंगूर की पत्तियों को बहुत अच्छी तरह धोएँ। नमकीन पानी वाली पत्तियाँ नमकीन होती हैं, और उन पर बचा हुआ नमकीन पानी नमक डालने से पहले ही पूरे बर्तन को बहुत नमकीन कर देगा।","लंबे दाने वाला चावल इस्तेमाल करें। छोटे दाने वाला चावल रोल के अंदर नरम और चिपचिपा हो जाता है और फूलने पर पत्तियों को फाड़ सकता है।","पत्तियों में ज़्यादा भराई न डालें। चावल पकते समय फूलता है, और बहुत भरी हुई रोल बर्तन में फट जाएगी।","आंच धीमी रखें और प्लेट अपनी जगह पर रखें। तेज़ उबाल रोल को ढीला कर देता है, जबकि धीमी, स्थिर आंच चावल को बराबर पकाती है और पत्तियों को नरम रखती है।"],"variations":["बिना मांस वाला (व्रत) डोलमा: मांस छोड़ दें और अतिरिक्त प्याज़, अजमोद, पुदीना और मुट्ठी भर कटे हुए अखरोट या पके हुए छोले के साथ 2 कप चावल इस्तेमाल करें; नींबू के साथ कमरे के तापमान पर परोसें।","पत्ता गोभी वाला डोलमा: अंगूर की पत्तियों की जगह उबली हुई पत्ता गोभी की पत्तियाँ इस्तेमाल करें, उसी तरह रोल करें — यह आर्मेनिया का आम सर्दियों का संस्करण है जब बेल की पत्तियाँ नहीं मिलतीं।","सिर्फ भेड़ के मांस वाला डोलमा: मिश्रण की जगह 500g कीमा किया हुआ भेड़ का मांस इस्तेमाल करें, अतिरिक्त पुदीना डालें, और लहसुन वाली दही (मत्सून) और नींबू के साथ परोसें।"],"serving":"गरम परोसें, प्रति व्यक्ति 5-6 रोल, साथ में एक चम्मच सादी दही या लहसुन वाली दही, नींबू की फाँकें और खीरा-टमाटर सलाद। डोलमा पारिवारिक भोजन और उत्सवों के लिए मुख्य व्यंजन है, लेकिन यह छोटी-छोटी डिशों की मेज़ का हिस्सा भी बन सकता है, कमरे के तापमान पर परोसा जाता है।","storage":"बचा हुआ डोलमा अपने पकाने वाले तरल में बंद डिब्बे में फ्रिज में रखें और 3 से 4 दिन में खाएँ। थोड़े शोरबे या पानी के साथ ढके हुए बर्तन में धीरे से गरम करें जब तक गरम न हो जाए। डोलमा 3 महीने तक फ्रीज़ भी अच्छी तरह हो जाता है; रात भर फ्रिज में पिघलाएँ और धीरे से गरम करें।","mistakes":["धोना छोड़ देना। नमकीन पानी से सीधी निकाली गई जार वाली पत्तियाँ डोलमा को बहुत नमकीन बना देती हैं, और दही भी इसे ठीक नहीं कर पाएगी।","पत्तियों में ज़्यादा भराई डालना। चावल पकते समय फूलता है, इसलिए ज़्यादा भरी हुई रोल फट जाती है और भराई बर्तन में फैल जाती है।","रोल को ढीला जमाना या प्लेट छोड़ देना। हिलने की जगह वाली रोल पकते समय खुल जाती हैं; उन्हें कसकर जमाएँ और दबाकर रखें।","उबालने के बजाय धीमी आंच पर पकाने की जगह तेज़ उबालना। तेज़ उबाल रोल को अलग कर देता है और पत्तियों को सख्त कर देता है, जबकि अंदर का चावल कच्चा रह जाता है।"],"faq":[["क्या मैं जार वाली पत्तियों की जगह ताज़ा अंगूर की पत्तियाँ इस्तेमाल कर सकती हूँ?","हाँ। ताज़ा पत्तियों को उबलते पानी में 1-2 मिनट तक उबालें जब तक वे नरम और लचीली न हो जाएँ, फिर बर्फ के पानी में ठंडा करके रोल करने से पहले सुखाएँ। हथेली के आकार की युवा, नरम पत्तियाँ चुनें — पुरानी, बड़ी पत्तियाँ लंबे समय तक पकाने के बाद भी सख्त रहती हैं।"],["क्या मैं डोलमा पहले से बना सकती हूँ?","हाँ, डोलमा अगले दिन और भी स्वादिष्ट लगता है, जब स्वाद जम जाते हैं। एक दिन पहले बनाएँ, अपने पकाने वाले तरल में ठंडा करें, बंद डिब्बे में फ्रिज में रखें और 3 से 4 दिन में खाएँ। थोड़े शोरबे के साथ धीरे से गरम करें।"],["पकाते समय मेरा डोलमा क्यों खुल गया?","रोल शायद बहुत ढीले जमाए गए थे, बहुत ढीले रोल किए गए थे, या बिना प्लेट के पकाए गए थे। हर पत्ती को कसकर रोल करें, रोल को बिना खाली जगह के परतों में कसकर जमाएँ, ऊपर गरम-सहनशील प्लेट से दबाएँ, और आंच धीमी रखें।"],["क्या मैं डोलमा फ्रीज़ कर सकती हूँ?","हाँ। पके हुए डोलमा को पूरी तरह ठंडा करें, थोड़े पकाने वाले तरल के साथ बंद डिब्बे में रखें, और 3 महीने तक फ्रीज़ करें। रात भर फ्रिज में पिघलाएँ और थोड़े शोरबे या पानी के साथ ढके हुए बर्तन में धीरे से गरम करें।"]]},"plov":{"intro":"प्लोव अज़रबैजान की राष्ट्रीय डिश है — केसर से सुनहरे बासमती चावल, नरम मेमने का मांस, चेस्टनट और सूखे मेवों की परतें, एक ही बर्तन में धीमी आंच पर तब तक भाप में पकाए जाते हैं जब तक दाने अलग-अलग और फूले हुए न हो जाएं। चावल और मेमने-मेवों की भराई अलग-अलग पकाई जाती है, फिर परत दर परत जमाकर साथ में भाप में पकाई जाती है, और डिश बड़ी थाली में अचार, सलाद या ताज़ी जड़ी-बूटियों के साथ परोसी जाती है। यह अज़रबैजान में शादियों, नवरोज़ और हर जश्न का केंद्र है, जहाँ टोस्टमास्टर पिलाफ की घोषणा करता है और उसे संगीत के साथ मेज़ तक लाया जाता है।","ing":["बासमती चावल 3 कप","धोकर नमकीन पानी में 30 मिनट भिगोया हुआ","मेमने का मांस 700 ग्राम","हड्डी रहित (टुकड़ों में कटा हुआ)","चेस्टनट 1 कप","छिले हुए","सूखी खुबानी 1/2 कप","गुठली निकाली हुई","सूखे खट्टे आलूबुखारे 1 कप","गुठली निकाले हुए","गुठली निकाली हुई खजूर 1/2 कप","सुनहरी किशमिश 1/2 कप","मक्खन 4 बड़े चम्मच","प्याज़ 1 मध्यम","आधे गोल टुकड़ों में कटा हुआ","केसर 1/3 छोटा चम्मच पिसे हुए रेशे","3 बड़े चम्मच गरम पानी में घोला हुआ (नमक 1 बड़ा चम्मच भिगोने के लिए + 2 बड़े चम्मच उबालने के लिए + 1/2 छोटा चम्मच मसाले के लिए)","पिसी हुई काली मिर्च स्वादानुसार"],"steps":["3 कप बासमती चावल तब तक धोएं जब तक पानी साफ न हो जाए, फिर 1 बड़ा चम्मच नमक वाले गुनगुने पानी में 30 मिनट भिगोएं।","कड़ाही में 2 बड़े चम्मच मक्खन गरम करें; 1 कप छिले हुए चेस्टनट 3 मिनट तलें, 1/2 कप सूखी खुबानी, 1 कप खट्टे आलूबुखारे और 1/2 कप खजूर डालकर 3 मिनट और तलें, फिर 1/2 कप सुनहरी किशमिश डालकर 1 मिनट तलें। आंच से उतार लें।","2 बड़े चम्मच नमक के साथ 10 कप पानी उबालें; छाना हुआ चावल थोड़ा-थोड़ा करके डालें और 7-10 मिनट उबालें जब तक दाने ऊपर न आ जाएं और बस पकने ही वाले हों; छान लें।","बर्तन में 1 बड़ा चम्मच मक्खन पिघलाएं; 700 ग्राम मेमने का मांस तले में एक परत में फैलाएं, 1/2 छोटा चम्मच नमक और काली मिर्च डालें; ऊपर 1 कटा हुआ प्याज़ फैलाएं; बिना ढके, बिना हिलाए 3 मिनट धीमी आंच पर पकाएं। (अगर मेमने का मांस इस्तेमाल कर रहे हैं, तो पहले उसे 5 मिनट उबालें, झाग उतारें और छान लें।)","प्याज़ के ऊपर आधा चावल फैलाएं, ऊपर सूखे मेवे और चेस्टनट सजाएं, फिर बाकी चावल को पिरामिड की तरह ढेर करें; ऊपर 1 बड़ा चम्मच पिघला हुआ मक्खन डालें।","भाप रोकने के लिए बर्तन को साफ तौलिए और ढक्कन से ढकें; धीमी आंच पर 30 मिनट पकाएं।","ढक्कन खोलें और 3 बड़े चम्मच गरम पानी में घोला हुआ 1/3 छोटा चम्मच केसर चावल पर छिड़कें; फिर से ढकें और 30 मिनट और धीमी आंच पर पकाएं जब तक चावल फूला हुआ और अलग-अलग न हो जाए और मांस सुनहरा न हो जाए।","बड़ी थाली में परोसें, चावल, मेवे और मेमने का मांस साथ-साथ निकालें, अचार, सलाद या ताज़ी जड़ी-बूटियों के साथ।"],"tip":"उबालने वाले चरण में चावल ज़्यादा न पकाएं — छानते समय वह बस पका ही होना चाहिए, क्योंकि वह बर्तन में भाप में पूरा पकता है। ढक्कन के नीचे रखा तौलिया भाप सोख लेता है, जिससे दाने चिपचिपे होने के बजाय अलग-अलग और फूले हुए रहते हैं।","notes":["चावल को पूरे 30 मिनट भिगोएं और उसे तब तक ही उबालें जब तक दाने ऊपर न आ जाएं और बस पकने ही वाले हों। उबलते पानी में पूरी तरह पका हुआ चावल लंबी भाप में गूदा बन जाता है।","असली केसर के रेशे इस्तेमाल करें, उन्हें पीसकर गरम पानी में घोलें। हल्दी सुनहरा रंग तो देती है, पर केसर की खुशबू नहीं, और केसर के बिना प्लोव, प्लोव नहीं होता।","चेस्टनट को बर्तन से निकालते ही गरम-गरम छीलें — तब छिलके आसानी से उतर जाते हैं, और ठंडे होने पर वे जिद्दी हो जाते हैं। ताज़े चेस्टनट न मिलें तो छिले हुए फ्रोज़न चेस्टनट भी अच्छे चलते हैं।","भाप के पूरे समय ढक्कन के नीचे तौलिया रखें और आंच धीमी रखें। तौलिया भाप सोख लेता है ताकि वह चावल पर वापस न टपके, और धीमी आंच से मेमने का मांस तले को जलाए बिना पक जाता है।"],"variations":["शाह प्लोव: बर्तन को लवाश ब्रेड से लाइन करें, उसमें चावल और मेमने-मेवों की भराई की परतें जमाएं, ऊपर से लवाश मोड़कर ढकें और कुरकुरा होने तक बेक करें। लवाश सुनहरा, कुरकुरा ताज बन जाता है जिसे मेज़ पर काटकर खोला जाता है।","तोयुक प्लोव (चिकन प्लोव): मेमने के मांस की जगह उतने ही वज़न के चिकन के टुकड़े लें। चिकन को पहले उबालने की ज़रूरत नहीं — उसे बर्तन में उसी तरह परतों में जमाएं और हमेशा की तरह भाप में पकाएं।","क़ाज़माक़ क्रस्ट: परतें जमाने से पहले, मक्खन लगे बर्तन के तले पर आटे की पतली परत या लवाश का एक गोल फैलाएं। वह सुनहरी कुरकुरी परत बन जाती है जो चावल के साथ टुकड़ों में परोसी जाती है — यह क्लासिक जश्न वाला स्पर्श है।"],"serving":"प्लोव को बड़ी थाली में परोसें, सुनहरे चावल को ऊंचा ढेर करें और ऊपर मेमने का मांस, चेस्टनट और सूखे मेवे डालें। बगल में अचार, साधारण सलाद और ताज़ी जड़ी-बूटियाँ मेज़ पर रखें, और सबको अपने आप लेने दें। किसी जश्न में प्लोव ही केंद्र होता है, इसलिए उसे सबसे आखिर में मेज़ पर लाएं और इसका एक पल बनाएं।","storage":"बचा हुआ प्लोव बंद डिब्बे में फ्रिज में रखें और 3 दिन में खाएं। थोड़ा पानी छिड़ककर ढके हुए बर्तन में धीमी आंच पर, या माइक्रोवेव में, भाप निकलने तक धीरे से गरम करें। प्लोव को फ्रीज़ न करें — चावल सूख जाते हैं और सूखे मेवे चमड़े जैसे हो जाते हैं।","mistakes":["चावल को पूरी तरह उबालना। छानते समय वह बस पका ही होना चाहिए, क्योंकि वह भाप में एक घंटा और पकता है — पूरी तरह पका चावल गूदा बन जाता है।","प्लोव के भाप में पकते समय परतों को हिलाना। हिलाने से चावल के दाने टूट जाते हैं और मेमने की चर्बी चावल में फैल जाती है; परोसने तक परतों को बिना छेड़े रहने दें।","ढक्कन के नीचे तौलिया न रखना। इसके बिना ढक्कन पर भाप जमकर चावल पर वापस टपकती है, जिससे ऊपरी परत गीली और चिपचिपी हो जाती है।","किशमिश को एक मिनट से ज़्यादा तलना। गरम मक्खन में किशमिश जल्दी जल जाती है और सख्त व कड़वी हो जाती है — उसे सबसे आखिर में डालें, सिर्फ एक मिनट तलें और कड़ाही आंच से उतार लें।"],"faq":[["क्या मैं प्लोव पहले से बना सकता हूँ?","हाँ। प्लोव को पूरी तरह पकाएं, ठंडा करें और बंद डिब्बे में फ्रिज में 3 दिन तक रखें। थोड़ा पानी छिड़ककर ढके हुए बर्तन में धीमी आंच पर भाप निकलने तक धीरे से गरम करें। सबसे फूले हुए चावल के लिए उसी दिन बनाएं, पर यह दोबारा गरम करने पर भी अच्छा रहता है।"],["क्या मैं मेमने के मांस की जगह चिकन इस्तेमाल कर सकता हूँ?","हाँ — यह तोयुक प्लोव है, जो अज़रबैजान में सबसे आम संस्करणों में से एक है। उतने ही वज़न के चिकन के टुकड़े लें और 5 मिनट पहले उबालने वाला चरण छोड़ दें, क्योंकि चिकन मेमने से तेज़ पकता है। परतें जमाएं और बिल्कुल उसी तरह भाप में पकाएं।"],["सूखे खट्टे आलूबुखारे क्या हैं, और इनकी जगह क्या इस्तेमाल कर सकता हूँ?","सूखे खट्टे आलूबुखारे खट्टे सूखे आलूबुखारे (आलू बुखारा) हैं, जो अज़रबैजानी प्लोव में क्लासिक खट्टा स्वाद देते हैं। अगर ये न मिलें तो उतनी ही मात्रा में सूखी क्रैनबेरी लें, या नींबू के रस की कुछ बूंदों के साथ अतिरिक्त प्रून्स लें।"],["मेरा प्लोव चावल फूला हुआ होने के बजाय चिपचिपा क्यों है?","चिपचिपा चावल आमतौर पर इसलिए होता है क्योंकि चावल उबालने वाले चरण में ज़्यादा पक गया, ढक्कन के नीचे तौलिया नहीं था, या भाप में पकते समय परतों को हिलाया गया। चावल को बस पकने पर छानें, ढक्कन के नीचे तौलिया रखें, और परोसने तक न हिलाएं।"]]},"machboos":{"intro":"मचबूस बहरीन का राष्ट्रीय व्यंजन है — नरम चिकन बहारत, सूखे काले नींबू, टमाटर, लहसुन और अदरक के सुगंधित शोरबे में धीमी आंच पर पकाया जाता है, फिर उसी शोरबे में पके सुनहरे बासमती चावल पर परोसा जाता है और ऊपर से गुलाब जल, नींबू का रस और मक्खन डाला जाता है। यह बहरीन का जुमे का पारिवारिक दावत है, बड़ी थाली में परोसा जाता है जिस पर ग्रिल्ड चिकन रखा जाता है और तली हुई प्याज़, किशमिश और मेवे बिखेरे जाते हैं। इस व्यंजन में समय लगता है — चिकन के लिए लगभग एक घंटे की धीमी पकाई और चावल के लिए धीमी आखिरी भाप — लेकिन ज़्यादातर समय इसमें हाथ नहीं लगाना पड़ता, और नतीजा एक ही बर्तन में पूरा खाना होता है: मसालेदार, खट्टा, सुगंधित और भरपूर।","ing":["चिकन 1 से 1.5 किलो","आधा कटा हुआ","बासमती चावल 650 ग्राम","धोकर 10 मिनट भिगोया हुआ","पानी 4.5 कप","टमाटर 3","चार टुकड़ों में कटे हुए","प्याज़ 3","बारीक कटी हुई","धनिया पत्ते 1/4 कप (कटे हुए)","हरी मिर्च 1","काले सूखे नींबू 2","छेद किए हुए","बहारत मसाला मिश्रण 2 छोटे चम्मच","हल्दी पाउडर 1.5 छोटे चम्मच","जीरा पाउडर 1 छोटा चम्मच","दालचीनी 2 छोटे चम्मच","इलायची पाउडर 1 छोटा चम्मच","लहसुन 2 कलियाँ","अदरक 1 टुकड़ा","छोटे टुकड़ों में कटा हुआ","मक्खन 3 बड़े चम्मच","नींबू का रस 1/4 कप","गुलाब जल 3 बड़े चम्मच","तेल 3 बड़े चम्मच","नमक 3 छोटे चम्मच"],"steps":["बहारत, हल्दी, जीरा और इलायची को 1 छोटे चम्मच नमक के साथ मिलाएं, और आधा मसाला चिकन के टुकड़ों पर छिड़कें।","एक बड़े बर्तन में तेल गरम करें और प्याज़ को सुनहरा भूरा होने तक तलें, फिर हरी मिर्च और छेद किए हुए सूखे नींबू डालें।","चिकन डालें, उसे मसालों और दालचीनी में लपेटें, ढककर 3 मिनट पकाएं, फिर लहसुन, अदरक और टमाटर डालकर 3 मिनट और पकाएं।","बचा हुआ नमक छिड़कें, गरम पानी डालें, ढककर लगभग 1 घंटे तक धीमी आंच पर पकाएं जब तक चिकन पूरी तरह पक न जाए।","चिकन निकालें, उस पर तेल लगाएं, बची हुई दालचीनी छिड़कें और ओवन में 10 से 15 मिनट तक ग्रिल करें जब तक सुनहरा भूरा न हो जाए।","छाना हुआ चावल बर्तन में चिकन के शोरबे में डालें और धीमी आंच पर 20 से 25 मिनट तक पकाएं जब तक वह शोरबा सोख न ले।","चावल पर गुलाब जल और नींबू का रस छिड़कें, ऊपर मक्खन के टुकड़े रखें, ढककर धीमी आंच पर 30 मिनट तक पकाएं।","चावल को बड़ी परोसने वाली प्लेट में निकालें और ऊपर ग्रिल्ड चिकन के टुकड़े रखें, ऊपर से अतिरिक्त धनिया और नींबू की फाँक से सजाएं।"],"tip":"प्रत्येक सूखे नींबू को बर्तन में डालने से पहले छेद करें, वरना उसका खट्टा स्वाद अंदर ही बंद रहता है। भाप में पकाने के आखिरी 30 मिनट में आंच बहुत धीमी रखें ताकि चावल फूला हुआ बने और कभी चिपके नहीं।","notes":["प्रत्येक सूखे नींबू (लूमी) को बर्तन में डालने से पहले छेद करें। बिना छेद वाला नींबू अपना खट्टा, धुएँ जैसा स्वाद अंदर ही रखता है, और शोरबा फीका रहता है।","पुराना बासमती चावल इस्तेमाल करें और 10 मिनट भिगोकर अच्छी तरह छान लें। पुराना चावल भाप के बाद लंबा और अलग-अलग रहता है; नया चावल नरम होकर चिपक जाता है।","मूल रेसिपी में चिकन 1 से 1.5 किलो है — पूरा चिकन आधा कटा हुआ, या 6 टुकड़ों में। हड्डी वाला चिकन ज़्यादा समृद्ध शोरबा बनाता है, इसलिए यहाँ बिना हड्डी वाला चिकन इस्तेमाल न करें।","गुलाब जल और नींबू का रस सिर्फ अंत में, तैयार चावल पर डालें। शोरबे के साथ उबालने पर वह खुशबू उड़ जाती है जिससे मचबूस की पहचान होती है।"],"variations":["मटन मचबूस: चिकन की जगह 1 से 1.5 किलो हड्डी वाला मटन लें और नरम होने तक 1.5 से 2 घंटे धीमी आंच पर पकाएं, फिर ग्रिल करके उसी तरह परोसें। मटन ईद का क्लासिक मचबूस है।","मछली मचबूस: चिकन की जगह 1 किलो सख्त सफेद मछली या बड़े झींगे लें, मछली को मसालेदार शोरबे में सिर्फ 10 से 15 मिनट पकाएं, फिर चावल पकाने से पहले निकाल लें। यह बहरीन का तटीय संस्करण है।","सब्ज़ी मचबूस: चिकन छोड़ दें, चावल को सब्ज़ी के शोरबे में 1 अतिरिक्त टमाटर और 1 अतिरिक्त प्याज़ के साथ पकाएं, और ऊपर तली हुई प्याज़, किशमिश और भुने हुए मेवे डालें। साथ में दही परोसें।"],"serving":"चावल को बड़ी थाली में ऊँचा लगाकर ऊपर ग्रिल्ड चिकन के टुकड़े रखें, ऊपर से अतिरिक्त धनिया, तली हुई प्याज़, किशमिश और भुने हुए मेवे छिड़कें, और साथ में नींबू की फाँकें रखें। मचबूस जुमे का पारिवारिक खाना है, इसलिए इसे बीच में रखकर सब मिलकर खाते हैं, साथ में टमाटर-खीरे का सलाद और दही का कटोरा या दक़ूस, खाड़ी की टमाटर-मिर्च वाली चटनी, परोसी जाती है। एक थाली 6 लोगों के लिए भरपूर है।","storage":"बचा हुआ मचबूस बंद डिब्बे में फ्रिज में रखें और 2 से 3 दिन में खाएं। ढके हुए बर्तन में धीमी आंच पर थोड़ा पानी डालकर धीरे से गरम करें, या माइक्रोवेव में भाप निकलने तक गरम करें। चावल और चिकन को अलग-अलग 2 महीने तक फ्रीज़ किया जा सकता है; गरम करने से पहले रात भर फ्रिज में पिघलाएं। एक से ज़्यादा बार गरम न करें।","mistakes":["सूखे नींबू में छेद न करना। बिना छेद वाले लूमी से शोरबे में स्वाद नहीं आता, और पकवान में वह खट्टापन नहीं आता जो मचबूस की पहचान है।","आखिरी 30 मिनट की भाप के दौरान चावल चलाना या ढक्कन उठाना। चावल को समान रूप से पकने के लिए स्थिर, बंद भाप चाहिए — चलाने से दाने टूटकर गूदेदार हो जाते हैं।","चावल डालने के बाद तेज़ आंच पर पकाना। नीचे का हिस्सा जल जाता है जबकि ऊपर कच्चा रहता है; चावल डालते ही आंच बहुत धीमी कर दें।","ग्रिल करने का चरण छोड़कर चिकन को सीधे बर्तन से परोसना। ग्रिल के नीचे 10 से 15 मिनट चिकन को सुनहरी त्वचा देते हैं और पकवान को पूरा करते हैं।"],"faq":[["क्या मैं चिकन की जगह मटन या मछली से मचबूस बना सकती हूँ?","हाँ। हड्डी वाला मटन क्लासिक विकल्प है — नरम होने तक 1.5 से 2 घंटे धीमी आंच पर पकाएं, फिर ग्रिल करके उसी तरह परोसें। मछली के लिए सख्त सफेद मछली या बड़े झींगे लें और सिर्फ 10 से 15 मिनट पकाएं, फिर चावल पकाने से पहले मछली निकाल लें ताकि वह टूटे नहीं।"],["बहारत क्या है, और इसकी जगह क्या इस्तेमाल कर सकती हूँ?","बहारत खाड़ी का गरम मसाला मिश्रण है जो मचबूस की जान है — आमतौर पर काली मिर्च, जीरा, धनिया, दालचीनी, इलायची, लौंग और जायफल। अगर तैयार मिश्रण न मिले तो 1-1 छोटा चम्मच काली मिर्च, जीरा, धनिया और दालचीनी में ½-½ छोटा चम्मच इलायची और लौंग मिलाएं; नतीजा बाज़ार के मिश्रण के करीब होगा।"],["मेरा चावल गूदेदार या चिपचिपा क्यों है?","गूदेदार चावल का मतलब आमतौर पर ज़्यादा पानी, बिना भिगोया और बिना छाना चावल, या आखिरी भाप के दौरान चलाना है। चावल को 10 मिनट भिगोएं, अच्छी तरह छानें, मापे हुए 4.5 कप शोरबे में बहुत धीमी आंच पर पकाएं, और आखिरी 30 मिनट में ढक्कन न उठाएं और न चलाएं।"],["क्या मैं मचबूस पहले से बना सकती हूँ?","हाँ। चिकन को शोरबे में एक दिन पहले पकाकर फ्रिज में रखें, फिर परोसने से ठीक पहले शोरबा गरम करें, उसमें चावल पकाएं और चिकन ग्रिल करें। बचा हुआ मचबूस फ्रिज में 2 से 3 दिन रहता है और थोड़ा पानी डालकर गरम करने पर अच्छा रहता है।"]]},"ilish-bhapa":{"intro":"इलिश भापा बांग्लादेश की प्रिय भाप में पकी हिलसा है — हिलसा, बांग्लादेश की राष्ट्रीय मछली, तीखी सरसों, दही और नारियल के पेस्ट में हरी मिर्च और सरसों के तेल के साथ भाप में पकाई जाती है। कच्ची मछली को कभी तला नहीं जाता; वह बंद टिफिन बॉक्स के अंदर अपनी ही भाप में धीरे-धीरे पकती है, नरम, रसीली और मुलायम रहती है, जबकि सरसों का पेस्ट सुनहरा और खुशबूदार हो जाता है। यह वह व्यंजन है जो बंगाली सम्मानित मेहमानों को परोसते हैं, बॉक्स मेज़ पर खोला जाता है ताकि भाप उठती मछली दिखे, और इसे हमेशा सादे भाप वाले चावल के साथ गरम खाया जाता है। सरसों के बीजों को पकाने से पहले दो घंटे भिगोना होता है, इसलिए पहले से योजना बनाएं — असली पकाने में सिर्फ लगभग 40 मिनट लगते हैं।","ing":["हिलसा मछली (इलिश माछ) 250 ग्राम","3 सेमी मोटे 4 टुकड़े","सरसों के बीज 40 ग्राम","भूरे","पीले मिले हुए","2 घंटे भिगोए हुए","हरी मिर्च 8 नग","नारियल 40 ग्राम","छिला","कसा हुआ","दही 25 ग्राम","फेंटी हुई","नमक 22 ग्राम (बॉन्ग ईट्स; अन्य रेसिपियों में लगभग 1 छोटा चम्मच)","चीनी 1/4 छोटा चम्मच","हल्दी पाउडर 1/2 छोटा चम्मच","सरसों का तेल 20 ग्राम"],"steps":["हिलसा को साफ करें और 3 सेमी मोटी स्लाइस में काटें, 250 ग्राम मछली से लगभग 4 टुकड़े।","40 ग्राम सरसों के बीजों को 2 घंटे पानी में भिगोएं। छानें, फिर नमक और 4 हरी मिर्च के साथ चिकना पेस्ट बनने तक पीसें, हल्के से चलाएं ताकि सरसों कड़वी न हो।","कसा हुआ नारियल, फेंटी हुई दही, 1/4 छोटा चम्मच चीनी, 1/2 छोटा चम्मच हल्दी और 20 ग्राम सरसों का तेल मिलाकर गाढ़ा सुनहरा पेस्ट बनाएं।","मछली के टुकड़ों पर पेस्ट को सभी तरफ अच्छी तरह लगाएं।","लेप लगी मछली को टिफिन बॉक्स में सजाएं, बाकी 4 हरी मिर्च आधी करके ऊपर रखें।","ढक्कन कसकर बंद करें और मछली को कम से कम 15 मिनट मैरिनेट होने के लिए अलग रखें।","कड़ाही में एक स्टैंड रखें, टिफिन बॉक्स की आधी ऊंचाई तक गरम पानी डालें, और पानी उबलने पर टिफिन को स्टैंड पर रखें। कड़ाही को ढकें और मध्यम आंच पर 15 मिनट भाप में पकाएं।","टिफिन को कड़ाही से निकालें और भाप वाले चावल के साथ गरम परोसने से पहले 5 मिनट और आराम करने दें।"],"tip":"सरसों के बीजों को सिर्फ हल्के से पीसें — ज़्यादा पीसने से सरसों कड़वी हो जाती है। दो या तीन बार चलाएं, किनारों को खुरचते हुए, जब तक बिल्कुल चिकना न हो जाए। और इस व्यंजन के लिए मछली को कभी तलें नहीं: पेस्ट में भाप में पकी कच्ची हिलसा नरम, रसीली और मुलायम बनती है।","notes":["सरसों के बीजों को पूरे 2 घंटे भिगोएं। अच्छी तरह भिगोए बीज चिकना पेस्ट बनाते हैं; सूखे बीज दानेदार रहते हैं और पेस्ट तीखा हो जाता है।","बॉन्ग ईट्स रेसिपी की तरह भूरे और पीले सरसों के बीज मिलाकर इस्तेमाल करें। भूरे बीज तीखापन देते हैं, पीले बीज उसे हल्का रखते हैं — सिर्फ भूरे सरसों से स्वाद बहुत कड़वा हो सकता है।","सरसों को सिर्फ हल्के से पीसें। दो या तीन बार चलाएं, किनारों को खुरचते हुए, जब तक बिल्कुल चिकना न हो जाए — ज़्यादा पीसना ही भापा के कड़वा होने का मुख्य कारण है।","इस व्यंजन के लिए मछली को कभी तलें नहीं। पेस्ट में भाप में पकी कच्ची हिलसा नरम, रसीली और मुलायम बनती है, जबकि तली हुई मछली सूख जाती है और सरसों का स्वाद फीका पड़ जाता है।"],"variations":["केले के पत्ते वाला भापा: टिफिन बॉक्स की जगह लेप लगी मछली को केले के पत्तों में लपेटें और 30 मिनट भाप में पकाएं, पारंपरिक ओह! कलकत्ता तरीके से — पत्ता हल्की खुशबू देता है।","खसखस वाला भापा: देबजानी के तरीके से ज़्यादा समृद्ध, मेवेदार पेस्ट के लिए सरसों के साथ 1.5 बड़े चम्मच खसखस पीसें।","बिना नारियल वाला भापा: नारियल छोड़ दें और उसकी जगह थोड़ी और दही डालें, ताकि स्वाद ज़्यादा तीखा और पूरी तरह सरसों वाला हो।"],"serving":"टिफिन बॉक्स से सीधे गरम परोसें, ढक्कन मेज़ पर ही खोलें ताकि खुशबूदार भाप सबके सामने निकले। हर व्यक्ति को सुनहरे सरसों के पेस्ट के साथ मछली का एक टुकड़ा दें, और हमेशा सादे भाप वाले चावल के साथ परोसें — चावल तीखा, तेल वाला पेस्ट सोख लेते हैं और उसकी गर्मी को संतुलित करते हैं। साथ में नींबू का टुकड़ा वैकल्पिक है, और कुछ और नहीं चाहिए।","storage":"बची हुई मछली को बंद टिफिन बॉक्स में फ्रिज में रखें और 1 से 2 दिन में खाएं। उबलते पानी पर बंद बॉक्स को लगभग 5 मिनट भाप में रखकर धीरे से गरम करें जब तक पूरी तरह गरम न हो जाए; तेज़ आंच पर माइक्रोवेव में गरम न करें या मछली को दोबारा न तलें, वरना वह सूख जाएगी। इलिश भापा को फ्रीज़ न करें — मछली सूख जाती है और सरसों के पेस्ट की ताज़ा तीखी खुशबू खत्म हो जाती है।","mistakes":["सरसों को ज़्यादा देर पीसना। ज़्यादा पीसी सरसों कड़वी हो जाती है और पूरा व्यंजन खराब कर देती है — हल्के से चलाएं, दो या तीन बार, जब तक बिल्कुल चिकना न हो जाए।","मछली को पहले तलना। भापा का मतलब है भाप में पका: तली हुई हिलसा सूख जाती है और इस व्यंजन की मशहूर नाज़ुक, रसीली बनावट खो जाती है।","2 घंटे भिगोना छोड़ देना। बिना भिगोए सरसों के बीज दानेदार, तीखा पेस्ट बनाते हैं, चिकना सुनहरा पेस्ट नहीं।","ज़्यादा देर भाप में पकाना या ढक्कन ढीला रखना। मध्यम आंच पर 15 मिनट से ज़्यादा पकाने से हिलसा टूटने लगती है, और ढक्कन कसकर बंद न हो तो भाप — और स्वाद — निकल जाता है।"],"faq":[["रेसिपी में 22 ग्राम नमक लिखा है — क्या यह ज़्यादा है?","हाँ, यह थोड़ा ज़्यादा है। बॉन्ग ईट्स में 22 ग्राम लिखा है, लेकिन अन्य रेसिपियों में लगभग 1 छोटा चम्मच नमक इस्तेमाल होता है। अगर आप निश्चित नहीं हैं, तो 1 छोटे चम्मच से शुरू करें, मछली पर लगाने से पहले पेस्ट चखें, और ज़रूरत हो तभी और डालें।"],["मेरा सरसों का पेस्ट कड़वा क्यों हो गया?","सरसों को ज़्यादा देर पीसा गया, या बीज पर्याप्त देर तक नहीं भिगोए गए। बीजों को पूरे 2 घंटे भिगोएं और हल्के से पीसें — दो या तीन बार, किनारों को खुरचते हुए — जब तक बिल्कुल चिकना न हो जाए।"],["क्या इलिश भापा बनाने के लिए टिफिन बॉक्स ज़रूरी है?","कसकर बंद होने वाले ढक्कन वाला स्टील का टिफिन बॉक्स पारंपरिक बर्तन है, लेकिन कोई भी ढक्कन वाला स्टील का डिब्बा जो अच्छी तरह बंद हो, काम करेगा। पारंपरिक रूप से मछली को केले के पत्ते में लपेटकर भी भाप में पकाया जाता है, जिससे हल्की खुशबू मिलती है।"],["क्या मैं इलिश भापा पहले से बना सकती हूँ?","आप मछली पर पेस्ट लगाकर टिफिन बॉक्स में कुछ घंटे पहले मैरिनेट करके फ्रिज में रख सकती हैं, लेकिन मछली नरम रहे इसके लिए परोसने से ठीक पहले भाप में पकाएं। बचा हुआ खाना फ्रिज में 1 से 2 दिन रहता है; लगभग 5 मिनट धीरे से भाप में गरम करें।"]]},"ema-datshi":{"intro":"एमा दात्शी भूटान का राष्ट्रीय व्यंजन है — ज़ोंगखा में 'एमा' का मतलब मिर्च और 'दात्शी' का मतलब चीज़ है। भूटान में मिर्च को मसाला नहीं, सब्ज़ी माना जाता है: 220 ग्राम मिर्चों को प्याज़, टमाटर और लहसुन के साथ नरम होने तक पकाया जाता है, फिर आंच बंद करके कसा हुआ चीज़ मिलाया जाता है, जब तक वह पिघलकर मलाईदार सॉस न बन जाए जो हर मिर्च पर चढ़ जाए। यह तीखा, समृद्ध और बेहद सुकून देने वाला है, और भूटानी घरों में लगभग हर दिन खाया जाता है, उबले हुए लाल चावल के ऊपर गरम परोसा जाता है। इस रेसिपी में सिर्फ मुट्ठी भर सामग्री और एक कड़ाही चाहिए, लेकिन इसमें सावधानी का फल मिलता है: मिर्चें नरम होनी चाहिए, गली हुई नहीं, और चीज़ आंच से उतारकर पिघलानी चाहिए, वरना सॉस दानेदार हो जाती है।","ing":["जलापीनो मिर्चें 220 ग्राम","लंबाई में चार हिस्सों में कटी हुई","हरी मिर्चें 6 ग्राम","चीरी हुई (2 छोटी हरी मिर्चें)","प्याज़ 70 ग्राम","कटा हुआ","लहसुन 15 ग्राम","मोटा कटा हुआ (लगभग 3 कलियाँ)","टमाटर 50 ग्राम","कटा हुआ","चीज़ 75 ग्राम","कसा हुआ (दात्शी, या फेटा, मोज़रेला या फार्मर्स चीज़)","मक्खन 15 ग्राम","वनस्पति तेल 7 ग्राम","नमक 5 ग्राम","पानी 250 ग्राम (लगभग 1 कप)"],"steps":["मिर्चों के डंठल निकालकर उन्हें लंबाई में चार हिस्सों में काटें। 2 छोटी हरी मिर्चों को चीरें, प्याज़ काटें, लहसुन मोटा काटें, और टमाटर काटें।","इन सबको नमक, वनस्पति तेल और 250 ग्राम पानी के साथ एक कड़ाही में डालें।","कड़ाही को ढक्कन से ढककर मध्यम आंच पर 15 मिनट तक उबालें, जब तक मिर्चें नरम न हो जाएं।","आंच बंद करें और मक्खन और कसा हुआ चीज़ डालें। चीज़ डालने से पहले आंच बंद करने से वह फटता नहीं है।","हल्के से चलाते रहें जब तक चीज़ पिघलकर मलाईदार सॉस न बन जाए जो मिर्चों पर चढ़ जाए।","चखकर नमक जांचें और उसे ठीक करें — कितना नमक चाहिए, यह इस पर निर्भर करता है कि आपका चीज़ कितना नमकीन है।","स्टू पकते समय लाल चावल अलग से पकाएं, और उसे गरम रखें।","एमा दात्शी को उबले हुए लाल चावल के ऊपर गरम परोसें।"],"tip":"चीज़ डालने से पहले आंच बंद कर दें। सीधी आंच पर डाला गया चीज़ फट जाता है और दानेदार हो जाता है; आंच से उतरे गरम स्टू में मिलाने पर वह पिघलकर चिकनी, मलाईदार सॉस बन जाता है।","notes":["ताज़ी, सख्त मिर्चें इस्तेमाल करें। जलापीनो एक हल्का विकल्प है; भूटान की पारंपरिक मिर्चें ज़्यादा तीखी होती हैं, इसलिए अगर आप असली तीखापन चाहते हैं तो हरी मिर्चों की मात्रा बढ़ाएं।","चीज़ डालने से पहले आंच हमेशा बंद करें। उबलते स्टू में चीज़ डालने से वह फटकर दानेदार हो जाता है और सॉस खराब हो जाती है।","ऐसा चीज़ इस्तेमाल करें जो अच्छी तरह पिघले — दात्शी, फेटा या मोज़रेला। सख्त, पुराना चीज़ ठीक से नहीं पिघलता और सॉस चिकनी नहीं बनती।","नमक डालने से पहले चीज़ का नमक चख लें। फेटा जैसे चीज़ पहले से ही नमकीन होते हैं, इसलिए ज़रूरत से ज़्यादा नमक आसानी से पड़ जाता है।"],"variations":["केवा दात्शी: स्टू में आलू डालें — कटे हुए आलू मिर्चों के साथ ही पकाएं, जब तक नरम न हो जाएं।","शामू दात्शी: मिर्चों के साथ कटे हुए मशरूम डालें; वे चीज़ की सॉस में मिट्टी जैसी खुशबू जोड़ते हैं।","हल्का संस्करण: मिर्चों के बीज और अंदर की झिल्ली निकाल दें और हरी मिर्चें कम कर दें, या आधा हिस्सा शिमला मिर्च से बदल दें।"],"serving":"उबले हुए लाल चावल के ऊपर गरम परोसें, ताकि सॉस चावल में समा जाए। भूटान में यह लगभग हर दिन खाया जाता है, अक्सर उबले हुए चावल और साथ में कोई और सब्ज़ी या दाल के साथ। एक कटोरा ही काफी है — यह तीखा और समृद्ध होता है।","storage":"बची हुई एमा दात्शी को बंद डिब्बे में फ्रिज में रखें और 1 से 2 दिन में खाएं। धीमी आंच पर हल्के से गरम करें और थोड़ा पानी या दूध मिलाएं अगर सॉस गाढ़ी हो गई हो। इसे फ्रीज़ न करें — चीज़ की सॉस फट जाती है और बनावट खराब हो जाती है।","mistakes":["सीधी आंच पर चीज़ डालना। चीज़ फटकर दानेदार हो जाता है और सॉस कभी चिकनी नहीं बनती।","मिर्चों को ज़्यादा पकाना। ज़्यादा देर उबालने से मिर्चें गली हुई हो जाती हैं और अपना आकार खो देती हैं।","चीज़ चखे बिना पूरा नमक डाल देना। नमकीन चीज़ के साथ स्टू आसानी से ज़्यादा नमकीन हो जाता है।","बहुत कम चीज़ या बहुत ज़्यादा पानी डालना। सॉस पतली और पानी जैसी रह जाती है, मलाईदार नहीं बनती।"],"faq":[["क्या एमा दात्शी बहुत तीखी होती है?","हाँ — मिर्च ही इस व्यंजन की मुख्य सामग्री है, मसाला नहीं। तीखापन कम करने के लिए मिर्चों के बीज निकाल दें, जलापीनो इस्तेमाल करें, या चीज़ की मात्रा बढ़ा दें।"],["अगर दात्शी चीज़ न मिले तो कौन सा चीज़ इस्तेमाल करूँ?","फेटा, मोज़रेला या फार्मर्स चीज़ अच्छा काम करता है। ऐसा चीज़ चुनें जो आसानी से पिघले; सख्त पुराना चीज़ सॉस को चिकना नहीं बनाता।"],["एमा दात्शी के साथ क्या परोसा जाता है?","परंपरागत रूप से उबले हुए लाल चावल के साथ, जो भूटान का मुख्य अनाज है। सफेद चावल या टिंगमो (भाप में पका हुआ ब्रेड) भी चलता है।"],["क्या मैं इसे पहले से बना सकती हूँ?","यह ताज़ा ही सबसे अच्छी लगती है। बची हुई डिश को फ्रिज में रखें और 1 से 2 दिन में धीमी आंच पर हल्के से गरम करके खाएं; सॉस थोड़ी गाढ़ी हो सकती है, तो थोड़ा पानी मिलाएं।"]]},"ambuyat":{"intro":"अम्बुयात ब्रुनेई दारुस्सलाम का राष्ट्रीय व्यंजन है — सागो पाम का स्टार्च पानी के साथ मिलाकर उबलते पानी से तब तक हिलाया जाता है जब तक वह चमकदार, पारदर्शी, गोंद जैसा पदार्थ न बन जाए। अपने आप में इसका स्वाद लगभग नहीं होता, इसलिए इसे कंडास कहलाने वाली बांस की छड़ियों पर लपेटा जाता है और मिर्च, झींगा पेस्ट और नींबू की तीखी काकाह सॉस में डुबोया जाता है, और ग्रिल्ड झींगे, मछली और सब्जियों के साथ खाया जाता है। पारंपरिक रूप से इसे बिना चबाए निगला जाता है, और कम से कम तीन साइड डिश और डिप के बिना यह अधूरा है।","ing":["सागो स्टार्च 1 कप (या विकल्प के रूप में टैपिओका स्टार्च)","ठंडा पानी 1/2 कप","उबलता पानी 3 कप","ताज़ी लाल मिर्च 5-7 (काकाह के लिए)","बर्ड्स आई मिर्च 2-3 (वैकल्पिक, अतिरिक्त तीखापन के लिए)","बेलाकान (झींगा पेस्ट) 1 बड़ा चम्मच","भुना हुआ","नींबू का रस 2 बड़े चम्मच (1-2 नींबू से)","शैलट 1 छोटा","चीनी 1/2 छोटा चम्मच","नमक 1/4 छोटा चम्मच"],"steps":["एक गर्मी-रोधी कटोरे में 1 कप सागो स्टार्च डालें, 1/2 कप ठंडा पानी मिलाएं और चम्मच या स्पैटुला से अच्छी तरह हिलाएं जब तक एक चिकना, गांठ-रहित पेस्ट न बन जाए। बाद में गांठें रोकने के लिए यह कदम बहुत ज़रूरी है।","केतली या बर्तन में 3 कप पानी उबालकर तेज़ उबाल पर लाएं।","उबलता पानी सागो पेस्ट में पतली धार में धीरे-धीरे डालें और लगातार तेज़ी से हिलाते रहें। मिश्रण तुरंत गाढ़ा होने लगेगा और पारदर्शी हो जाएगा।","तब तक हिलाते रहें जब तक पूरा मिश्रण एक गाढ़े, चिपचिपे, जेली जैसे पदार्थ में न बदल जाए। यह ज़्यादातर साफ़ होना चाहिए, हल्की ओपल जैसी चमक के साथ।","पूरी तरह बदल जाने पर अम्बुयात को 1-2 मिनट बैठने दें। यह और भी सख्त हो जाएगा। एक साझा परोसने वाले कटोरे में डालें और गरम ही तुरंत परोसें।","अगर आपका बेलाकान पहले से भुना नहीं है, तो 1 बड़ा चम्मच बेलाकान को सूखी कड़ाही में धीमी आंच पर 1-2 मिनट तक हल्के से भूनें जब तक खुशबू न आने लगे। जलने न दें।","मिर्च और शैलट को मोटा-मोटा काटें। खल-बट्टे में, या छोटे फूड प्रोसेसर में, भुने हुए बेलाकान, मिर्च, शैलट, 1/2 छोटा चम्मच चीनी और 1/4 छोटा चम्मच नमक को तब तक कूटें जब तक मोटा पेस्ट न बन जाए।","2 बड़े चम्मच नींबू का रस मिलाएं, चखकर मसाला ठीक करें, और काकाह को छोटे परोसने वाले कटोरे में डालें। बांस की कंडास पर थोड़ा अम्बुयात लपेटें, काकाह में डुबोएं, और ग्रिल्ड झींगे, मछली और सब्जियों के साथ खाएं।"],"tip":"स्टार्च को पहले ठंडे पानी से चिकना पेस्ट बनाकर मिलाएं — यही वह कदम है जो गांठें रोकता है। उबलता पानी पतली धार में डालें और हिलाना कभी न रोकें, वरना स्टार्च चमकदार और चिकना बनने के बजाय गांठों में जम जाता है।","notes":["अम्बुयात अपने आप में लगभग बेस्वाद होता है — यह चावल या नूडल्स जैसा एक तटस्थ स्टार्च आधार है, और सारा स्वाद काकाह सॉस और साइड डिश से आता है।","लपेटने से पहले कंडास को थोड़े स्टार्च वाले पानी में डुबोएं, ताकि अम्बुयात छड़ियों पर चिपके और फिसले नहीं।","गरम रहते ही तुरंत परोसें। ठंडा होने पर अम्बुयात सख्त हो जाता है और अपनी चमकदार, खिंचने वाली बनावट खो देता है।","सागो स्टार्च की जगह टैपिओका या आलू का स्टार्च इस्तेमाल किया जा सकता है, लेकिन बनावट असली सागो स्टार्च से थोड़ी कम लचीली होती है।"],"variations":["टेम्पोयाक काकाह: 2 बड़े चम्मच किण्वित दुरियन (टेम्पोयाक) को 1 मिर्च, 1 छोटा चम्मच झींगा पेस्ट और 1 बड़ा चम्मच सूखे झींगे के साथ कूटें, फिर थोड़े गरम पानी से पतला करें।","इमली काकाह: 1 कप इमली का रस 2-3 बारीक कटी लहसुन की कलियों, 1-2 कटी मिर्च और एक चुटकी नमक के साथ तब तक उबालें जब तक थोड़ा गाढ़ा न हो जाए।","बिंजई काकाह: नींबू, प्याज़, लहसुन और बिंजई फल को कूटकर खट्टा, मसालेदार डिप बनाएं — ब्रुनेई की क्लासिक खट्टी काकाह।"],"serving":"गरम साझा कटोरे में परोसें, काकाह छोटे कटोरे में, और उसके आसपास ग्रिल्ड झींगे, तली हुई मछली, भाप में पकी सब्जियां और खीरे और गाजर की स्लाइस रखें। कंडास पर एक छोटी गेंद लपेटें, डुबोएं, और बिना चबाए निगलें — यही पारंपरिक तरीका है।","storage":"अम्बुयात ताज़ा और गरम ही सबसे अच्छा खाया जाता है। ठंडा होने पर यह सख्त और सूखा हो जाता है और ठीक से दोबारा गरम नहीं होता; उतना ही बनाएं जितना एक बार में खाएंगे। काकाह सॉस फ्रिज में एक दिन तक रखी जा सकती है।","mistakes":["ठंडे पानी का पेस्ट न बनाना। सूखे स्टार्च में सीधे उबलता पानी डालने से गांठें बन जाती हैं जो कभी चिकनी नहीं होतीं।","उबलता पानी बहुत तेज़ डालना या हिलाना रोक देना। स्टार्च जगह-जगह जम जाता है और अम्बुयात चमकदार होने के बजाय गांठदार हो जाता है।","इसे ठंडा परोसना। ठंडा अम्बुयात सख्त और बेजान होता है; पारदर्शी होते ही इसे गरम परोसना चाहिए।","इसे सादा खाना। काकाह और साइड डिश के बिना अम्बुयात लगभग बेस्वाद होता है — डिप ही असली व्यंजन है।"],"faq":[["अम्बुयात किससे बनता है?","अम्बुयात सागो स्टार्च से बनता है, सागो पाम के तने से निकाला गया सफ़ेद स्टार्च। स्टार्च को ठंडे पानी के साथ मिलाकर पेस्ट बनाया जाता है, फिर उबलता पानी हिलाते हुए डाला जाता है जब तक वह चमकदार, पारदर्शी, गोंद जैसा पदार्थ न बन जाए।"],["काकाह सॉस क्या है?","काकाह अम्बुयात के साथ परोसी जाने वाली डिपिंग सॉस है। क्लासिक संस्करण सांबल बेलाकान है — लाल मिर्च, बर्ड्स आई मिर्च, भुना हुआ झींगा पेस्ट, शैलट, चीनी, नमक और नींबू का रस कूटकर मोटा, तीखा पेस्ट बनाया जाता है। अन्य काकाह में इमली, टेम्पोयाक (किण्वित दुरियन) या बिंजई फल इस्तेमाल होता है।"],["अम्बुयात कैसे खाते हैं?","कंडास कहलाने वाली बांस की छड़ियों से: छड़ियों के चारों ओर थोड़ा अम्बुयात घुमाएं, काकाह सॉस में डुबोएं, और बिना चबाए निगल जाएं। इसे ग्रिल्ड झींगे, मछली, सब्जियों और अन्य साइड डिश के साथ खाया जाता है।"],["क्या मैं सागो स्टार्च की जगह टैपिओका स्टार्च इस्तेमाल कर सकती हूँ?","हाँ। टैपिओका या आलू का स्टार्च एक आम विकल्प है और उसी तरह काम करता है, हालांकि बनावट असली सागो स्टार्च से थोड़ी कम लचीली होती है।"]]},"fish-amok":{"intro":"फिश अमोक, या अमोक ट्रे, कंबोडिया का राष्ट्रीय व्यंजन है — सफ़ेद मछली को केले के पत्ते के कपों में सुगंधित नारियल करी में धीरे से भाप में पकाया जाता है, जो क्रोएंग पर बना होता है, खमेर मसाला पेस्ट जिसमें लेमनग्रास, गलंगल, हल्दी, लहसुन, शैलट और काफिर लाइम के पत्ते होते हैं। अंडे करी को नरम, कस्टर्ड जैसी जमावट देते हैं, और केले का पत्ता हल्की मिट्टी जैसी खुशबू जोड़ता है। इसे गरम परोसा जाता है, ऊपर काफिर लाइम के पत्ते और लाल मिर्च डालकर, भाप में पके चावल के साथ।","ing":["सफ़ेद मछली फ़िले 500 g (कैटफ़िश, तिलापिया या स्नैपर)","एक-एक निवाले के टुकड़ों में कटी हुई","नारियल का दूध 1 कप","नारियल की मलाई 1/2 कप","अंडे 2","फेंटे हुए","क्रोएंग पेस्ट 3 बड़े चम्मच (2 डंठल लेमनग्रास, 2 शैलट, 2 लहसुन की कलियाँ, 1 छोटा टुकड़ा गलंगल, 1 छोटा चम्मच ताज़ी हल्दी, 2 काफिर लाइम के पत्ते, 1 छोटा चम्मच झींगा पेस्ट)","फिश सॉस 1 1/2 बड़े चम्मच","ताड़ की चीनी 1 छोटा चम्मच","केले के पत्ते 2-3","चौकोर टुकड़ों में कटे हुए (या छोटी रैमेकिन)","लाल मिर्च 1 (पतली कटी हुई)","और काफिर लाइम के पत्ते (बारीक कटे हुए, सजाने के लिए)"],"steps":["लेमनग्रास, शैलट, लहसुन, गलंगल, हल्दी, काफिर लाइम के पत्ते और झींगा पेस्ट को खल-मूसल में या छोटे ब्लेंडर में थोड़ा पानी डालकर चिकना क्रोएंग पेस्ट बना लें।","एक बड़े कटोरे में नारियल का दूध, नारियल की मलाई, 3 बड़े चम्मच क्रोएंग पेस्ट, फिश सॉस, ताड़ की चीनी और फेंटे हुए अंडे पूरी तरह चिकने होने तक फेंटें।","500 g सफ़ेद मछली को एक-एक निवाले के टुकड़ों में काटें, नारियल के मिश्रण में मिलाएं और 15 मिनट तक मैरीनेट होने दें।","केले के पत्तों को आंच के ऊपर से जल्दी गुज़ारकर या गरम पानी में डुबोकर नरम करें, फिर उन्हें कपों की तरह मोड़ें और ज़रूरत हो तो कॉकटेल स्टिक से बांधें (या छोटी रैमेकिन इस्तेमाल करें)।","मछली का मिश्रण कपों में डालें, लगभग तीन-चौथाई तक भरें ताकि कस्टर्ड को जमने की जगह मिले।","कपों को उबलते पानी के ऊपर स्टीमर में रखें, ढकें और 20–25 मिनट तक भाप में पकाएं, जब तक करी जमकर कस्टर्ड जैसी न हो जाए।","हर कप के ऊपर थोड़ी नारियल की मलाई डालें और 2–3 मिनट और भाप में पकाएं।","बारीक कटे काफिर लाइम के पत्तों और लाल मिर्च से सजाएं, और भाप में पके चावल के साथ गरम परोसें।"],"tip":"केले के पत्ते के कपों को ज़्यादा न भरें — तीन-चौथाई भरने से मिश्रण को बिना छलके जमने की जगह मिलती है। अमोक तब तैयार है जब वह छूने पर सख्त लगे लेकिन फिर भी नम हो, नरम कस्टर्ड जैसा, कभी सूखा नहीं।","notes":["मज़बूत सफ़ेद मछली इस्तेमाल करें जो भाप में पकने पर अपना आकार बनाए रखे — कैटफ़िश, तिलापिया या स्नैपर क्लासिक चुनाव हैं। नरम, परतदार मछली टूट जाती है और अमोक टुकड़ों में जमने के बजाय दलिया जैसा हो जाता है।","अगर हो सके तो क्रोएंग ताज़ा बनाएं। लेमनग्रास, गलंगल, हल्दी, लहसुन, शैलट और काफिर लाइम के पत्तों का कूटा हुआ पेस्ट डिब्बाबंद करी पेस्ट से कहीं ज़्यादा चमकदार स्वाद देता है, और यही अमोक को थाई की बजाय खमेर स्वाद देता है।","अंडे न छोड़ें — यही करी को नरम कस्टर्ड में जमाते हैं। इनके बिना मिश्रण पतली सॉस ही रहता है और कप खोलने पर अपना आकार नहीं बनाए रखता।","नोनी के पत्ते केले के पत्ते के कपों के लिए पारंपरिक बिछावन हैं और हल्का कड़वा, जड़ी-बूटी जैसा स्वाद जोड़ते हैं; अगर वे न मिलें तो अकेला केले का पत्ता भी ठीक है, और ज़्यादातर घरों में यही तरीका अपनाया जाता है।"],"variations":["चिकन या झींगा अमोक: मछली की जगह उतने ही वज़न का कटा हुआ चिकन थाई या छिला हुआ झींगा लें और उतने ही समय तक भाप में पकाएं; झींगे को सिर्फ 15–18 मिनट चाहिए।","शाकाहारी अमोक: मछली की जगह 500 g मिश्रित मशरूम और टोफू लें, फिश सॉस की जगह सोया सॉस इस्तेमाल करें और झींगा पेस्ट छोड़ दें।","तीखा अमोक: क्रोएंग में 1 छोटा चम्मच मिर्च पेस्ट मिलाएं, या भाप में पकाने से पहले मिश्रण में कटी हुई बर्ड्स आई मिर्च डालें।"],"serving":"अमोक को गरम, केले के पत्ते के कप में ही परोसें, मेज़ पर खोलकर, भाप में पके चमेली चावल के कटोरे के साथ। ऊपर थोड़ी नारियल की मलाई डालें और कटे हुए काफिर लाइम के पत्ते और लाल मिर्च छिड़कें। प्रति व्यक्ति एक कप भरपूर मुख्य व्यंजन है; कंबोडिया में इसे अक्सर सूप और सलाद के साथ साझा भोजन के हिस्से के रूप में खाया जाता है।","storage":"बचा हुआ अमोक बंद डिब्बे में फ्रिज में रखें और 1 से 2 दिन में खाएं। 8–10 मिनट तक भाप में धीरे से गरम करके परोसें जब तक पूरी तरह गरम न हो जाए — माइक्रोवेव भी चलता है लेकिन किनारे सूख सकते हैं। अमोक को फ्रीज़ न करें; अंडे का कस्टर्ड रबड़ जैसा हो जाता है और पिघलने पर पानी छोड़ता है।","mistakes":["केले के पत्ते के कपों को ज़्यादा भरना। तीन-चौथाई से ज़्यादा भरने पर मिश्रण जमते समय छलक जाता है, या कप वज़न से फट जाता है।","बहुत तेज़ आंच पर या बहुत देर तक भाप में पकाना। कस्टर्ड नरम और नम रहने के बजाय रबड़ जैसा और सूखा हो जाता है — पानी को हल्की उबाल पर रखें और 20 मिनट पर जांचें।","क्रोएंग की जगह डिब्बाबंद करी पेस्ट इस्तेमाल करना। थाई करी पेस्ट कहीं ज़्यादा तीखे होते हैं और उनमें गलंगल और काफिर लाइम का वह संतुलन नहीं होता जो अमोक को कंबोडियाई स्वाद देता है।","मैरीनेट करने का चरण छोड़ देना। मछली को नारियल के मिश्रण में 15 मिनट रखे बिना सीधे कपों में डालने से मछली बीच से फीकी रह जाती है।"],"faq":[["फिश अमोक क्या है?","फिश अमोक, या अमोक ट्रे, कंबोडिया का राष्ट्रीय व्यंजन है: सफ़ेद मछली को केले के पत्ते के कपों में नारियल करी में भाप में पकाया जाता है, जो क्रोएंग से बनती है — लेमनग्रास, गलंगल, हल्दी, लहसुन, शैलट और काफिर लाइम के पत्तों का खमेर मसाला पेस्ट। फेंटे हुए अंडे करी को नरम, कस्टर्ड जैसी बनावट में जमा देते हैं।"],["क्या मैं केले के पत्तों के बिना फिश अमोक बना सकती हूँ?","हाँ। छोटी रैमेकिन, गरम सहने वाले कटोरे या फॉइल के कप भी उतने ही अच्छे चलते हैं — मिश्रण डालें, हल्के से फॉइल से ढकें और उसी तरह भाप में पकाएं। पत्ते की हल्की मिट्टी जैसी खुशबू नहीं मिलेगी, लेकिन स्वाद और बनावट वही रहेंगे।"],["फिश अमोक के लिए कौन सी मछली सबसे अच्छी है?","कैटफ़िश, तिलापिया या स्नैपर जैसी मज़बूत सफ़ेद मछली, एक-एक निवाले के टुकड़ों में कटी हुई। कैटफ़िश कंबोडिया में पारंपरिक चुनाव है। बहुत नरम या तेल वाली मछली से बचें, जो भाप में पकते समय टूट जाती है।"],["क्रोएंग क्या है, और क्या मैं इसे तैयार खरीद सकती हूँ?","क्रोएंग खमेर सुगंधित पेस्ट है जो कंबोडियाई खाना पकाने के केंद्र में है, लेमनग्रास, गलंगल, हल्दी, लहसुन, शैलट और काफिर लाइम के पत्तों को कूटकर बनाया जाता है, अक्सर झींगा पेस्ट के साथ। ताज़ा कूटा हुआ क्रोएंग कहीं ज़्यादा चमकदार स्वाद देता है; अगर आप इसे न बना सकें तो पीली करी पेस्ट सबसे नज़दीकी विकल्प है, लेकिन स्वाद ज़्यादा तीखा और कम खुशबूदार होगा।"]]},"souvla":{"intro":"सूवला साइप्रस का सबसे प्रसिद्ध व्यंजन है — पोर्क शोल्डर के बड़े टुकड़े रेड वाइन, जैतून के तेल, समुद्री नमक, काली मिर्च और ग्रीक ऑरेगैनो (रिगानी) में मैरीनेट करके, लंबी सीखों पर लगाकर फौकू ग्रिल पर सुलगते कोयलों पर धीरे-धीरे पकाए जाते हैं। सूवलाकी से अलग, जिसमें छोटे टुकड़े तेज़ आंच पर जल्दी पकाए जाते हैं, सूवला को पहले भूरा किया जाता है और फिर कोयलों से ऊपर उठाकर दो घंटे तक धीमी आंच पर पकाया जाता है, बीच-बीच में पलटते हुए, जब तक बाहर से कुरकुरा और सुनहरा और अंदर से रसदार और धुएँदार न हो जाए। यह साइप्रस के गाँवों की दावतों और पारिवारिक बारबेक्यू का मुख्य व्यंजन है, नींबू के टुकड़ों, गरम पीटा ब्रेड और सलाद के साथ परोसा जाता है, और सीख से सीधे खाया जाता है।","ing":["पोर्क शोल्डर 2.5 पाउंड (लगभग 1.1 किग्रा)","लगभग 2.5 सेमी के टुकड़ों में कटा हुआ","रेड वाइन 2 बड़े चम्मच (या अच्छी रेड वाइन सिरका)","जैतून का तेल 2 बड़े चम्मच","समुद्री नमक 1 बड़ा चम्मच","ग्रीक ऑरेगैनो (रिगानी) 1 छोटा चम्मच","पिसा हुआ","ताज़ी पिसी हुई काली मिर्च 0.5 छोटा चम्मच","नींबू 1 (टुकड़ों में कटा हुआ, परोसने के लिए)","पीटा ब्रेड 6 (परोसने के लिए)","ताहिनी डिप (वैकल्पिक, परोसने के लिए)"],"steps":["2.5 पाउंड पोर्क शोल्डर को लगभग 2.5 सेमी के टुकड़ों में काटें, टुकड़ों को जितना हो सके बराबर रखें ताकि वे एक साथ पकें।","पोर्क को एक बड़े कटोरे में डालें और ऊपर से 2 बड़े चम्मच रेड वाइन और 2 बड़े चम्मच जैतून का तेल डालें, अच्छी तरह मिलाएं ताकि हर टुकड़ा लिपट जाए।","ऊपर से 1 बड़ा चम्मच समुद्री नमक, 0.5 छोटा चम्मच ताज़ी पिसी काली मिर्च और 1 छोटा चम्मच पिसा हुआ ग्रीक ऑरेगैनो छिड़कें, फिर दोबारा मिलाएं जब तक मसाला बराबर न फैल जाए।","कटोरे को ढककर कम से कम 2 घंटे के लिए फ्रिज में रखें, आदर्श रूप से रात भर, ताकि वाइन, तेल और ऑरेगैनो मांस के अंदर तक पहुँच जाएं।","प्रत्येक लंबी सीख पर लगभग 6 टुकड़े लगाएं, टुकड़ों के बीच थोड़ी जगह छोड़ें, कुल लगभग 12 सीखें बनाएं।","सीखों को गरम चारकोल ग्रिल पर रखें और बार-बार पलटते हुए सभी तरफ से बराबर भूरा करें, लगभग 15 मिनट।","सीखों को कोयलों से ऊपर उठाएं और 90 मिनट से 2 घंटे तक धीरे-धीरे ग्रिल करें, बीच-बीच में पलटते हुए और जैतून के तेल और नींबू के रस से ब्रश करते हुए, जब तक बाहर से कुरकुरा और सुनहरा और अंदर से पूरी तरह पक न जाए।","पीटा ब्रेड को ग्रिल पर गरम करें, मांस को थोड़ी देर आराम दें, ऊपर से नींबू निचोड़ें और गरम पीटा, सलाद और चाहें तो ताहिनी के साथ परोसें।"],"tip":"सूवला को जल्दी न करें। पहले सीखों को रंग के लिए भूरा करें, फिर उन्हें कोयलों से ऊपर उठाएं और हल्की आंच को काम करने दें — वही धीमा दूसरा चरण मांस को अंदर से रसदार और बाहर से कुरकुरा बनाता है।","notes":["पोर्क शोल्डर ही इस्तेमाल करें, लीन लॉइन नहीं। शोल्डर की चर्बी धीरे-धीरे पकते समय मांस को नम रखती है; लीन टुकड़े दो घंटे ग्रिल पर सूख जाते हैं।","टुकड़े बड़े रखें — लगभग 2.5 सेमी, या इससे भी बड़े, 5 से 7 सेमी। छोटे टुकड़े बहुत जल्दी पक जाते हैं और सूख जाते हैं; सूवला की पहचान ही धीरे पकाए गए बड़े टुकड़े हैं।","कम से कम 2 घंटे मैरीनेट करें, लेकिन रात भर सबसे अच्छा है। रेड वाइन और ऑरेगैनो को मांस के अंदर तक स्वाद पहुँचाने के लिए समय चाहिए।","फौकू ग्रिल, साइप्रस में इस्तेमाल होने वाली लंबी चारकोल रोटिसरी, आदर्श है, लेकिन कोई भी चारकोल बारबेक्यू चलेगा। धुएँदार स्वाद के लिए असली चारकोल पर पकाएं, गैस पर नहीं।"],"variations":["चिकन सूवला: पोर्क की जगह हड्डी रहित चिकन थाई लें, बड़े टुकड़ों में काटें और उसी तरह मैरीनेट करें; 60 से 90 मिनट तक पकाएं, जब तक चिकन पूरी तरह पककर सुनहरा न हो जाए।","लैम्ब सूवला: लैम्ब शोल्डर के बड़े टुकड़े लें और उसी रेड वाइन, जैतून के तेल और ऑरेगैनो से मैरीनेट करें; लैम्ब सूवला साइप्रस का एक क्लासिक विकल्प है और लगभग उतने ही समय में पकता है।","लहसुन और नींबू वाली सूवला: मैरीनेड में 3 कुचली हुई लहसुन की कलियाँ और 1 नींबू का रस मिलाएं, और ग्रिल करते समय सीखों पर जैतून का तेल और नींबू का रस ब्रश करें, ताकि स्वाद और भी ताज़ा और तीखा हो।"],"serving":"सूवला को सीखों से सीधे परोसें, नींबू के टुकड़ों, गरम पीटा ब्रेड, टमाटर, खीरा और प्याज़ की गाँव वाली सलाद, और डिपिंग के लिए ताहिनी या त्ज़ात्ज़िकी के साथ। साइप्रस में यह दावत का व्यंजन है, परिवार के साथ बाहर खाया जाता है, और हर व्यक्ति 3 से 4 सीखें लेता है। इसके साथ एक गिलास रेड वाइन या ठंडी बीयर अच्छी लगती है।","storage":"बची हुई सूवला को बंद डिब्बे में फ्रिज में रखें और 2 दिन में खाएं। ग्रिल पर या गरम ओवन में हल्के से गरम करें जब तक अंदर तक गरम न हो जाए; ध्यान रखें कि ज़्यादा न पकाएं वरना सूख जाएगी। बचा हुआ पोर्क सलाद और ताहिनी के साथ पीटा में भरकर ठंडा भी अच्छा लगता है। अगर हो सके तो पकी हुई सूवला को फ्रीज़ न करें — उसकी बनावट सूख जाती है।","mistakes":["मांस को बहुत छोटा काटना। छोटे टुकड़े सूवलाकी की तरह पकते हैं और सूख जाते हैं; सूवला को लंबे धीमे पकने के लिए लगभग 2.5 सेमी या उससे बड़े टुकड़े चाहिए।","पूरे समय तेज़ आंच पर पकाना। पहले भूरा करना सही है, लेकिन अगर आप सीखों को कभी ऊपर नहीं उठाते तो बाहर जल जाता है और अंदर कच्चा रह जाता है; उन्हें ऊपर उठाएं और हल्की आंच को काम पूरा करने दें।","मैरीनेट का समय छोड़ देना। 2 घंटे से कम में वाइन और ऑरेगैनो मांस के बीच तक नहीं पहुँचते; रात भर सबसे अच्छा है।","सीखों को बार-बार पलटना भूल जाना। कोयलों की तरफ वाला हिस्सा जल्दी जल जाता है, इसलिए बराबर भूरा करने और हर तरफ रसदार मांस के लिए बार-बार पलटें।"],"faq":[["सूवला और सूवलाकी में क्या अंतर है?","सूवला में मांस के बड़े टुकड़े, लगभग 2.5 सेमी या उससे बड़े, इस्तेमाल होते हैं, जो चारकोल पर 1.5 से 2 घंटे तक धीरे-धीरे पकाए जाते हैं, जबकि सूवलाकी में छोटे टुकड़े तेज़ आंच पर जल्दी पकाए जाते हैं। सूवला को पहले भूरा किया जाता है, फिर कोयलों से ऊपर उठाकर धीरे-धीरे पूरा किया जाता है; सूवलाकी पूरे समय आंच के पास रहती है।"],["क्या मैं फौकू ग्रिल के बिना सूवला बना सकती हूँ?","हाँ। फौकू साइप्रस की पारंपरिक चारकोल रोटिसरी है, लेकिन कोई भी चारकोल बारबेक्यू चलेगा। ज़रूरी है असली चारकोल और धीमे दूसरे चरण के लिए सीखों को कोयलों से ऊपर उठाने की सुविधा, इसलिए ऊंचाई बदली जा सकने वाली ग्रिल इस्तेमाल करें या सीखों को ईंटों पर रखें।"],["सूवला को कितनी देर मैरीनेट करना चाहिए?","कम से कम 2 घंटे, और आदर्श रूप से रात भर फ्रिज में। रेड वाइन, जैतून का तेल, नमक, मिर्च और ऑरेगैनो को मांस के अंदर तक स्वाद पहुँचाने के लिए समय चाहिए; छोटा मैरीनेड सिर्फ सतह को मसाला देता है।"],["क्या मैं पोर्क की जगह चिकन या लैम्ब इस्तेमाल कर सकती हूँ?","हाँ, दोनों साइप्रस में पारंपरिक हैं। हड्डी रहित चिकन थाई के बड़े टुकड़े लें और 60 से 90 मिनट तक पकाएं, या लैम्ब शोल्डर के बड़े टुकड़े लें, जो लगभग पोर्क जितने ही समय में पकता है। वही मैरीनेड और वही धीमी चारकोल विधि रखें।"]]}};
